/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240304-3","meetingId":"r06-c-budget","date":"2024年3月4日","dateIso":"2024-03-04","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を185件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"こんの副委員長","kind":"質問","question":"第４項、款別審査の質疑等についてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含め、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含め、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"おはようあります。歳出予算全般と、８１ページ、商店街ステップ・アップ支援事業についてお尋ねさせていただきたいと思います。最初に、歳出予算全般の減額補正に関連しまして、事務事業評価についてお尋ねさせていただければと思います。しかし、予算の執行状況だけを見て一律での削減をしたいということでは、事務事業評価による予算の削減とは言えないと思いますけれども、お考えを教えてください。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価についてのご質問を頂きました。事務事業評価によります予算削減の考え方といたしまして、前年度決算で不用額が大きい事業につきましては、内容や規模、数量等の見直しを行いまして、予算案に反映させたところです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"予算の執行率だけではなくて、事業の必要性・有効性も勘案して、客観的な評価に基づいた結果によって来年度の予算編成にも活かしたいということは理解できます。その中で確認をさせていただきたいのですけれども、今回の事務事業評価では削減額の結果が非常に注目されていますけれども、改めて事務事業評価の目的を教えていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価は、より実効性の高い施策展開に向けた事業内容の充実や、中長期的な視点からの事業のスクラップ・アンド・ビルドを行っていくなど、事業の不断の検証・見直し・改善等を進め、それを予算に的確に反映させていくマネジメントサイクルを確立させることで。","voiceIndex":11,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"確認","question":"それで、そうした目的を果たしていく中で、全６６５事業の事務事業評価を実施して、一般会計予算の１％、２０億円の財源を捻出されたということですけれども、施政方針においても、中長期的な視点からの施策の検証・見直し・アップデートを図るとのお話が、今、課長からもありましたけれども、こうした削減額の部分だけではなくて。","respondent":"吉岡政策推進担当課長","answer":"委員のご指摘のとおり、行政活動の透明性の向上と説明責任を果たしていく上でも、事務事業評価の結果を分かりやすく周知していくことは非常に重要だと考えておりますので、どのような事業が拡充・改善されたかということなどにつきましても、区民の皆様に分かりやすく示せるよう。","voiceIndex":13,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"せっかく大きな成果だと思いますので、分かりやすいアピールを、ぜひ区民の皆様にも分かるようにご検討していただきたいと思います。要望でお願いいたします。次は、８１ページ、商店街ステップ・アップ支援事業についてお尋ねさせていただきたいと思います。つまり、一件の申請もなかったということだと私は認識しているのですけれども、その原因として何を考えているのかというお尋ねをしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"ただいまのご質問にお答えいたします。８１ページに書いてある事業におきまして、後継者育成支援事業ですけれども、この中で金額としまして、やはり若手経営者たちが企画するようなイベントに使えるような予算になってあります。","voiceIndex":15,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、２件を予定していたのだけれども一件もなかったということだと私は思っております。商店街に対して、当初どのような事業のＰＲをしていたのかというのもお聞きしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"それに加えて２月頃、今年も２月８日・９日に実施しましたけれども、商店街の代表者を集めたような助成金の説明会、制度の説明会というものをやってあります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問","question":"コロナが５類になって、いろいろな商店街でも、お客様が来場されるという中で、今後、補助金が適当に使われるように、どのような事業改善を行っていくのかというのをお聞きしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"こういったものは、全体の説明会だけではなくて、各商店街単位の担当者の方ともいろいろ意見交換、情報交換させていただきながら、一つでも多くのイベントをやっていただいて、にぎわい創出につながるように、また引き続き丁寧にご説明し、支援してまいりたいと考えております。","voiceIndex":21,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ丁寧に説明していただいて、来年度、より一層、商店街対策、活性化に向けて取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"提案","question":"先日の一般質問にて、被災者の負担軽減のため、住民等の利便性の向上や業務の効率化の観点からも、オンラインによる申請受付を提案させていただいたところ、区の見解として、「罹災証明書発行の電子申請を可能とするシステム設定を進めており、早期に電子申請を受け付けることができるように進めていく」とありました。","respondent":"提坂税務課長","answer":"今後、それ以外にも税の申告等、ほかの業務についてもオンライン化を進めていく予定ですけれども、今ご質問のあった罹災証明関連のみならず、様々な公的サービスを受けるための申請業務につきましても、税関連のみならず区全体の業務と連携し、また。","voiceIndex":25,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"迅速に重要性を確認されていることなので、今後さらに進めていっていただければと思います。このぴったりサービスにより、和歌山市や都城市では被災者の個人市民税の災害減免申請もできるようになっています。被災者の罹災証明により受けることができる区民税の減免措置のオンライン化を求めますが、改めて区の見解をお聞きしたいと思います。","respondent":"提坂税務課長","answer":"区民税の申告につきましては、令和７年１２月以降に、オンライン化、いわゆるｅＬＴＡＸと申しますけれども、導入する予定で準備を進めているところです。それに併せて、公的支援に関する減免申請等についても研究を重ねてまいりたいと考えています。","voiceIndex":27,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"令和７年１２月に向けて、さらに力強く進めていただければと思います。続いて、７３ページ、区立保育園費、７５ページ、私立保育園費に関連して、保育園の延長保育についてお伺いしていきます。区では、多様な幅広い区民のニーズや質の向上に向けて、区立保育園の民営化など様々な対策を取られていると思われますが、この点についてお考えをお聞きしたいと思います。","respondent":"立木保育課長、石井保育支援課長","answer":"ニーズの部分に関しましては、子ども・子育て支援事業計画等の中でも今後検討していく内容かと考えています。そうした中で、今後、区立で対応できるかどうかというのは検討してまいりたいと考えています。私立保育園における早朝保育につきましても、やはり子育て負担の軽減というものはとても大事なところですから、補助金の範囲内で実現できるように、各私立園にも呼びかけてまいりたいと思ってあります。","voiceIndex":29,"id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"時代はますます多種多様な働き方が増え、時代に即した対応が必要だと感じています。誰一人取り残さない施策を進めていただきたいと思いますが、今後、区立と私立、連携といったところも、関連を強めていっていただければと思います。再度、改めて区の見解を頂ければと思います。","respondent":"石井保育支援課長","answer":"今後、区立保育園、私立保育園をめぐる状況については、ただいまいろいろ議論していますけれども、これまで以上に、より一層連携を密にしながら、様々な保育ニーズに応えていけるようにしていきたいと考えています。","voiceIndex":32,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"本日から、どうぞよろしくお願いいたします。私からは、６３ページの公共施設整備基金積立金、６５ページの庁舎整備基金積立金について伺います。公共施設整備基金積立金について伺います。同積立金は、令和３年度は４０億円、令和４年度は２０億円、そして今年度、令和５年度は１２億円と、積立金額が減少傾向にあります。当初の工事代金の見積りから、実際に支払った金額は上昇していますでしょうか。","respondent":"遠藤財政課長","answer":"前半の、基金が減っているというようなお話です。令和３年度・４年度は、決算数値ということで確定しておりまして、令和５年度は見込みという形で出させていただいているところです。","voiceIndex":36,"id":"exchange-013"},{"speaker":"山本委員","kind":"意見","question":"要因について理解いたしました。同資金は、公共設備の更新や新規建設における投資負担額の平準化のため、および将来の財政悪化に備えたものとの理解ですが、今後の大型公共施設更新の見通し、その更新に係る資金計画に対する現状の積立金残高の認識についてお教えください。","respondent":"遠藤財政課長","answer":"そちらにつきまして、一方で積立金のところにつきましては現在のいわゆる行政需要というものがありますので、そちらを勘案しながらという形になりますけれども、こちらの部分、積立金が枯渇するようなことのない形で進めているところです。","voiceIndex":38,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問","question":"代表的な事例の大阪万博では、会場建設費が２０１７年当初の１,２５０億円から、昨年１０月には２,３５０億円と、１.９倍に大幅に増加しています。現在の品川区公共施設等総合計画では、大阪万博の当初予算と同じ２０１７年に策定しており、策定当時からは大幅な上乗せが必要となると考えます。積立金目標額の機動的な見直しが必要であると考えますが、ご見解を伺います。","respondent":"吉岡政策推進担当課長","answer":"初めに、委員ご案内の、平成２９年度に策定いたしました公共施設等総合計画につきましては、令和６年度の改定に向けまして、今年度、改定作業を進めておりまして、先月、２月には計画素案のパブリックコメントを実施したところです。","voiceIndex":40,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"今まさにパブリックコメントなどをやりながら検討を進めていくというところで理解いたしました。昨今の状況を踏まえると、より一層の対応が必要、積み増しが必要なのかというところでございまして、民間活力の活用などで、公共施設建て替えに係る財政上の負担軽減に対する工夫が必要と考えますが、併せてこの点についても区のご見解を伺います。","respondent":"吉岡政策推進担当課長","answer":"今、委員からご質問いただきました、施設整備における民間活力の活用につきましては、区としても重要であると捉えておりまして、先ほど申し上げた公共施設等総合計画における方針の中で定めているとおり、引き続き民間活力の活用につきましても幅広く検討いたしまして。","voiceIndex":42,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"来年度以降の策定予算範囲を要望して、次の質問に移ります。次に、庁舎整備基金について伺います。これまでの計画では、令和６年度まで３０億円ずつ積み立てるという方針のようですが、その後の基金の積立て方針の検討状況についてはいかがでしょうか。据置きか、増額するか、未決定の場合はいつ頃決めていくのか、区のお考えをお聞かせください。","respondent":"遠藤財政課長","answer":"今回、金額が変わったというところになりますので、そちらにつきましては改めて検討という形で、今の段階で特に決まっているというものはございません。","voiceIndex":44,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"現状を認識いたしました。国と都の分担金は、持分割合から概算で全体の２割相当としますと、５６０億円の２割の１１２億円で、分担金を除く区の負担金は、およそ４５０億円と考えます。国と都の分担金、国の補助金を除いた時点で、現時点での区の想定負担額はどの程度であるとお考えでしょうか。お考えをお聞かせください。","respondent":"大友新庁舎建設担当課長","answer":"現在、区分所有の割合は調整中ではありますけれども、おおむね、お見込みのとおり、国と東京都の費用負担は２割程度を想定しています。補助金につきましては、防災機能の強化によるものなど、積極的に活用を検討してまいりたいと考えているところです。","voiceIndex":46,"id":"exchange-018"},{"speaker":"山本委員","kind":"提案","question":"２０２２年の区長選挙のときに、私は庁舎跡地活用による庁舎建て替え資金の区民負担軽減を提案しておりましたが、森澤区長もその後、公約に掲げ、現在進めておられます。今後の資金計画について、幾つかご提案申し上げます。将来の不確実性を回避するため、令和６年度から積立金の増額をするのはいかがでしょうか。グリーンボンドの活用に対する区のご見解を伺います。","respondent":"遠藤財政課長","answer":"市場規模が大分大きくなっているような話も聞いておりますので、そういう部分で、今度こちらについては研究を重ねていきまして、進めていきたいと考えているところです。","voiceIndex":48,"id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"建築の進捗や設計がより実現が高まっていくというところによるとは思いますけれども、資金調達を、環境に配慮した取組をしているということを広くアピールする機会とすること、そして発行体として、より有利な条件で効果的な資金計画となるよう、専門家のアドバイスを活用し、より具体的な検討を進めていくことを要望して、私からの質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、８５ページ、下水道管改修事業、また８５ページの不燃化特区支援事業、８９ページの住宅・建築物耐震化支援事業について、耐震化の促進を求めて質問します。上下水道の耐震化です。下水道管改修事業のうち、耐震化推進事業が約５,０００万円の減額となっていますが、その理由を伺います。工事が進んでいないということなのでしょうか。併せて伺います。","respondent":"北原河川下水道課長","answer":"減額の理由についてですが、設計段階の調査の結果等により、既に耐震性を有するなどの理由で、対策が必要な管渠が想定より少なく済んだため、減額補正を行ったものです。必要な箇所に対策を講じているという意味でして、計画が遅れているということではございません。","voiceIndex":52,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"遅れているということではないということで、１つ安心しました。さらに耐震化を進めていくことが必要だと思います。１月１日に発生した能登半島地震でも断水などが発生して、大変な避難生活となっております。上下水道の耐震化の費用というのはどのように捻出されているのか、伺います。","respondent":"北原河川下水道課長","answer":"下水道の費用についてですが、下水道料金、あと東京都の都費、あと国費も投入して事業をしているという認識です。水道については、あまり我々の所管でないところもありますが、水道料金等を投入しているものと認識しております。","voiceIndex":54,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"水道料金から出している。代表質問でも質問をしました。それに対して区は、下水道については２３区で連携して要望しているとの答弁でしたが、本年度から３年分の特別区長会の要望事項を確認してみたのですけれども、下水道の耐震化については、要望項目に記載がありませんでした。区が２３区で連携して要望しているというのは、どういう形で何を要望したのでしょうか。伺います。","respondent":"北原河川下水道課長","answer":"２３区では下水道事業の促進のために特別区下水道事業促進連絡会というものをつくっておりまして、そちらで東京都副知事と、あと下水道局、あと国にも事業の促進について要望しています。","voiceIndex":56,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"促進連絡会で要望しているということで、それは何を要望したのかというところで伺ったので、答えていただければと思います。それと、直近では、いつ要望したのかというところも伺いたいと思います。","respondent":"北原河川下水道課長","answer":"要望の内容についてですが、下水道の浸水対策の促進、老朽化対策の促進、災害・震災対策の促進、あと水質改善に取り組むこと、あと財源を確保することという要望をしておりまして、東京都に関しましては昨年１１月８日に要望活動を行っております。","voiceIndex":58,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々、老朽化・震災対策についても要望されているということで、ぜひここで、さらに公費を投入して進めていただきたいということで、要望していただきたい。やはりそれが、早く進められるということにもつながるかと思うのですが、いかがでしょうか。実際、今、区内の上・下水道の耐震化をいつまでに１００％にする計画なのか、伺います。","respondent":"北原河川下水道課長","answer":"水道についてですが、１００％という計画ではございませんが、短期・中期的な目標を定め、対象施設や地区を重点化するなど、計画的に事業を行っていくものと認識しています。","voiceIndex":60,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"重要なところからやっていくというのは必要だと思うのですけれども、さらにこれを進めていっていただきたいと思うのです。やはり、被害軽減のために耐震化を進めていくということが有効だと思いますけれども、いかがでしょうか。やはり区民生活がかかっているわけですから、区としても早期耐震化を進め、１００％を目指すことを求めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"区内の水道施設や下水道施設の耐震化が早期に進むこととしては、区も重要と考えておりますが、都としても計画的に進めていると認識しておりますので、今後も引き続き情報収集に努めるとともに適切に対応してまいりたいと考えております。","voiceIndex":62,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"その理由と、減額の主な内訳を伺いたいと思います。今回、住宅耐震化と下水道の耐震化の減額で、約１４億円減額になってしまうということで、それを実際、ほかのところに回していただきたいということで、家庭用の太陽光発電・蓄電池システム設置助成が、予算上限に達したために受付終了となっているということで、ぜひそれをしっかり、そこへ回していただきたいと思うのですが、いかがでしょうか。","respondent":"長尾建築課長","answer":"今回の耐震事業での減額の主な理由としましては、緊急輸送道路沿いの改修工事、あとは木造住宅の除却助成の減額となった……。","voiceIndex":64,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"私からは、令和５年度補正予算全般、第１号議案と、昨年末などの分を含めた令和５年度の補正予算と、６７ページの区民保養所経費、品川荘大規模改修設計委託、あと８１ページの中小企業活性化事業費、商店街活性化事業費、また昨年度の省エネルギー対策設備更新助成金について、関連してお伺いいたします。","respondent":"遠藤財政課長","answer":"これまでの補正予算につきましては、いわゆる国からの重点支援地方交付金などもありまして、かなり区民の生活が痛んでいるというところもありまして、そちらの給付と併せて、区で一般財源なども使いながら、いわゆる困っている方たちにどういう給付をしていくかということで。","voiceIndex":67,"id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"国からの分も多かったということなのですけれども、それは具体的に物価高騰などによる経済対策のためということでよろしいのか、改めてその確認と、令和６年度もこうした補正予算、それはその時々によって分からないと思うのですけれども、不確実性の高い時代なので、令和６年度も、現在も経済状況がそこまでいいとは思っておりませんけれども、令和６年度の見通しを、現時点でどの程度お考えなのか。","respondent":"遠藤財政課長","answer":"当初予算でも十分、こちらではいわゆる無償化など、経済対策ではない部分もありますけれども、キャッシュレス決済ポイントなどをやらせていただいて、区民生活の部分について当初から切れ目のないような形で実施させていただいているところです。","voiceIndex":69,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。適宜、対応をよろしくお願いします。それで、区民保養所に移りますけれども、２,６２３万円が減額されておりますけれども、これは一体どのような理由なのか、お知らせください。","respondent":"宮澤地域活動課長","answer":"ただ、保養所につきましては、今後の方向性というのを改めて検討するというところから、工事につきましても施設運営上の維持に必要最小限に絞って執行し、その残額を減額補正したものです。","voiceIndex":71,"id":"exchange-030"},{"speaker":"筒井委員","kind":"提案","question":"今、見直しということもご答弁がありましたけれども、事務事業評価の行政評価シートの７０ページにも最終評価のコメントがありますけれども、それこそ、社会経済動向や民間類似施設に鑑み、施設の必要性や在り方、協定・民間施設の借上げをはじめとする代替手段等について比較検討とありますので、私もそのとおりだと考えておりますので、ご答弁がありましたけれども、改修工事なども。","respondent":"宮澤地域活動課長","answer":"その一方で、施設の老朽化という現状もあります。先ほど答弁しましたとおり、施設維持につきましては必要最小限というところで絞っておりまして、今後の方向性については検討していくです。","voiceIndex":73,"id":"exchange-031"},{"speaker":"筒井委員","kind":"意見","question":"ぜひご検討をよろしくお願い申し上げます。続いて、中小企業活性化事業費、商店街活性化事業費なのですけれども、かなり減額されております。先ほど、商店街ステップ・アップ支援事業についてはご答弁があったので分かりましたけれども、そのほかの中小企業活性化事業費の減額などは、一体どのような理由で減額になったのか、お知らせください。","respondent":"小林商業・ものづくり課長","answer":"この部分につきましては、８１ページに記載がありますとおり、事業承継支援事業です。こちらは中小企業の後継者支援ということで、区として一生懸命やっている事業ですけれども、この中で減額の対象となった部分が、具体的に言うと助成金です。","voiceIndex":75,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。投資について具体的なお話が出なかったということは、先方があまり積極的ではなかったという理解でよろしいのですか。","respondent":"小林商業・ものづくり課長","answer":"ご指摘のとおりでございまして、相談事業やセミナーというのは我々開催しておりまして、こういったものはふだんから相談会等やっておりますけれども、事業承継に合わせて、設備投資も含めて一緒に事業承継をやるというような話が、令和５年度においてはなかったです。","voiceIndex":77,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。設備投資に併せてやるのは、あまりお声がなかったということで、あまりそこまで経営面的に余力がなかったということなのでしょうか。それについて、区の分析をお知らせください。","respondent":"小林商業・ものづくり課長","answer":"ただいま、まず事業承継のほうのご質問ですけれども、設備投資というところに関して、我々もコロナ以前ですと年間１０件程度、設備投資も一緒に併せてやろうというようなお話を頂いていたところですけれども、コロナに入って、やはりこの数字が落ちてきたかと認識しております。","voiceIndex":79,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。予算上、限りはありますけれども、かなり周知を、もう少ししっかり丁寧にやっていただきたいと思っているのですけれども、その点、周知の在り方についてお伺いいたします。","respondent":"小林商業・ものづくり課長","answer":"経営支援窓口の中でも、こういったものが今使えますというようなお知らせもしていただく中で、ではこういうものも一緒に使いたいというようなお声もあったところで、それが当初考えていた３００件を超えるような。","voiceIndex":81,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。それで、フリーランスの方が、例えば電気代がかからないかと言えば、結構クリエイティブな方なので、パソコンなど電気代がかかるということなので、もっと品川区としても、業種を従来型の業種などに絞らないで、新しい多様化の時代ですから、幅広くレンジを広げて、多くの中小企業、個人事業者の方々の支援策をぜひ検討していっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"私からは、６１ページの各種保育利用料、一時保育について、７１ページのすまいるスクール運営費について質問をします。本日は補正予算の項目の中から、すまいるスクールの間食についてお伺いします。この間食の費用について、区と児童側ではどのような負担割合になっていますでしょうか。間食を提供しないＡ登録と、間食を提供するＢ登録およびＣ登録の割合を伺います。","respondent":"藤村子ども育成課長","answer":"Ｂ・Ｃ登録、Ａ登録の割合というところですけれども、すまいるスクールの登録率として、Ｂ・Ｃ登録の割合が現在、全学年で６２.７％という形になっておりまして、Ａ登録全体で見ると、割合としては今。","voiceIndex":85,"id":"exchange-037"},{"speaker":"せらく委員","kind":"確認","question":"間食の負担割合は、全額区で負担していただいているということで確認いたしました。区で全額負担するという考え方をお聞きしたいと思います。質問の意図としては、お伝えしておきたいのですけれども、仕出し弁当を公費で提供してほしいという意図ではないということは先に申し上げします。区費で全額負担していることの考え方を教えてください。","respondent":"藤村子ども育成課長","answer":"区で負担する意図としましては、お子様を６時以降お預かりする際に、おなかがすいてしまったり、少し手持ちぶさたな時間といったところが出てくるかと思いますので、夕食の妨げにならないような簡単な軽食というのをご提供差し上げて。","voiceIndex":87,"id":"exchange-038"},{"speaker":"せらく委員","kind":"確認","question":"対して、その自治体の理事者は、品川区の取組は職員の負担軽減にはなるものの、業者委託ですと、飲料とスナックなどで寂しいメニューになっているということが、確認が取れました。そこで、間食の内容について、児童や保護者などにアンケートやニーズ調査を行ったことがあるか、伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"すまいるスクールでは第三者評価というような評価を外部機関に委託しておりまして、その際に保護者アンケートというのを行っておりますので、間食に限定してではないのですけれども、すまいるスクールの運営の中で。","voiceIndex":89,"id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"しっかりアンケートを、間食に関することではないかもしれないのですけれども、声を聞いていただいてありがとうあります。すまいるスクールの間食委託先の業者のホームページを見てみましたが、３種類のお菓子で１食分とすることが多いと書いてありました。次に、一時保育について伺います。こちらは今回もマイナス補正ということで、内容を伺います。その割合の想定や目標がございましたら教えてください。","respondent":"立木保育課長","answer":"委員がおっしゃられた一時保育に関しましては、現在、ＬＩＮＥで利用の申込みができるようになってあります。利用割合につきましては、今、正確な数字は出ていないのですけれども、電話ではなく、ＬＩＮＥ利用のほうが多く、ほぼそちらになってあります。","voiceIndex":91,"id":"exchange-040"},{"speaker":"せらく委員","kind":"質問・要望","question":"ＬＩＮＥと電話での申請では、ほぼＬＩＮＥのほうだということなのですけれども、目標としてもやはりＬＩＮＥや電子申請のほうをメインに使っていただきたいという思いなのでしょうか。区内でも様々なところでキャッシュレスの対応が進められておりますが、一時保育の支払い方法は、現在は現金のみでしょうか。キャッシュレス対応のご予定はありますか。","respondent":"立木保育課長","answer":"キャッシュレスに関しましては現在できていないのですけれども、キャッシュレスでの収納に向けて、条件整備をしておりまして、今後取り組んでまいる予定です。","voiceIndex":93,"id":"exchange-041"},{"speaker":"せらく委員","kind":"確認","question":"私立保育園では、リフレッシュ、不定期の終了などでも利用できる一時保育を行っているところですが、なかなかホームページ上で情報が確認できず、受入れ園について先日、保育課長、保育支援課長より教えていただきました。こちらの区としての支援の方向性を最後に教えていただけたらと思います。","respondent":"石井保育支援課長","answer":"令和５年度よりリフレッシュでも、私立保育園で一時預かりができるようになりました。当然、多くの方のニーズがありますので、情報提供をホームページ等々で積極的に発信できるように工夫してまいりたいと考えています。","voiceIndex":95,"id":"exchange-042"},{"speaker":"澤田委員","kind":"質問","question":"私からは、５３ページ、第１４款都支出金のうち、８節地域産業デジタル化推進事業費補助金に関連して、品川区のデジタル化の動向について６点ほど質問いたします。そこで、まず企業のデジタル化の動向について伺います。品川区では現在、この補正予算に計上されている東京都の地域産業デジタル化推進事業費補助金などを活用しながら、競争力支援のためのＤＸ、デジタル技術活用推進事業を行っております。","respondent":"小林商業・ものづくり課長","answer":"こうした取組を通じまして、引き続き区内中小企業のＤＸ化あるいは生産性向上、企業競争力の強化というものを進めてまいりたいと考えています。","voiceIndex":98,"id":"exchange-043"},{"speaker":"澤田委員","kind":"質問","question":"経済分野のデジタル化に関連し、続いて商店街のデジタル化についても伺いたいと思います。現在、商店街などの店舗でのキャッシュレス決済が進む中において、品川区では６月１日から６月３０日を実施期間として、区内中小店舗を対象としたキャッシュレス決済ポイント還元事業を予定していますが、こちらの現在の準備状況やスケジュールを教えてください。","respondent":"小林商業・ものづくり課長","answer":"現在、ご指摘のとおり、６月１日から６月３０日までで実施予定ということで、具体的にはａｕＰＡＹ、ｄ払い、ＰａｙＰａｙ、楽天ペイと連携したポイント還元事業ということで実施することとしております。","voiceIndex":100,"id":"exchange-044"},{"speaker":"澤田委員","kind":"質問","question":"５億円を区内事業活性化のために使われるということですけれども、今後さらに商店街のＤＸ、デジタル化が進んでいくと思いますけれども、品川区と同様に他区でも、キャッシュレス決済ポイント還元事業以外に、商店街連合会が発行するプレミアム商品券の発行支援を行っていますが、２３区の中には紙以外の商品券以外にデジタル商品券の発行支援を行っている区もあり、先日の一般質問でも。","respondent":"小林商業・ものづくり課長","answer":"こうした課題を解決するために、デジタル化の円滑な導入に向けて、先行事例の調査分析をきちんと行いながら、紙の商品券との併存なども含めまして、発行主体である商店街連合会との間で具体的な協議を進めてまいりたいと考えています。","voiceIndex":102,"id":"exchange-045"},{"speaker":"澤田委員","kind":"質問","question":"その原因としては、高齢者の方々の中には、スマートフォンを活用したデジタル商品券の対応より、慣れ親しんだ紙商品券のほうが安心して使いやすいという認識があるからとも伺っております。新宿区以外の大都市などでもデジタル対応が必ずしも進んでない状況もあるようですから、品川区においても、仮にデジタル商品券の導入を行った際に同じ状況になることも予想されます。","respondent":"川原高齢者地域支援課長","answer":"参加者は平均で８割以上の高齢者の方にご参加いただいている、大変ご好評いただいている事業です。区といたしましては、スマホ初心者の高齢者に対しての活動を支援すべく、またフレイル予防、社会参加の支援も含めて、今後も実施していく所存です。","voiceIndex":104,"id":"exchange-046"},{"speaker":"澤田委員","kind":"質問・要望","question":"結果として、高齢者の方々のスマートフォン利用が増えることで、今後新しい取組、仕組みが導入された際にも、あるいは品川区の行政サービスの向上にも役立っていくことになると思います。区役所や地域の情報を自由に入手し、買物やクーポンの利用なども使いこなせるように、スマートフォン教室の内容の拡充を求めたいと思いますが、区のお考えをお聞かせください。","respondent":"川原高齢者地域支援課長","answer":"ただし、高齢者のスマホ教室について、令和６年度も新たに教室を拡充して実施するなど、今後も高齢者がスマホに抱く不安感などを払拭しまして、生活の質の向上や介護予防体操なども取り入れながら、楽しく教室に参加いただけるように実施してまいりたいと考えています。","voiceIndex":106,"id":"exchange-047"},{"speaker":"澤田委員","kind":"質問・要望","question":"現在でも個別の要望に対して対応してくださっているということで安心いたしました。最後になりますけれども、先日、小池都知事が記者会見で発表した、東京都独自のデジタル地域通貨プラットフォーム、仮称「Tokyo Tokyo Point」についてお伺いします。","respondent":"横田情報推進課長","answer":"引き続き、東京都あるいはＧｏｖＴｅｃｈ東京の動向を注視しながら、また、区が実施予定のデジタル商品券の状況、他区の動向などを踏まえまして、デジタル地域通貨について検討を進めてまいります。","voiceIndex":108,"id":"exchange-048"},{"speaker":"澤田委員","kind":"質問","question":"今はまだ特に情報の開示などはないみたいですが、今後導入されていくという可能性も踏まえて、それも考えて、ぜひキャッシュレス決済等の準備というものをしていっていただければと思います。私からの質問は以上となります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-049"},{"speaker":"横山委員","kind":"質問","question":"私からは、６３ページ、国際交流推進事業、６７ページ、区民まつり経費、時間があれば７３ページ、児童相談所移管推進事業についてお伺いいたします。１点目に、国際交流推進事業についてお伺いいたします。国際推進事業について補正の理由を簡単にご説明ください。","respondent":"勝亦総務課長","answer":"今回、減額補正していますけれども、国際友好協会への補助金の減額でございまして、内訳といたしましては、友好協会で実施予定でありましたオークランド市からのホームステイの受け入れ、それからポートランド市へのホームステイの派遣が実施できないということで。","voiceIndex":112,"id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"最初の５か年計画で終了することなく、今後も海外大都市の道路管理者との連携・拡大を目指しているということでした。こうした先進的な事例を調査いただきながら、より効果的に多文化共生理解の促進や国際交流事業の前進につなげていただきたいと要望いたしますが、区のご見解をお聞かせください。２点目なのですけれども、区民まつり経費についてお伺いいたします。補正の内容をご説明ください。","respondent":"勝亦総務課長、宮澤地域活動課長","answer":"今後も様々な交流を図っていくために、今頂きましたような情報収集に努めて、国際交流の発展に努めてまいりたいと考えております。区民まつりの減額の理由です。こちらは、新型コロナウイルス感染症対策ということで手指消毒剤を予算計上していたところですけれども、５類移行に伴いまして、執行しなかったものです。","voiceIndex":114,"id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"現在、区内在学の留学生や外国人介護人材、モンゴル高専卒業生から、例えばアンケートなどで多文化共生理解に関する意見をお伺いして、区政に反映したり区内のイベントに協力していただくなど、品川区国際友好協会との連携を深めることのできる機会はありますでしょうか。現状について教えてください。","respondent":"勝亦総務課長、宮澤地域活動課長","answer":"現在、実施しております交流以外にも、文化、スポーツ、教育等、いろいろ様々な交流の形があろうと考えております。次年度につきましても、開催の時期をずらしたり、開催時間を３時以降などに遅くするというふうに検討を進めていると、実行委員会から聞いているところです。","voiceIndex":117,"id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"私からは、８５ページ、水辺利活用事業、８９ページ、しながわ水族館リニューアル経費、ともにマイナス補正でありますので、内容をお聞きしながら、また関連して伺ってまいりたいと思います。初めに、８５ページの水辺利活用事業から伺ってまいります。マイナス６００万円ということでのマイナス補正となっておりますが、理由を含めて内容をお知らせください。","respondent":"北原河川下水道課長","answer":"こちらの事業についてですが、東海橋船着場が東京都の防災船着場に位置づけられておりますが、災害時の夜間に利用するには照度が不足していることから、照明機器および非常用電源機器を整備するものでございまして、照明機器は設置できるものの。","voiceIndex":122,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"内容を確認させていただきまして、マイナス補正とはなったものの、しっかり来年度に行っていくということが確認されました。水辺利活用に関連いたしまして、ここで桟橋の整備について伺わせていただきます。そこで、桟橋の整備について伺います。この桟橋がいつ設置されたのか、また、ここは区有桟橋ではないと思いますので、所有者が誰なのか、経緯等をお知らせいただきたいと思います。","respondent":"北原河川下水道課長","answer":"こちらの桟橋についてですが、民間が設置した非動力専用の桟橋ということで、平成１８年に設置して、現在、１８年が経過していると認識しています。","voiceIndex":124,"id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在、東京都の事業ですけれども、立会川周辺の浸水被害軽減に向けての事業も進んでおり、これからしっかりと整備が進んでいくと、水もきれいになってくる、浸水対策も整えられてくるというエリアになってくると思いますが、人道橋の設置が進んでいる現在、この計画と併せて、この桟橋につきましても、品川区ができることをぜひお取組を頂きまして、改修を視野に入れて検討していただきたいと思いますが。","respondent":"北原河川下水道課長","answer":"今後も地元関係者の意見も伺いながら、また関係部署とも調整を図りながら、適切に対応してまいりたいと考えております。","voiceIndex":126,"id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"具体的にお願いしたいと思います。今日はご発言がありませんが、渡辺議長と共に、またこういうお声も一緒に頂いておりますので、ぜひ推進していただきたいと思います。続きまして、しながわ水族館のリニューアル経費につきまして、こちらもマイナス補正で少し金額が大きいこともありますので、この内容をお聞きいたしまして、スケジュールへの影響を伺います。","respondent":"高梨公園課長","answer":"その後、事業者が決まったことで、設計業務の全体工程が明らかになったことにより、今年度実施する業務の執行見込みに合わせて減額補正をするものです。","voiceIndex":128,"id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"スケジュールへの影響はないということを確認いたしました。皆さんも大変期待しているリニューアルでありますので、着実に進めていただきたいと思います。先ほどは勝島運河の桟橋についてお聞きいたしましたが、しながわ水族館の駐車場方向には、品川区の勝島南運河に区有施設の桟橋がありますので、この桟橋としながわ水族館の関連性について伺ってまいります。","respondent":"高梨公園課長","answer":"現在、基本設計の中で、具体的な動線等々を検討していますが、やはり今の水族館からすると裏手側のように見えてありますので、リニューアルに際しましては、訪れる来館者の皆様に。","voiceIndex":130,"id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。昨年、建設委員会で議会報告会をさせていただきましたときに、水族館リニューアルをテーマにいたしました。たくさんのご意見を頂きました。併せて、区民の声をどのように反映させていただけるのか、お伺いいたします。","respondent":"高梨公園課長","answer":"そのためには、やはり区民の方からもしっかり誇りと思える水族館としたいと考えてございまして、現在の水族館でも区民アイデアを基に展示のアイデアを取り入れていますけれども、新しい水族館においても、区民から展示についてのアイデアを募集して、それを展示に活かし。","voiceIndex":132,"id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私も今年１月に施設の見学に伺いました。先日配付された行政評価シートを見ますと、専門職を８０人確保するのが目標で、既に５５人確保しているようですが、専門職とはどういった方々でしょうか。１０月開設までケース引継ぎで、現在ある東京都品川児童相談所に職員を派遣して引継ぎに当たるとお聞きしましたが、現在の施設からの職員の異動はないのでしょうか。以上、４点お伺いします。","respondent":"長谷川児童相談所開設準備課長","answer":"続きまして、医療的ケアの子どもの対応につきましては、児童相談所の一時保護所においては、専門的な治療を行う職員あるいは体制というものが整っておりませんので、そういった場合には障害児施設等の利用を検討するといった状況です。","voiceIndex":136,"id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問・要望","question":"続いてお聞きします。保護される子どもの背景には、様々なケースや難しいトラブルがあると思いますが、保護される子どもの定義とはどのようなものでしょうか。子どもや家庭の相談を受け付ける手順や、問題解決のためのケース管理プロセスなどはあるのでしょうか。最後に、様々な深刻な問題に直面する職員の方の心理的な負担に対してのケアは、どのように考えられているのでしょうか。以上、３点お願いします。","respondent":"長谷川児童相談所開設準備課長","answer":"子どもやケースへのプロセスといったところに関しましては、様々な通達のほか、児童相談所の運営指針というものを国が発出しておりますので、その中の手順に沿って対応することになろうかと思いますが。","voiceIndex":138,"id":"exchange-060"},{"speaker":"おぎの委員","kind":"質問","question":"昨今、全国各地で悲しい児童虐待の報道を目にします。今回は品川区独自の児童相談所開設ということで非常に注目されています。どうぞよろしくお願いします。続きまして、河川管理費についてお聞きします。今回、補正予算で河川管理費は全般的に下がっています。事業見直しや変更などでしょうか。様々な理由があると思いますが、まずは理由をお聞かせください。","respondent":"北原河川下水道課長","answer":"減額になった主な原因ですけれども、主には、目黒川でしゅんせつ工事、支障物撤去工事を行おうと当初予算時に考えていたのですが、建設局が行う工事と競合したため、規模を縮小して実施した等の理由によります。","voiceIndex":140,"id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問","question":"立会川の水質浄化機器運転費が、令和４年度にリースから買取りになったと資料にありましたが、そういった変更はよくあるのでしょうか。水質浄化の状況についてお聞かせください。","respondent":"北原河川下水道課長","answer":"水質についてですけれども、これを設置した平成２０年以降、水質がある程度保たれていることからも、効果があるものと認識しています。","voiceIndex":142,"id":"exchange-062"},{"speaker":"おぎの委員","kind":"質問・要望","question":"目黒川、立会川、どちらも東京湾に注ぐ最後のところが品川区になっており、上流域の区や東京都にも様々な協力を仰ぎたいところですが、水辺のまち、品川区として、区でできることを根気よく続けていっていただきたいと思います。質問は以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-063"},{"speaker":"えのした委員","kind":"質問","question":"私からは、７５ページのベビーシッター利用支援事業についてお伺いします。こども家庭庁は先月、２月１３日、企業の従業員向けのベビーシッター券７０万枚を発行。割引券１枚２,２００円で、２０２４年度予算の１.８倍だと話題になりましたが、品川区でも未就学児の一時預かり利用支援、ベビーシッター利用支援事業を実施しており、子育て支援は区としてもとても重要な施策です。","respondent":"石井保育支援課長","answer":"本事業は、日常生活上の突発的な事情やリフレッシュ等の目的により一時的に保育が必要となった保護者などに対して、ベビーシッターの利用料の一部を助成して経済的な負担軽減を図るものです。令和４年度より、東京都の補助を受けて実施しています。","voiceIndex":146,"id":"exchange-064"},{"speaker":"えのした委員","kind":"質問","question":"そこでお伺いします。令和５年度の予算が４,５００万円で、補正予算が１億７,１２０万円と、３.８倍以上の補正予算になっておりますが、当初予算の考え方をお知らせください。","respondent":"石井保育支援課長","answer":"令和５年度当初予算の算定に当たっては、令和４年度前半部分の実績に基づいて４,５００万円としています。実際には令和４年度年度後半の伸びが著しく、令和４年度は１７０名程度の目標を掲げておりましたが、実に１,０００名以上のご利用がございました。","voiceIndex":148,"id":"exchange-065"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認が取れました。当初は１７０名程度の見込みが、５.８倍以上、１,０００名の利用と、実績やニーズの高さが伺えました。東京都に対して予算要望はされているのか。されていない場合は要望いたしますが、区のご見解をお知らせください。","respondent":"石井保育支援課長","answer":"東京都が本事業を終了した場合については大変な財政負担となってしまうため、区としても、特別区長会が取りまとめております令和７年度東京都に対する予算要望事項として上げさせていただいているところです。","voiceIndex":150,"id":"exchange-066"},{"speaker":"えのした委員","kind":"質問","question":"ぜひ、引き続き東京都の予算の確保に期待しております。続きまして、ベビーシッターの確保についてお伺いします。実績を踏まえると、ベビーシッター利用支援は非常にニーズが高まっておりますが、ベビーシッターの人数は現状足りているのでしょうか。育成や増員も含め、現状と方向性をお知らせください。","respondent":"石井保育支援課長","answer":"東京都にも確保策について確認させてもらっていますけれども、本事業に従事できるベビーシッターの増員に向けて、例えば夜間や土日も含めた研修の実施などを柔軟に行う等、確保策に努めていると聞いてあります。","voiceIndex":152,"id":"exchange-067"},{"speaker":"えのした委員","kind":"質問・要望","question":"区民の方から十分でないとのお声があるとのこと、研修の実施も含めて優秀なベビーシッターの育成と増員を要望いたします。全て利用すると、これは午前中の上限を１時間２,５００円として年間３６万円の補助。このような現場の背景を踏まえて、病児保育施設にとらわれずに、ベビーシッターも含めた様々な預け先を進めていくことが重要だと考えますが、区のご見解をお知らせください。","respondent":"石井保育支援課長","answer":"本事業に関しましては、そういったベビーシッターの事業者にも活用していただけるものですので、区としてもこういった助成を利用していただけるようにＰＲしてまいりたい。そういう中で、病児保育施設に限らず、様々なニーズにお応えできたらと考えています。","voiceIndex":154,"id":"exchange-068"},{"speaker":"えのした委員","kind":"質問・要望","question":"ご説明ありがとうございました。病児保育施設の設置、また本事業のＰＲの拡充も要望します。先日、地域の保護者の方から、「ベビーシッター利用支援事業を、子どもが小学生になってから知りました。共働きで、お互いの両親も区内在住ではなく、何かあった際に気軽に子どもの預け先がなく大変苦労した。周知方法についてお知らせください。","respondent":"石井保育支援課長","answer":"現在、区のホームページや各種刊行物、しながわこどもぽけっと、産後ドゥーラなど、連携した周知を行ってあります。妊娠届を出された方向けに、ご案内のリーフレットの配布等もしています。","voiceIndex":156,"id":"exchange-069"},{"speaker":"えのした委員","kind":"確認","question":"妊娠届出のタイミングなど、周知・啓発されているとのこと、確認が取れました。昨年の１０月２０日ですか、妊娠・子育て中の保護者と小中高生の子どもたちを対象にした新しいアプリ、しながわこどもぽけっとも配信されており、私も確認しましたが、大変評価しております。人材バンク、人材マッチングアプリ等を利用した仕組みづくりはどうお考えでしょうか。ご見解をお知らせください。","respondent":"石井保育支援課長","answer":"そういった状況も踏まえまして、まずきちんと指導・監督できるような体制を整えていくことが肝要だと考えています。","voiceIndex":158,"id":"exchange-070"},{"speaker":"えのした委員","kind":"意見","question":"先ほどもありましたが、児童相談所が開設された後は、国からも指導・監督権限が下りてくるので、そういったことを踏まえて対応していただければと思います。区内に待機型として拠点があれば、保護者の異動があっても、コストを抑えた病児保育、保護者の自宅療養が可能になるのではと考えますが、区のご見解をお知らせください。","respondent":"石井保育支援課長","answer":"待機型の拠点施設といったニーズ等もあるところですけれども、例えば実施スペースの確保や、あと、そもそもやはり先ほども申し上げたとおり、ベビーシッター全体の確保といったことで課題があると考えていますが。","voiceIndex":160,"id":"exchange-071"},{"speaker":"えのした委員","kind":"質問・要望","question":"そうですよね。スペースの確保にベビーシッターの確保等、様々な課題があるようですが、一つずつ丁寧な課題の解決を期待しております。区民の方への安心安全な保育、また子育ての負担を軽減できる事業の安定と拡充を要望して、私からの質問を終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"８９ページの応急活動対策費に関連して、災害時のペット同行避難および同伴避難、そしてキッチンカーについて伺いたいと思います。能登半島地震を含めて多くの災害を通じて、防災対策の強化はスピード感が必要だと思います。新年度予算では様々示されておりますが、直ちに活かすという姿勢や具体化について、最終補正で追加は考えられなかったのか、伺いたいと思います。","respondent":"平原防災課長","answer":"能登半島地震で明らかになった課題などに対する事業につきましては、今、委員がご指摘のとおり、令和６年度当初予算案に計上させていただいたところです関係で、今回の補正で特に追加支出ということは考えていないところです。","voiceIndex":164,"id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"ワンちゃんを飼っている飼い主から、首都直下型地震のときのワンコとの避難生活がとても不安だと切実に訴えられました。自宅が倒壊し、避難生活となる中、ワンコをどこかに置いて自分だけ避難生活など考えられない。そこで、パンフレットの作成や品川区ホームページの充実を求めますが、いかがでしょうか。ペット防災計画がなぜ進まないのか、課題が何か、伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"そちらに関しては区としても認識しています。来年度予算につきましては、ペットを飼われている方、飼われていない方も安心して避難生活が送れるように、ペット防災、ペット同行避難に必要な備蓄というものも進めてまいるというところで、今計画しています。","voiceIndex":166,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"私も話を伺いましたが、例えば家の中でも、玄関先で知らない人や物音がするだけで警戒するので、多くの方が行き交う避難所で過ごせるのか不安で仕方がない。能登では犬は外だった。やはり、一つ一つの声に対して、どう向き合っていくのか。様々な問題を整理して、例えば審議会なども立ち上げて、本格的にペット支援を体系立てて作成していただきたいと思いますが、改めていかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"ペット同行避難に対する今後の対応についてですけれども、地域の皆様の意見を十分お伺いしながら体制を進めてまいりたいと思います。","voiceIndex":168,"id":"exchange-075"},{"speaker":"中塚委員","kind":"提案","question":"地域の理解、動物やペットが苦手な方の理解も必要だと思います。私は、保護犬の活動や被災地支援を行っているドッグトレーナーとの意見交換を提案したいと思います。既に獣医師会との意見交換はされているかと思いますけれども、こうした災害時の計画について、ドッグトレーナーとの連携も位置づけて、ペット支援を具体的に進めていただきたいと思いますが、いかがでしょうか。","respondent":"舩木生活衛生課長","answer":"そうした中で、もちろんペットとの災害対策になりますと、犬もそうですし、犬以外の猫や、ほかの小動物もおりますので、例えば犬につきましては、確かに犬の特性や習性などをよく知っているドッグトレーナーの活用といったところもありますし。","voiceIndex":170,"id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、いろいろ進めていただきたいと要望したいと思います。最後に一言、キッチンカーについての活用についても伺いたいと思います。ぜひキッチンカーの活用を、防災計画、防災対策に位置づけていただきたい。地域防災計画にも反映していただきたい。例えば災害協定を結ぶなどの具体化がよいかと思いますけれども、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"キッチンカーについてのご質問です。今般の能登半島地震におきましても、温かい食事、栄養のある食事というところで、課題が出てきたところです。区といたしましても、様々、飲食業界の方と協力・連携して、そういった食事が提供できるように進めてまいりたいと考えております。","voiceIndex":172,"id":"exchange-077"},{"speaker":"ひがし委員","kind":"質問","question":"本日はよろしくお願いいたします。私からは、ページは前後しますが、６９ページ、自立支援給付事務の中の重度訪問介護について、そして７１ページのすまいるスクール運営費についてお伺いいたします。今回の補正予算において、自立支援給付事務に３億２,３４８万４,０００円の補正がついています。その中でも、重度訪問介護が１億７,５５６万円と多くの割合を占めています。","respondent":"松山障害者支援課長","answer":"私からは、重度訪問介護の増額の理由につきましてお答え申し上げます。当初、前年度実績の利用者３５人を見込んでおりました。それが、令和５年１２月末で利用者は５人ほど増加し、４０人となっております。","voiceIndex":175,"id":"exchange-078"},{"speaker":"ひがし委員","kind":"質問・要望","question":"障害者福祉計画における見込量の算出方法について改めて伺います。グループホーム整備についても進めてほしいと願う一方で、グループホームの整備だけではなく、在宅で過ごしたいと願う方々に対する支援、訪問介護等についても、サービスの向上に努めていただきたいと思いますが、在宅介護に対する今後の展開、区のお考えについてもお聞かせください。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"サービスの見込量は利用量の上限値を示すものではありませんので、実際の個別支援におきましては、個別の状況に応じて必要なサービスを提供いたします。在宅支援についての区の認識と今後の展開についてお答え申し上げます。区といたしましては、地域で安心して生活するためには、在宅で必要な支援を受けられることが重要と考えております。","voiceIndex":177,"id":"exchange-079"},{"speaker":"ひがし委員","kind":"質問・要望","question":"見込量は、数年の実績の平均値を出している、また少し多いほうを取っているということで、その点を踏まえて確認してみると、令和３年、令和４年が大体、利用時間数が４,３９３時間と４,４７５時間。そして、令和５年が少し増えています。予算や実績と計画が連動するように、今後の計画の際には見込量の出し方について再検討していただければと思いますが、区の見解をお聞かせください。","respondent":"川崎障害者施策推進課長","answer":"これは、２３区、どの自治体も同じような方法で取ってはいるのですけれども、やはり実際の個別支援において、実績等を見ながら、またニーズに応じて、今後十分な支援量が提供できるように、体制は整えていきたいと考えております。","voiceIndex":180,"id":"exchange-080"},{"speaker":"ひがし委員","kind":"質問","question":"区民の方々がこの見込量を見て、何か不安だ、サービスが減らされるのではないかというところ、先ほどからご答弁いただいていますけれども、そういうことではなく、きちんと予算もつけるし、介護のところも力を注いでくれると理解いたしましたが、改めて、その見解で間違いないでしょうか。","respondent":"松山障害者支援課長","answer":"委員がおっしゃいます、区民の方のご不安な気持ちは受け止めております。今後、策定予定の障害福祉計画の見込量を、事情が変わって超えたとしても、個別支援の中では必要なサービスについては支給してまいりますので、引き続きご安心してご利用いただければと考えています。","voiceIndex":182,"id":"exchange-081"},{"speaker":"ひがし委員","kind":"質問・要望","question":"居宅介護訪問、重度訪問介護についても、支援についてさらに体制を整えていただければと思いますし、先ほどから言っていますように、見込量というところも、実績、また予算と連動させるような形として示していただければ、区民の方々も安心、そして実績・予算ともに差異がないような形になるのではないかと思いますので、この点について改めて要望します。次のすまいるスクール運営費について質問いたします。","respondent":"藤村子ども育成課長","answer":"仕出し弁当はアレルギー対応を行わないというところですけれども、実際には、アレルギー対応までカバーしているお弁当の業者が見つからないというところが大きな要因です。","voiceIndex":184,"id":"exchange-082"},{"speaker":"ひがし委員","kind":"意見","question":"私はもともと看護師をしていたので、衛生の面やアナフィラキシーショックの件など、すごく気になるので、その点について聞きたいと思っているのですけれども、その前に運営の体制について幾つか気になる点があると、また区民の方からも聞いております。すまいるスクールのスタッフが、ここに２名増員となっているのですけれども、この経緯についてもお聞かせいただければと思います。","respondent":"藤村子ども育成課長","answer":"お届けの場所なのですけれども、今回、第一日野小学校で試行実施した際は、ランチルームにお届けということだったのですけれども、こちらは、学校によってはどういったところにお届けするかというところは異なってくると思いますが、こちらは児童が口にするものですので。","voiceIndex":186,"id":"exchange-083"},{"speaker":"ひがし委員","kind":"確認","question":"その責任の所在というところです。この委託のところにかかってくるのか、学校側なのか、区なのかというところも気になるというようなご意見がありましたので、併せて伺えればと思います。","respondent":"藤村子ども育成課長","answer":"間違ってお弁当を食べてしまった際の対応というところ、およびアレルギーが出てきてしまった際の対応というところですが、こういったケースに限らず、例えばすまいるスクールでけがをしてしまったなどといった際には、保護者の方に連絡する、学校に連絡する。","voiceIndex":188,"id":"exchange-084"},{"speaker":"ひがし委員","kind":"確認","question":"昨年１１月に行われた文教委員会の資料、議事録も確認しましたが、仕出し弁当を食べている方と食べていない方の部屋が分かれているなどという議事録も見まして、その対応、せっかく一緒に食べられる機会なのに分けてしまうというのもどうなのかと思ったのですが、その点について、区としてどのような対応を検討しているのか、聞かせていただければと思います。","respondent":"藤村子ども育成課長","answer":"加えまして、部屋が分かれているというところなのですけれども、こちらは、アレルギーといったところを考慮して、しっかりやっていくために部屋を分けたところですので、今後実施していく中では、一緒に食べられたほうがというところはありますので。","voiceIndex":190,"id":"exchange-085"},{"speaker":"つる委員","kind":"質問・要望","question":"３８ページ、特別区民税、特別区財政調整交付金、７５ページ、ベビーシッター利用支援事業について、関連して伺っていきたいと思います。特別区民税につきましては７億円の補正ということで、近年ずっと税収増が続いてきております。現状も含めて教えてください。ただ、その先につきましては、さらに品川区にとっても納税義務者になっていただきたいですし、地域においては担い手になっていただきたい。","respondent":"遠藤財政課長","answer":"現役世代へのですけれども、今回、子育て支援ということでお話を頂いて、その後、１８歳以上というような形になりましたけれども、お子さんの支援というのは言わば現役世代への支援というところと両輪という形になりますので、今回の部分についても。","voiceIndex":193,"id":"exchange-086"},{"speaker":"つる委員","kind":"提案","question":"これは、代表質問等でもいろいろ引用していますが、教育、医療、介護などの、人間が生きていく上で不可欠なサービスを全て無償化していくという方向性を、党としては志向・検討しているという状況があるわけでありますが、そうしたところもぜひ参考としながら、公明党としても自治体における政策提案等も今後していく予定もあろうかと思いますので、その際はぜひ積極的に参考にしていただきたいと思います。","respondent":"佐藤企画課長","answer":"様々なご質問を頂きました。順番にお答えすると、まず委員がご紹介の家庭での労働の捉え方と支援策というところで、国で定期的に調査しておりまして、女性が７７.５％、男性が２２.５％というところで、女性の比率のほうが圧倒的に大きいというところです。","voiceIndex":195,"id":"exchange-087"},{"speaker":"つる委員","kind":"提案","question":"現状、様々な形でしんどい状況が、本当に今、心の部分やメンタルのケアなどの施策も大きく拡充してきているわけでありますけれども、どんなしんどい状況にあっても、品川区が背中をぽんと支えてくれて、共にこの歩みを進んでいけるような、そして一歩前進していけるような勇気もともに与えていけるように、施策展開を令和６年度もしっかりと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":197,"id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私からは、５８ページ、ふるさと納税と、６２ページの広報広聴費と、行ければ６９ページの重度訪問介護でお願いします。ふるさと納税です。これを踏まえて、今回、１,５００万円から補正で１,６２９万円、そして次年度は９,０００万円を予定しておりますけれども、この流れについてどのような経緯といいますか、どういった見込みで算出されていますでしょうか。内訳を教えてください。","respondent":"提坂税務課長、飛田子育て応援課長","answer":"補正の部分は、子どもの未来応援事業の分が増額になっているということで補正を組んだと認識しております。こちらに載っています１,６２９万８,０００円の充当ですが、これは子どもの未来応援事業ということでガバメントクラウドファンディングを行いまして、そこで予想を超える多大なご寄附を頂いたということです。","voiceIndex":199,"id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"区内のところから、いろいろと今、相談というか、お話をしているということで、ぜひ私からも、体験型の、品川区にぴったりのアイデアがあるので提案したいと思います。皆さん、今、一番稼いでいると言われている芸人、つまり一番人気があって勢いのある芸人をご存じでしょうか。これは、コンビのうちの一人の森田哲矢さんは、１０年ほど前に関西から東京に進出してきまして、五反田にずっと住んでいます。","respondent":"提坂税務課長","answer":"今ご提案の芸人の部分については認識不足で申し訳なかったのですけれども、その辺をいろいろと、どんなものか調査させていただいて、返礼品としてふさわしいものかどうかということを、研究を重ねてまいりたいと思います。","voiceIndex":202,"id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"品川区はケーブルテレビ品川の主要株主となっておりまして、様々なイベントの動画撮影など、ケーブルテレビ品川が入って放送されていると思うのですけれども、例えばイベントの最中に、参加者、議員か何かは分かりませんけれども、もし問題発言や報道があって、それを確認したいというようなことが発生した場合、例えば区議会として、そういったものを確認というようなことを。","respondent":"辻広報広聴課長","answer":"区は、撮影を依頼しまして、できた納品物はこちらに納品していただくということで、その後は場合によってはご相談に応じてできる場合もありますし、その前の状態ですと、まだ完全作品ではないので、ケーブルテレビで難しいという場合もあるかと思います。","voiceIndex":204,"id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"確認","question":"できる場合もあるということで安心しました。やはり、何か問題が起きたときに、議会として確認して、声明を出したり処分を行ったり、いろいろそういった事実確認も必要になる場合もあります。","respondent":"久保田企画部長","answer":"メディアのいろいろな規制がありますので、そういったことに対しての対応は、やはり難しいところがあるのではないかと考えております。","voiceIndex":206,"id":"exchange-092"},{"speaker":"せお委員","kind":"質問","question":"私からは、７９ページ、出産・子育て応援事業についてお伺いします。出産・子育て応援事業は、妊娠期から出産、子育てまで支援していく事業ですが、こちらに対して１億６,６００万円余の減額補正となっています。この減額補正のご説明を、まずお願いいたします。","respondent":"若生健康課長","answer":"この電子クーポンが、実際には予算執行のタイミングとしては、個々の利用者が実際に専用サイトでクーポンを使用して、それの使用が事業者に行きまして、取りまとめて、遅れて区に請求が来るという仕組み上の問題で、当初の数か月は請求がなかったものですから。","voiceIndex":209,"id":"exchange-093"},{"speaker":"せお委員","kind":"確認","question":"理解できました。ということは、妊娠・出産している人がかなり減ったとか、申請している人がすごく少ないなどということではないという理解でよろしいのか。そこだけ確認させてください。","respondent":"若生健康課長","answer":"実際に見積もっている妊娠届出数や出産数というのは、そこまで落ち込んでいるわけではございませんで、実際に申請者が漏れているかというところについては、ほぼほぼ、これはギフトの申請は来ている、一部。","voiceIndex":211,"id":"exchange-094"},{"speaker":"せお委員","kind":"質問","question":"そこで、おむつ宅配との関連です。おむつ宅配も、いろいろな議員がおっしゃっていますけれども、委託ではありますが、保健師、助産師、看護師などの専門職が訪問すると伺っています。まだまだ始めたばかりなのですが、始めてみた中で、改めて出産・子育て応援事業との役割分担をどのように考えていますでしょうか。こちらも併せてお聞かせください。","respondent":"石橋品川保健センター所長","answer":"見守りおむつ定期便につきましては、本年度１１月から開始したばかりの事業となりますので、今後、事業の効果を検証してまいりたいと考えております。こちらの両方の委託事業としましては、まず委託の指導員・支援員が訪問します。","voiceIndex":213,"id":"exchange-095"},{"speaker":"せお委員","kind":"提案","question":"保健所関連、こういったところ全体の業務整理、切り出しや業務委託というのは、私も以前から提案してきているのですけれども、コロナを経験して、そして新たな出産・子育て応援事業とおむつ宅配も加わったことも含めて、改めて、働き方の現在の状況と考え方を教えてください。そこで、庁舎以外の現場に出向くような、もちろん保健師もそうですし、主に専門職の方々の状況はいかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"保健師以外でもできる業務は、ほかの職種で対応するなど、または委託化するなど、各所で適した事務分担を行い、職員の負担軽減に努めてまいります。","voiceIndex":217,"id":"exchange-096"},{"speaker":"安藤委員","kind":"質問","question":"最終補正予算における基金の積み増しは、財政調整基金や公共施設整備基金、庁舎整備基金、義務教育施設整備基金ということで、合計、何と２８億８,０００万円余ということになりますが、上りますけれども、最初に伺いたいのは、うち、区の裁量で自由に使える財政調整基金ですが、この最終補正での積立額、あと当初予算では当初何円積み立てる予定だったのか、伺いたいと思います。","respondent":"遠藤財政課長","answer":"基金の積立てのお話ですが、まず令和５年度当初では積んでおりません。ゼロ円という形になります。今回、補正予算ということで、既にこれまでの補正予算で１１億円ほどを使って、それぞれ補正予算をさせていただいているところです。すみません。","voiceIndex":220,"id":"exchange-097"},{"speaker":"安藤委員","kind":"質問","question":"当初予算では２,２００万円余だったのですけれども、最終補正では約９億５,０００万円ということになっております。追加補正で執行すべきだったのではないでしょうか。１点、伺いたいと思います。併せて、今年度の当初予算に組まれていたもので、年度途中に予算が足りなくなってしまって、補正予算で区に追加して予算化した事業などには、どんなものがあるのでしょうか。伺いたいと思います。","respondent":"遠藤財政課長","answer":"追加でやるべきではなかったかというところですけれども、これまでの補正予算の中で、今回、最終補正ですので、期限が短かったりというところで、なかなか新規や、あるいは途中でスキームを変えるというのは難しい部分があります。","voiceIndex":222,"id":"exchange-098"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、途中でもう足りなくなって、区民から求められている事業もあったわけですが、そういうことはやらないで、結果的には２８億円、貯金に回しましたねということなのです。ですから私は、必要なら機動的に組むべきだったと思います。年度途中で補正予算を組むもの、組まないものの判断基準というのはどうなっているのでしょうか。改めて伺います。","respondent":"遠藤財政課長","answer":"年度途中で足りなくなった部分というところでの追加の部分ですけれども、今回、最終補正の中で、いわゆるプラスになっている、積み増しているものについては、基本的に今回、足りなくなっているというものがほとんどだと考えているところです。","voiceIndex":224,"id":"exchange-099"},{"speaker":"安藤委員","kind":"質問・要望","question":"不十分だと私は思います。区内の建設業組合も、予算に向けた要望書で、昨年度は４,８００万円の予算額に対して、助成件数２９１件、助成額５,０９６万円と、大変好評な結果となったと。伺いますけれども、住宅改善工事助成事業について、これが区内経済の循環や活性、また中小・零細建設業者・個人事業主支援の点で、区はどのように評価しているのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"住宅改善工事助成についてお答えします。本事業ですが、区内の住環境の整備および区内事業者の振興を図ることを目的としており、着実に実績を上げ、一定の成果を上げているところです。区内事業者の振興にも十分役立っていると考えております。","voiceIndex":226,"id":"exchange-100"},{"speaker":"安藤委員","kind":"質問","question":"非常に重要だと。特に区内事業者は本当に今、大変な中でいますから、大変重要な事業だという評価だと思います。今年度予算にも、当初予算には、２１２件で５,２００万円の予算が組まれていました。伺いますけれども、今年度を含む直近３年間の当初予算額と、予算切れでこの事業が終了してしまった、もう受付もないですという日にちについて、それぞれ伺いたいと思います。","respondent":"竹田住宅課長","answer":"令和５年度の当初予算額が、４００万円増額いたしまして５,２００万円となっています。それから、新規受付終了日ですが、令和３年度が１２月２４日、令和４年度が１０月２８日、令和５年度が１０月６日となっております。","voiceIndex":228,"id":"exchange-101"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは年間を通しての事業のはずなのですけれども、この３年間を見ても、年内に全て終了してしまっている。ですから私は、一方で基金に、４つの基金で２８億８,０００万円積んでしまっている結果になりました。その場合というのは、これまでの教訓を活かして、希望者が全員助成を受けられるように、必要な補正というのをタイムリーに組んでいただきたいと私は思うのですけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"令和５年度は、前年度の４,８００万円に比較しまして４００万円増額しまして、５,２００万円となっております。毎年、着実に当初予算を増額し、当初予算を着実に執行しておりますので、今年度では補正予算は考えておりませんでした。","voiceIndex":230,"id":"exchange-102"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、新年度予算の額が増えたというのは評価しているのですけれども、そうではなく、伺ったのは、それでも足りなくなった場合に、機動的に補正予算なども組む必要があるのではないですか、そのような考えを持っていただきたいと思うのですけれども、いかがでしょうかという質問ですので、お答えください。","respondent":"竹田住宅課長","answer":"この事業は、令和６年度予算におきましては、対前年比１,３００万円増の６,５００万円をご提案しています。なお、本事業は耐震性を高める工事にもご利用いただけますので、本事業を通じて安全安心な快適な住環境の促進に向けて尽力していきたいと考えております。","voiceIndex":232,"id":"exchange-103"},{"speaker":"安藤委員","kind":"質問","question":"もう、すばらしい事業について、本当にすばらしい事業だということが繰り返し語られているわけです。であるならば、私はなおさら、それが、しかも様々な面で、命も守る、防災にも寄与する、区内事業者の支援、区内経済循環ということで、様々な効果があるわけですから、ぜひそういった柔軟な対応を今後お願いしたい。一般会計補正予算に反対を表明して質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-104"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、６８ページ以降の民生費、衛生費の中での感染症対策について、６３ページ、広報広聴費について、７３ページですか、子育ての中で、午前中にオアシスルームの予約のところでＬＩＮＥヤフーの話が出たので、その件についてお伺いしていきます。こういった事例があったときに、どのような対応をされているのか、また対応・対策についてどのような基準があるのか、教えてください。","respondent":"坂野保健予防課長、辻広報広聴課長、崎村人事課長、佐藤経理課長","answer":"これが去年の５月７日までで、５月８日から５類になったので、１１か月分ぐらいがなくなったというので、この減額の額となっております。広報広聴課の人件費についてのお尋ねかと思います。こちらは、年度途中で育休等が出まして、その分が、会計年度ではなくて……。広報広聴課の職員給与費の増になりますけれども、まず職員給与費の当初予算の段階では。そういった場合、国の機関あるいは東京都がどういった処分をするかということを見ながら、あるいは２３区内のほかの自治体等の動きを見ながら。","voiceIndex":236,"id":"exchange-105"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"国は全体的に見てそれを判断するのですけれども、区というのは小さなコミュニティで動いているので、そこではどうしても、５類に移ったからといってというのがどうしても出てくると思うのです。これは要望で終わります。広報広聴。これは、ハッシュタグがいろいろ書いてある。なので、情報に対してはやはりもう少し徹底していただきたいと思いますが、改めてその辺のお考えを教えてください。","respondent":"辻広報広聴課長、立木保育課長","answer":"今回の自殺対策のところですが、そこが少し足りないといいますか、確かに議員がおっしゃいますように、心に何か抱えている方がそれを見て、では次にどういう行動を起こすのかということが。午前中にお答えしました一時保育の関係の件で、ＬＩＮＥというお話をさせていただきましたけれども、こちらは補足になるのですが、令和４年度までがＬＩＮＥで、現在は区の電子申請システムに乗り換えてあります。","voiceIndex":241,"id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問","question":"個別の案件について言っているのではなくて、それぞれ、ＬＩＮＥという話でもないのです。様々な会社と、企業と、団体と、いろいろな契約をしている中で、向こう側、相手先の事情があったときに、どういう対応を取っているのですか。何もなかったというのだったら、何もなかったでいいのですけれども、では取っているのか、取っていないのか、まず教えてください。","respondent":"佐藤経理課長","answer":"それを受けて、区も指名停止等の処分をするというような形で対応しております。所管はそれぞれ各事業者と事業をやっておりますので、その範囲で確認していると認識しております。","voiceIndex":244,"id":"exchange-107"},{"speaker":"石田（し）委員","kind":"確認","question":"今日はここまでにしておきますけれども、これは追及するので、ぜひきちんと確認しておいてください。私が言っているのは、契約されている方たちに何かあったときに、どういう対応をしているのか。今回、例を挙げて、ある特定の企業の名前が出ましたから私は言っただけで、そうではなくても、どこかと何かの契約をしているのだから、そのときにそういった対応をどうやって行っていくのかと私は聞いている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-108"},{"speaker":"塚本委員","kind":"質問","question":"私からは、ページ７９の各種がん検診、それからページ８９の給水体制整備費、これは前にもほかの委員からも質問が少し出ていますけれども、私は初期消火というところについて少し伺いたいと思っています。もし時間があれば６７ページの区民まつり経費について伺いたいと思います。","respondent":"若生健康課長","answer":"バリウム検診につきましては、実際のところ、見込みが、金額的なところではなく人数のところでのお答えになるのですけれども、バリウムの予算上の人数が１,９００人に対して、見込みが１,８０６人、内視鏡検診につきましては、予算上４,３００人のところが。","voiceIndex":248,"id":"exchange-109"},{"speaker":"塚本委員","kind":"質問","question":"これが経年的に減少傾向なのですか。そういう指摘があって、また国の指針で推奨されている検診ではないというご指摘もありました。この点について、推奨されている検診ではないというところがどういったことなのかということを少し詳しくお伺いしたいのと、胃がんリスク検診の受診者の減少傾向ということについて、区の今の見解ということをお伺いしたいと思います。","respondent":"若生健康課長","answer":"区といたしましては、現状、内視鏡検診、それからバリウム検診は対策型検診として推奨されている、こちらについては同じように継続していく予定ですが、リスク検診も合わせた３つのうち一つを選択する方法というのが。","voiceIndex":250,"id":"exchange-110"},{"speaker":"塚本委員","kind":"確認","question":"見直していくというところでご答弁いただきましたけれども、内視鏡検査というのが、少し聞いた話では、リスク検診、いわゆるピロリ菌の感染というのは、内視鏡でも一定程度、確認できるということで、そういう意味では、内視鏡検査をしておけば、リスク検診はしなくても大丈夫というような見方が一定できるのかどうかということをお伺いしたいと思うのと、それから今後。","respondent":"若生健康課長","answer":"ただ、全然、胃がんリスクのピロリ菌の検査の必要が全くない、意義がないものかというと、そういうわけでもなく、一定程度、それも有効性はあるということはありますので、ただ対策型検診としては推奨されていないというところが現状なので、このやり方については。","voiceIndex":252,"id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"品川区として、この日数というのをどのような形で、そのとおりなのだということなのか、耐震の進捗状況も都内でいろいろ違いもあったりして、品川区としてはもう少し早く復旧するのだなどという見解があるのかどうかという中で、それをまず伺いたいのと、断水したときに、いわゆる消防あるいは区民消火隊といったところの初期消火について、水が出ないというような中で。","respondent":"羽鳥防災体制整備担当課長","answer":"想定の復旧まで１７日ですけれども、ここの評価に関しましては、管理をしている東京都で計画的に整備を進めているものと認識しておりますので、その状況を踏まえて区としても十分な体制を取っていくということで考えているところです。","voiceIndex":254,"id":"exchange-112"},{"speaker":"田中委員","kind":"質問","question":"私は、３８ページ、特別区交付金、普通交付金が１１億２,０００万円減額になったことに関してお伺いしたいと思います。それで、そのときの収入が増えたので、その差額が狭まったからなのだろうと、そのときは認識いたしましたが、この１１億２,０００万円の減額の理由について改めてお伺いしたいと思います。","respondent":"遠藤財政課長","answer":"需要額についても基本的には増えているという形になっておりますけれども、他区と比較しての部分で、基準財政需要額の伸び率が低かったというところと、それから基準財政収入額の伸び率が高かったというところの２つの要因があるというところで考えているところです。","voiceIndex":257,"id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"そのように当日もご説明いただき、今も改めて伺いましたが、過去を遡ってみたときに、直接収入が増えたものが、これは全てを反映しているとは思いませんけれども、同じ３８ページに特別区民税が７億円増額になっています。ここでご説明がすとんと落ちないところがありまして、これまでの東京都とのやり取りの中で、いろいろ確認しました。一方で、２区だけが減額になっていますという発表がありました。","respondent":"遠藤財政課長","answer":"その辺が影響して、基準財政需要額が大きく下がっているというところになりますので、ですので正式には、去年から０.７％、普通交付金という形では減という形になっておるようなところです。","voiceIndex":259,"id":"exchange-114"},{"speaker":"田中委員","kind":"質問","question":"すみません。都市計画交付金の他区との比較はしておりませんが、品川区固有のことでそうなってしまっているのか、ほかの前提条件として、都市計画交付金が、ではほかの区も同様に減っているのだけれども、その分が反映されているのだけれども、でもトータルで言えば品川区だけ特別区交付金が減額されてしまっているという、その辺の分析はいかがでしょうか。","respondent":"遠藤財政課長","answer":"品川区の部分も同じような形で、今年度、対象となる部分が少なくなっていると考えているところです。","voiceIndex":261,"id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、それが結果的に、先ほどと論点が別の視点になってしまうかもしれませんけれども、収入が増えることによって、交付金が結果的にはマイナスになってしまうようなことがあってもいけないと思うので、要は政策と財源確保ということがしっかりと一致するような方向で議論していただきたいし、また財源確保に向けての努力もぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-116"},{"speaker":"こしば委員","kind":"質問","question":"私からは、７９ページの各種がん検診についてお伺いいたします。がんの死亡、すなわち悪性新生物による死亡率は、日本人の死因の中で、総合的に言いますと第１位です。昨年の４月に閣議で第４期のがん対策推進基本計画が決定されました。そして、計画には大まかに４つの目標が掲げられておりまして、その一つが、がんの予防です。減額の理由、そして区の評価について教えてください。","respondent":"若生健康課長","answer":"喉頭がん検診につきましては、これは区の推奨から外れてはいますけれども、こちらについても一定程度、こちらの受診率等が少ないというところは認識しているので、こちらについては今後検討と考えています。","voiceIndex":265,"id":"exchange-117"},{"speaker":"こしば委員","kind":"質問","question":"私もその報告書を見させていただきまして、大変たくさんの気づきを得ることができました。そこでお聞きいたしますが、既にがん検診の種目によっては、検診が何度か行われている種目もあると思いますが、その他のがん検診の案内にも、再度の、二度、三度と繰り返しの勧奨をすることで、受診率向上をお願いしたいと考えますが、現状を含め、お答えいただければと思います。","respondent":"若生健康課長","answer":"今年度、これからになるのですが、３月に大腸がんにつきましても、未受診者の方、４０歳から５９歳の国民健康保険加入の対象者、１万９,０００人ほどを対象に再勧奨通知を送るというようなことで対応を行っていく予定です。","voiceIndex":267,"id":"exchange-118"},{"speaker":"こしば委員","kind":"質問","question":"ここで、がん検診を受けるに当たりまして、対象の区民の方々からは、一部の負担金または無料で受診できるがん検診もあると認識しておりますが、一方で、品川区の補助を受けずに、自費でがん検診を受診するようなケースの場合、分かる範囲で結構ですので、１人当たり大体どのくらいかかるのか教えていただければと思います。","respondent":"若生健康課長","answer":"大腸がん検診につきましては無料になっております。子宮がんについても無料になっております。乳がん検診につきましては、超音波検査対象の方につきましては５００円、マンモグラフィーも併用される方については１,０００円となっております。","voiceIndex":269,"id":"exchange-119"},{"speaker":"こしば委員","kind":"質問","question":"聞き方が悪くてすみません。自費で、つまり補助を受けないで検診を受ける場合に、大体どのくらいかかるのでしょうか。分かる範囲で教えてもらいたかったのですが、もう一度お答えをお願いできますでしょうか。","respondent":"阿部健康推進部長","answer":"あるいは、人間ドックの際に併せて検診を受けられているというような方が多いと思いますので、この後、少し機会を捉えて、現状把握等に努めてまいりたいと思います。","voiceIndex":271,"id":"exchange-120"},{"speaker":"こしば委員","kind":"意見","question":"時間が少なくなったので、手短に言いますと、要はもし完全に自費で受ける場合は、相当な値段になると思います。そういったことも含めて、値段に着目した、受診率の向上に向けた取組をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":273,"id":"exchange-121"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほど田中委員もやったのですけれども、３８ページ、財政調整交付金関係を少しお話したいと思います。それから、６７ページ、区民保養所経費の質問もしたいと思います。これは、どうしてこういう話をするかというと、高橋イズムがありました。それから濱野イズムもありました。それで、先ほど田中委員も質問したのですが、これはどう聞いていても東京都の立場で物を言っていると思っている私がいます。","respondent":"新井副区長","answer":"ただ、こちら側に来て、逆に東京都からの説明を聞いて、その理不尽さだったり不合理さに、ある意味、憤りを感じているところもあり、財政調整だけではないと思うのです。","voiceIndex":276,"id":"exchange-122"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"メリット、デメリットの話だと、それだったらこういう感じで言ったほうが、逆に区は、あまり再編とか言うと、ある区と組まなくてはならなくなったりすると面倒くさくなっちゃうから、やめておこうかな」とか、そういう話もあったりしたものですから、それはぜひ区長会でも頑張っていただきたいと考えていますので、よろしくお願いします。それで、全ての区、今、２３区でまだ保養所機能は残している。","respondent":"宮澤地域活動課長","answer":"それら他区の状況や区民ニーズというところを含めまして、今後しっかりと検討していきたいと考えております。","voiceIndex":278,"id":"exchange-123"},{"speaker":"松永委員","kind":"質問","question":"私からは、６５ページの庁舎管理費について、６７ページの区民保養所、先ほどの品川荘について、もう一つが８３ページの目黒川・立会川水質改善について、時間がありましたら８７ページの除却助成、住替え支援助成と、８９ページのいわゆる耐震化について伺いたいと思います。","respondent":"佐藤経理課長","answer":"こちらは、令和５年度予算の編成を致しました令和４年の年末にかけまして、委員もご指摘のとおり、エネルギー価格の高騰を受けまして、電気・ガス料金について上昇傾向にあったというところでございまして、令和４年度の補正予算で。","voiceIndex":281,"id":"exchange-124"},{"speaker":"松永委員","kind":"意見","question":"国の対策ということであります。分かりました。次に、６７ページの区民保養所についてですが、先ほど、２,６２３万円の減額となっている理由については、工事計画を縮小されたということでありますが、最低限の工事に絞ったということで、どの部分に工事費を充てられたのかをお知らせください。","respondent":"宮澤地域活動課長","answer":"その中身としましては、老朽化に伴いまして、空調設備の更新のための工事、また、あともう一つが温泉用のろ過装置に絞った内容になっているというところです。","voiceIndex":283,"id":"exchange-125"},{"speaker":"松永委員","kind":"質問","question":"空調設備とろ過装置ですが、品川荘は今、築年数はどれくらいなのでしょうか。例えば今、南海トラフ地震が起きそうだという状況の中で、もし大きな地震が起きたときの耐震化の面に関してはどうなのかということをお聞きしたいと思います。","respondent":"小林施設整備課長","answer":"品川荘ですが、築年数としましては、およそ３０年です。それで、建物の耐震性能につきましては、この建物につきましては新耐震の基準に基づいて設計していますので、ある一定程度の耐震性能は持っているといったところです。","voiceIndex":285,"id":"exchange-126"},{"speaker":"松永委員","kind":"質問・要望","question":"もちろん少年野球です。次に、８５ページの目黒川の障害物ですが、汚泥のしゅんせつについてですけれども、この汚泥については１,３００万円の減額ということでありますけれども、内容といたしましては、護岸の脇の辺りの汚泥を取るということを伺っておりますけれども、その場所について詳しくお知らせいただければと思います。もう一つは、目黒川の障害物について、どういったものなのかお知らせください。","respondent":"北原河川下水道課長","answer":"しゅんせつを行う場所ですけれども、東京都と品川区で役割分担をしておりまして、品川区は河川の両脇のフーチング部分のしゅんせつを行うものです。障害物撤去につきましては、過去に護岸を整備したとき等に残置されている杭などが船の航行に支障になるため、撤去するものです。","voiceIndex":287,"id":"exchange-127"},{"speaker":"松永委員","kind":"質問・要望","question":"内容は分かるのですけれども、例えば目黒川の杭というのは、船が航行する辺りにあるのか、なぜそういったものがあるのかといった調査をしながら、しっかりと対策を取っていただきたいのですけれども、こうした中で、汚泥のしゅんせつをする際に、臭いなど恐らく出てくるのではないかと思うのですけれども、そうした近隣住民との対策をどのように取られているのかお知らせください。","respondent":"北原河川下水道課長","answer":"今後の予定なのですけれども、来年度につきましては、目黒川で工事が多数、ふくそうしておりまして、建設局の工事もありますので、令和７年度以降に最上流部でやりまして、全ての区間を完了する予定となっております。","voiceIndex":289,"id":"exchange-128"},{"speaker":"松永委員","kind":"質問","question":"ぜひ近隣住民のそういった対策も取っていただければと思います。次に、８７ページの除却助成、住替え支援事業について伺います。住替え支援についてですが、不燃化特区で建て替える際にかかる費用、引っ越し費用や、家賃補助は３か月分であると認識しておりますけれども、その利用実績と見込みについてどうだったのか、またその理由についてお知らせください。","respondent":"小川木密整備推進課長","answer":"除却申請の補正の理由ですが、こちらは移転助成とも補正理由は同じですが、当初見込んでおりました助成申請の件数が少なかったことによりまして、今回、減額補正をさせていただいたところです。","voiceIndex":291,"id":"exchange-129"},{"speaker":"松永委員","kind":"意見","question":"対象となる地域なのですけれども、これはもうあくまでも、もし大きな地震が来たら危ないということで、大体そのぐらいの地域やエリアなどに絞って予算をつくられていると思うのですけれども、そういったところの周知というのは、どういった形でやられていたのか、対象となるエリアの方たちに対して、ポスティングなり様々な対策は取っているのかと思いますけれども、改めてその方法についてお知らせください。","respondent":"小川木密整備推進課長","answer":"不燃化特区支援事業の対象地区ですが、区内１０地区になってございまして、こちらは特に危険度が高く、住宅が密集している地域を重点的に集中的に行うといったところで、１０地区を指定しています。","voiceIndex":293,"id":"exchange-130"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ早急な対策をお願いしたいと思います。そのため、耐震化が不可欠だと考えています。そこで私も昨年の第２回定例会で一般質問させていただいたのですけれども、いわゆる８１－００ですけれども、新耐震であるものの２０００年に改定された現行耐震基準より耐震性能に不安があるということで、早急な対応をお願いしていただきたいということで、区としてもしっかりとやっていくという回答を頂いております。","respondent":"長尾建築課長","answer":"耐震化がまだ不十分である、木造住宅については特に不十分であるという認識ですので、この拡充した除却助成をしっかりと今後周知いたしまして、耐震化をさらに加速していきたいと考えております。","voiceIndex":295,"id":"exchange-131"},{"speaker":"西本委員","kind":"質問","question":"質問を全部、申し上げたいと思います。これは、品川区いじめ防止対策推進基本方針と同じでよろしいでしょうか。なので、この基本方針、要は別物であったとしても、いじめ対策というのは、主導権はどうなっていくのですか。これは、３７校、一斉にやるところがあるのでしょうか。私は、来年度、３７校、一気に行うということは、あまりにも危険過ぎるし、どうしてそういう結論に至ったのかを説明してください。","respondent":"丸谷教育総合支援センター長、勝亦総務課長、藤村子ども育成課長","answer":"次年度に向けましては、体制強化ということでＨＥＡＲＴＳの中に弁護士を導入するなどといった形でのことも検討しています。現在のところ、頂いた１９件のうち５件は無事終息という形になっておりますけれども、それ以外につきましては、引き続き相談対応に当たっているところです。３７校一斉に実施できるかというところなのですが、こちらは８月に１０日間の試行実施を終えまして、そちらで幾つか課題は上がってきたところなのですが。","voiceIndex":299,"id":"exchange-132"},{"speaker":"西本委員","kind":"質問","question":"相談員というか、どなたが対応したのですか。何が違うのですか。なぜそれが、区長部局がつくると言い始めるのでしょうか。責任を持って教育委員会でつくったものは、改正するのだったら教育委員会がしっかりと責任を持ってやるべきではないでしょうか。そこを教育委員会はどう思っているのですか。それから区長部局は、どうして今まで教育委員会でやってきたのに、区長部局がそこに入ってくるのでしょうか。","respondent":"勝亦総務課長、丸谷教育総合支援センター長、藤村子ども育成課長","answer":"区長部局における相談員ですけれども、相談員３人が、心理カウンセラー、それから社会福祉士といった資格を持った者が対応しています。今回、区長部局と連携してというところで、教育委員会が作成した基本方針について、区長部局とも連携するという意味で協働して取りかかるというものです。こちらについては他自治体でも実施できているものですので、やっていきたいと思います。","voiceIndex":303,"id":"exchange-133"},{"speaker":"若林委員","kind":"質問・要望","question":"今回、６,２００万円の減額の理由も聞きます。最後に１件の世帯人数も、併せてお聞きしたいと思います。これの理由。それから、出産・育児一時金は、昨今のいろいろ報道もありますけれども、品川区でも、この項目だけ見ても１,８００万円の減額ということで、この減額の理由説明をお聞きしたいと思います。これについて、区民の方から意見やご要望があったので、ここで取り上げします。捨ててはいません。","respondent":"豊嶋生活福祉課長、池田国保医療年金課長、勝亦総務課長","answer":"私からは、住居確保給付金の件数等々についてご説明します。令和５年度、一番新しい申請件数と支給件数です。一体的実施についてのマイナスの補正です。二十歳になった実行委員の方等の意見も伺いながら、今後、どういったものが適切な記念品になるかどうか、考えてまいりたいと思います。","voiceIndex":308,"id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"郵送で送るということは、ただでさえ文字だけでありますので、なかなか伝わりづらい。新製品は毎年のように開発されています。アール・ブリュットにも一生懸命取り組まれている施設もあります。こういった、先ほどの送る側、また受け取った側のお気持ちの２つの視点から記念品を選定し、新成人に心が届くように努めていただきたいと存じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":312,"id":"exchange-135"},{"speaker":"西村委員","kind":"質問","question":"８５ページ、不燃化特区支援事業、８９ページ、住宅・建築物耐震化支援事業。質問が重ならないように伺ってまいりたいと思います。この減額補正されている理由は、午前中に木造住宅の除却の減額と伺いました。この除却の申請は例年同様に、想定よりも半分程度の申請件数だったということでしょうか。減額の詳細と、近年の申請数の変化を伺います。","respondent":"長尾建築課長","answer":"実績といたしましては約半分程度の申請になる見込みとなっておりますので、今回の補正減額では１１６棟分、約２.２億円の木造住宅の除却助成分を減額する内容となっております。","voiceIndex":314,"id":"exchange-136"},{"speaker":"西村委員","kind":"質問","question":"例年、これぐらいの申請数ということでよろしいのかと思うのですけれども、除却・建て替えを進めるために、区が前段で進めていっていただいた診断が、２次診断である一般診断法を取り入れております。費用は、戸建てで１件１５万円程度でしたでしょうか。耐震診断をさらに拡充して促すことでの、区の狙いや期待する効果を伺います。","respondent":"長尾建築課長","answer":"失礼しました。除却助成につきましては、平成２３年度から実施している制度になっております。その中で、平成２７年度以降は例年１５０件前後の申請が、除却助成についてはございました。","voiceIndex":316,"id":"exchange-137"},{"speaker":"西村委員","kind":"質問・要望","question":"診断をする方は建て替えを検討している方だと思いますので、自宅の耐震性能がどれぐらいかをぜひとも区民の皆様に検討するきっかけにしていただきたいと思います。不燃化率を上げていくことは、会派でも、まつざわ委員長を中心に要望してまいりました。どういう経緯があったのか、今後の数値目標はあるのか、伺います。","respondent":"小川木密整備推進課長","answer":"こちらの事業に関しましては、現在、品川区不燃化特区支援事業は、整備地域の中の重点整備地域を不燃化特区と指定しまして、助成支援を行わせていただいているところですが、来年度から取り組む加速事業につきましては、今年度からやっております東京都の補助スキームを活用して。","voiceIndex":318,"id":"exchange-138"},{"speaker":"西村委員","kind":"意見","question":"このスキームを活用していただいておりますけれども、令和７年まであと２年というところで、さらに力強い促進をお願いしたいと思います。東京都耐震ポータルサイトを見ておりますと、建て替え助成までしている区が現在８区ありまして、今後も区の取組は、これで終わりではないと考えていますが、これからこの事業をどこまで広げていくのか、区のお考えをお聞かせください。","respondent":"長尾建築課長","answer":"今後も、拡充してきた除却助成をしっかりと周知して、耐震化を促進していきたいと考えております。建て替えに関しましては、２３区の中でも一部の区で除却助成と併せて、もしくは建て替え助成をやっている区があるということは認識しております。","voiceIndex":320,"id":"exchange-139"},{"speaker":"西村委員","kind":"質問","question":"診断の強化をなぜこのタイミングでしていくのかというところも、今のご説明で私も理解できましたが、ぜひとも力強くお願いしたいと思います。見方を変えれば起こり得る事態だということも言えますので、この点、能登半島地震のこのような報道を受けましての、担当課のお考えをお聞かせください。","respondent":"長尾建築課長","answer":"昨年度の１０月から２０００年までに建てられた木造住宅も耐震診断の助成制度の対象に追加するなどして、旧耐震だけではなくて、住宅の耐震化については幅広く支援できるような状況にしております。","voiceIndex":322,"id":"exchange-140"},{"speaker":"西村委員","kind":"質問","question":"助成することで、除却・除去、さらには建て替えにつなげたいという担当課の熱意は伝わってまいりますが、現状、診断した方はすぐに工事につながっているのか、駄目なところが見つかっても直さない、直せないというような区民の方がいるのではと懸念いたしますが、その点はいかがでしょうか。","respondent":"長尾建築課長","answer":"木造住宅の除却助成を活用される方に関しましては、その後の建て替えや売却などという道筋が一定、見えている方からの申請や事前相談というのがほとんどですので、そこについては止まらず、そのまま建て替えに向かって進んでいるものと認識しております。","voiceIndex":324,"id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"確認","question":"６３ページ、６５ページ、９１ページの基金積立金についてお尋ねします。財政調整基金積立金ほか３つの基金への補正についてお伺いします。一般財源は１２億円。ここで、ほかの委員からもあったのですが、確認していきたいと思います。先ほど少しありましたが、基金の名前から、補正予算の編成に当たって、歳入との最終調整という形で、こういう金額になっているのかということをもう一回確認します。","respondent":"遠藤財政課長","answer":"財政調整基金の積立額補正につきましては、委員のおっしゃるとおり、最後、歳入と歳出を合わせなくてはいけませんので、その部分での積立額です。","voiceIndex":328,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということで、歳入・歳出を合わせるという部分もあるのですが、その一方で財政調整基金の金額、こういった調整した金額だけではなくて、積み立てることは可能だと思っています。その点についてはいかがでしょうか。","respondent":"遠藤財政課長","answer":"今回の補正額につきましては、今回の最終補正において、いわゆる財政の年度間の、これは令和５年度の資金がそれぞれどういう部分で使われているかで、足りない部分という形で、財政需要という形で出したものですので。","voiceIndex":330,"id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"今まさにおっしゃったように、結果としてというところなのですが、財政調整基金という形で、さらに積み立てることは、私は可能だと思っています。その件については、また別の機会にお話を伺いたいと思います。そして、先ほど出てきた庁舎整備基金ですが、利子のみであります。今後の庁舎整備に当たり、いろいろなところで議論になっていますが、具体的な財源計画をお伺いいたします。","respondent":"遠藤財政課長","answer":"ただ、現状におきましては、まだその後どうするかというところはまだ決まっていないところですので、今後、資金計画、実際の実績などが出た段階でも金額が分かってくるかと思いますので、そちらを徐々に見ながらという形になろうかと考えているところです。","voiceIndex":332,"id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、今お話があったように、令和５度年末で９０億円になるという。それで、令和６年度で１２０億円までいくというところはもう承知しております。先日あった庁舎整備の基本設計の中間報告では４５０億円という形でしたけれども、５６０億円まで膨れると。そうすると、そこの中で、何というか、解決できるという状況で、議会で現状、これからというお話がありましたけれども、いかがでしょうか。","respondent":"遠藤財政課長","answer":"今、計算式のお話を頂いたとおり、現状では１２０億円で、都や国のところの負担分を引きますと賄えるというような状況では考えているところです。","voiceIndex":334,"id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、起債をどうするかというお話になりますけれども、起債が３３０億円になるという前提で、それぞれ考えていかなければいけないところになるのかと思います。実は区債について、２３区で令和４年度決算を比較したところなのですけれども、品川区は区民１人当たりの区債残高は３万円です。２３区平均の４万６,０００円を下回っており、下から８番目の低さです。それについてはいかがでしょうか。","respondent":"遠藤財政課長","answer":"今後、起債はさせていただきまして、そちらの返済が当然かかってきますので、そこの部分につきましても、減債基金の積立てなども考えながら、返済の計画も立てるべきかと考えているところです。","voiceIndex":336,"id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"意見","question":"減債基金条例というのは、その中で３つ、対象事業があって、１つは特別区都市計画交付金の対象となる都市計画事業、２つ目は校舎建築などを目的とした義務教育施設整備事業、そして３番目に、そのほか償還財源を確保すべき公共事業ということなので、減債基金条例の減債基金の中に積み立てることができる。","respondent":"遠藤財政課長","answer":"一方で、今後またもう少し上がるような形も考えられますので、その分、今後の推移を見ながら、こちらについては様々な手法を検討していきたいと考えているところです。","voiceIndex":338,"id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問","question":"というご答弁なのですが、私が今お話ししたように、先ほど財政調整基金が数字的には調整額が出る。ただし、数字が大きいということが、やはり庁舎建設で欲しいので、できるだけ本当に様々な手法を使って、もちろん起債は起債ですけれども置いておいて、基金の中でできるだけ基金を積み重ねておく必要があると思うのですが、改めてお願いします。","respondent":"遠藤財政課長","answer":"様々な手法があると認識しておりますので、こちらの減債基金も含めまして、いろいろと検討させていただければと考えています。","voiceIndex":340,"id":"exchange-148"},{"speaker":"松本委員","kind":"確認","question":"先ほど基金積立金について質疑のやり取りをお伺いしていて、ここを確認しないといけないのかと思ってお伺いしたいのですけれども、先ほどの流れだと、基金に積めるだけのお金があるのであれば、予算の上限に達したものについて使ってはどうかというやり取りだったと思うのですが、そもそも補正予算の在り方として、そういうことがよいのか、よろしくないのかというところがあると思うのですが。","respondent":"遠藤財政課長","answer":"この間ずっと執行を１年間やってきた結果、様々な不用額が出てきているです。そこの部分のお金については、要するに還元金の平準化といいますか、安定性を含めてという形で、基金に積み置くという形につきましては、よく一般的にやられていることだと考えております。","voiceIndex":343,"id":"exchange-149"},{"speaker":"松本委員","kind":"質問・要望","question":"そうではなくて、事業のほうに、事業の人気があるから、こちらにもうどんどん補正予算で使ってしまえばいいという考え方が、これは国のほうについては財政法があって、地方においてもいろいろな財政規律の問題があると思うのですけれども、そういうことが、これは我々議員も質疑をする、要望を上げるときに。","respondent":"遠藤財政課長","answer":"一方で、最終補正という時期ですので、なかなか新規事業ができないとか、あとは、どうしても一部の医療費などという部分については、しっかり払っていかなくてはいけない部分もあろうかと思いますけれども。","voiceIndex":345,"id":"exchange-150"},{"speaker":"松本委員","kind":"提案","question":"こうしたことを考えながら、私も質疑をしていきたいと思います。ありがとうございました。これは昨年、そうした条例改正案が通ったということで、給与が増えているということだと思うのですけれども、道路課と防災課については２,０００万円規模で減っているというところで、これはどういう要因なのかお伺いできればと思います。","respondent":"崎村人事課長","answer":"道路課、防災課の給与費の減額です。先ほど石田しんご委員からも別の観点でご質問いただいたところなのですけれども、まず当初予算の考え方といたしまして、職員給与費については、その前年の１０月１日現在の現員現給をもって算定させていただいて、予算編成しています。","voiceIndex":347,"id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"よく理解できました。ここはある程度、厳密にやっていただくのがいいのではないかと思うのですが、今こういうふうに１００万円単位で給与についてやられている理由と、千円単位にしたほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"遠藤財政課長","answer":"人件費の場合はほかの流用と違いまして、いわゆる同一款内においてできるというところもありますので、一部のところにつきましては計上しないで、ほかのところで考えながらというか、ある程度、全体を見てという形でさせていただいているところです。","voiceIndex":349,"id":"exchange-152"},{"speaker":"松本委員","kind":"確認","question":"お考えは分かりました。この職員給与費に関連して、職員研修制度についてもお伺いしたいと思います。これは、品川区の職員自己啓発助成要綱に定めがあると思うのですけれども、ただ拝見すると、具体的な内容は基本的には総務部長が定めるということになっていて、なかなか中身が我々には分かりにくいので、助成の趣旨と具体的な内容、そして実際にどういうものが活用されているのか伺います。","respondent":"田口人材育成担当課長","answer":"ただいまの委員の自己啓発制度のご質問にお答えいたします。こちらは、教育機関が実施する講座を自発的に受講する職員および指定された研修を実現する職員に対して費用の一部を助成することで、自己啓発の促進を図り、質の向上を目的とするものです。","voiceIndex":351,"id":"exchange-153"},{"speaker":"松本委員","kind":"意見","question":"すみません。活用状況ということで、どういうものが人気があるか、どういうものが使われているかという具体的なところもお願いします。","respondent":"田口人材育成担当課長","answer":"失礼いたしました。活用状況につきましては、令和５年度は２月末時点で２３件、約２３万円の助成を行っております。申請が多い主なものとしましては、日商簿記検定や社会保険労務士、宅地建物取引士、語学系に関する講座や検定です。","voiceIndex":353,"id":"exchange-154"},{"speaker":"松本委員","kind":"確認","question":"魅力的だと私も思うのですけれども、一方で要綱を確認すると、会計年度任用職員の方たちというのが対象からは外されているかと思います。この理由についてお伺いできればと思います。","respondent":"田口人材育成担当課長","answer":"こちらの制度なのですけれども、会計年度任用職員につきましては１会計年度内での任用となっております。こちらが、翌年度以降も働くということが確定していないということもございまして、対象外としております。","voiceIndex":355,"id":"exchange-155"},{"speaker":"須貝委員","kind":"提案","question":"このように、社員に業務改善案の提出をお願いし、提案１件につき５００円支給し、対象に選ばれると５,０００円支給するというものです。その結果、現在、赤字体制の会社から、１か月の平均で２００件以上の提案数があり、売上げと利益も増大し、経営も安定したというような内容の報道がありました。この提案に対して特に目立つのが、上司が部下を評価するのは２５％、４分の１です。","respondent":"吉岡政策推進担当課長","answer":"なかなか、その後の効果をどう見せていくかというところまでは至っていないところですけれども、今年度、品川区が実施した事務事業評価につきましては、行政評価のマネジメントサイクル、ＰＤＣＡのＣの部分というところで、今後のＡ、行っていく中で。","voiceIndex":359,"id":"exchange-156"},{"speaker":"須貝委員","kind":"提案","question":"これも質問を忘れましたけれども、職員事業提案制度というのは実際あるのかどうか教えてください。そして、あれば何件ぐらい毎月出ているのか、それも教えてください。住民や法人から電話対応や窓口対応、各種書類の処理などを行い、福祉、教育、子育てなど、数字に表せない仕事をしていると思うのですが、どうでしょうか。お答えください。これについてご見解をお聞かせください。","respondent":"岡秘書担当課長、吉岡政策推進担当課長","answer":"私からは、職員事業提案制度についてお答えします。今年度から職員提案事業制度をやりまして、提案数が３３件ありました。そのうち９件を予算化して、来年度に向けてやり始めました。委員からお話があったとおり、こちらの事務事業評価につきましては、様々な事業で定めている指標の達成状況や予算の執行といった客観的な数値に基づいておりますけれども、その事業を行っていく上での必要性や有効性というところで。","voiceIndex":361,"id":"exchange-157"},{"speaker":"須貝委員","kind":"提案","question":"区民を支えるということですよね。それを、こういうふうに、人件費は幾ら、事業費は幾らではないのではないのですか。これだけの大勢の、要は品川区は大企業です。その職員の方が、「いや、こうしたらいいと思うんだけど」という提案。多くの方の知恵を借りて、やはり現場でいる職員の知恵を借りて、品川区というのを改善するべきではありませんか。もう一度、ご見解をお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価のところで、先ほども申し上げたとおりですけれども、事業の必要性、有効性を見る上で、やはり事業の効果を算出するに当たり、必要な満足度というのが重要な指標ではありますけれども、もし同じ満足度を得られるのであれば、当然。","voiceIndex":364,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"行政というのは、何か利益を得るためにやっているのですか。違いませんか。では仕事をいつやるのですか。でも、それでいいのではないですか。そういう、評価する仕組みというのをつくるべきだと私は思いますが、それがイコール、職員の働きがいにつながるのではないですか。でも、それはできないとして、やはりそういうことを主眼として、行政評価というのはするべきだと私は思うのですが、いかがですか。","respondent":"吉岡政策推進担当課長、崎村人事課長","answer":"事業などで同じ効果を得られるのであれば、財源も限られている部分はありますので、しっかりと、どう事業を実施すれば効率的にできるかというところで、行政評価を実施したです。ですので、先ほど政策推進担当課長からお話しいたしましたけれども、人件費もやはり考えながら、限られた人材で良質な区民サービスを提供するためにはどうしたらいいかということを考えていくのが行政の役割だと考えております。","voiceIndex":366,"id":"exchange-159"},{"speaker":"須貝委員","kind":"提案","question":"そちらを考えるのではなくて、お客様に対して、区民の皆さんにどれだけ満足してもらえますか、区民から頼られますかということを主眼にすべきでしょう。違いますか。今、品川区では、ＳＤＧｓ未来都市、それから自治体ＳＤＧｓモデル事業の提案内容が出ました。だけど、今、皆さんに必要なのはこのことですか。生活は大変です。そうすると、私は考え方がおかしいと思うのですが、ご見解をお聞かせください。","respondent":"久保田企画部長","answer":"行政評価の件ですけれども、当然ながらコストという意識を我々は持っていますけれども、やはり区民サービスを提供する、そして区民の方に満足していただくということが一番大事だと思っていますので、そうした視点も入れながら、行政評価をしていく中で。","voiceIndex":369,"id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"森澤区長は本当に若くて聡明な方だと思います。でも新井副区長、側に、年齢が近いのですから、「区長、それはおかしいですよ。違いますよ」ということは、ノーはノーではっきり言って、それでやはりお互いに話し合って、この品川区を改革、改善してほしいと私は思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":371,"id":"exchange-161"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、１０３ページから始まります特別会計の国民健康保険と後期高齢者医療制度、そして介護保険について伺いたいと思います。その特別会計が補正予算でどうなっているのかについて伺いたいと思います。それから２点目に、特別区長会が昨年の１１月１６日に厚生労働大臣宛てに、国民健康保険制度の見直しに関する提言を出して、加入者の負担軽減など、５項目にわたる要望も出しました。","respondent":"池田国保医療年金課長","answer":"実際、医療費がかかるということは、保険料についても、医療費、それから所得によって保険料というのは決定してまいりますので、負担される方がますます苦しい現状になってくるというような、負担が大きくなるという現状があるということで、今後も国民健康保険の事業について。","voiceIndex":373,"id":"exchange-162"},{"speaker":"鈴木委員","kind":"確認","question":"決算補填等を目的とする法定外繰入れということが２４億円ということでいいのですか。法定外繰入れは最終補正で幾らかと伺ったのですけれども、２４億円でいいのかということの確認をお願いしたいと思います。これは、協会けんぽの２倍以上になるものです。総収入で月２５万円の４人世帯から月４万円もの国保料というのは、負担が重いという認識はないかということを伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"それで、もう一つが提言についてですけれども、こちらについては、これまでも特別区長会を通じて、東京都、それから国等にいろいろな要望を出させていただいているところですけれども、今回は本当に保険料について厳しい状況というのもございましたので。","voiceIndex":375,"id":"exchange-163"},{"speaker":"鈴木委員","kind":"質問・要望","question":"特別区長会の提言というのは初めてかと伺ったので……。ごめんなさい。すみません。私は、負担が重いという立場にぜひとも区としても立っていただきたいと思うのです。子どもの国民健康保険料の負担軽減ももっと拡大してくれということで要望しているわけですから、その大本には、負担が重いという立場に立っていただきたいということで思いますけれども、いかがでしょうか。この点について伺います。","respondent":"池田国保医療年金課長","answer":"もう一つの子どもの保険料についてですけれども、これも、子どもの保険料、未就学児の保険料の均等割の５割軽減については国の制度ですので、こちらにつきましては、国がこれもこの間の提言と同時に、子どもの保険料の軽減についても提言させていただいてありますので。","voiceIndex":377,"id":"exchange-164"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、私も現場の声を本当に様々なところで聞いているのですけれども、どの現場でも、もう限界という状況で、疲弊しながら必死に、何というのですか、利用者の方を守り、仕事を守りという形で仕事をされているという大変な実態だということを実感しているのですけれども、そういう中で、ぜひ区としても現場の声を聞いていただいて、区としてできることはやりますという姿勢で。","respondent":"菅野高齢者福祉課長","answer":"そういった現場の声を伺いながら、区としてどういった支援ができるのかというところで、今回も居住支援手当というところで、１万円の手当の支給というところも踏み切らせていただきましたので、現場の声を聞きながら今後も検討していきたいと思っているところです。","voiceIndex":379,"id":"exchange-165"},{"speaker":"鈴木委員","kind":"意見","question":"もう時間がなくなってしまって、意見表明を行いたいと思います。介護保険、後期高齢者医療制度、それから国民健康保険の特別会計に反対の意見表明を行います。今、区民の生活実態は、コロナ禍に続く物価高騰で多くの人が苦境に立たされています。実質賃金もピーク時より７４万円も下がり、年金も下げられている。この補正予算にもこの視点で反映させるべきと考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":381,"id":"exchange-166"},{"speaker":"大倉委員","kind":"質問","question":"私からは、補正予算に関連して事務事業評価と、ウェルビーイング予算について伺うのと、６９ページ、障害者グループホーム整備等助成について、あと、７１ページ、すまいるスクール運営費、先ほど同じ会派の、ひがし委員からもありましたが、ほかの委員からもありましたが、お弁当の件について伺えればと思います。どのように検討がされていくのか、教えていただければと思います。","respondent":"吉岡政策推進担当課長、佐藤企画課長、川崎障害者施策推進課長、藤村子ども育成課長","answer":"来年度の実施につきましては、今年度の実施結果を踏まえまして、そういった予算の削減額の考え方や成果指標の設定方法をはじめといたしまして。プレス発表資料に書かれてあるのは、総合実施計画、総合戦略の改定の中で、ウェルビーイングの実現に向けて。私からは、障害者グループホーム整備等助成の５,０００万円減額になった理由についてお答えいたします。学校との調整や現場職員との対応フローの構築によって、他の学校でもクリアできるのではないかというような前提を持って、今回。","voiceIndex":383,"id":"exchange-167"},{"speaker":"大倉委員","kind":"質問・要望","question":"事務事業評価については分かりました。代表質問でもしたのですが、中・重度のグループホーム等、障害のある方が入れるような施設など、運営も既にされているところの助成の費用について件数を伺って、しっかりと中・重度の受入れができるような、区の補助金に資するような制度の要件について、見直し中も含めて検討していただきたいというところで質問をさせていただきました。伺います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長、藤村子ども育成課長、吉岡政策推進担当課長","answer":"グループホーム整備等助成についてのお尋ねです。先ほど、整備補助については、使わずに開設が進んだとご説明しました。今後、この補助金の活用によりまして中・重度の障害のある方の入居が進むよう、補助金の要件につきまして、事業者の声を聞きながら。誤食の可能性というところなのですけれども、こちらも、そういったことが起こらないように細心の注意を払って、委託の人間もつける形になりますので。","voiceIndex":388,"id":"exchange-168"},{"speaker":"大倉委員","kind":"質問","question":"事務事業評価は、そういった視点も持ちながらやっていただいているということなので、安心いたしました。引き続きよろしくお願いします。障害者グループホーム等の助成の運営は、ぜひ要件については、事業者の声を聞きながら、また国の指針も注視しながらということでありましたが、ぜひよろしくお願いします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":393,"id":"exchange-169"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、７５ページ、私立幼稚園費、私立幼稚園保育料助成、そして８９ページ、防災費から避難所管理費、この２点で質問をします。私立幼稚園保護者補助金が減額補正になっておりますけれども、その理由と背景をお知らせください。品川区として私立幼稚園による幼児教育の重要性をどのようにお考えになっているのか、伺います。","respondent":"石井保育支援課長","answer":"幼児期の貴重な人格形成の基礎ということで、私立幼稚園の果たす役割というのはとても大きいものであると認識しています。","voiceIndex":395,"id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問","question":"無償化開始の際にも議会でも課題となっておりました、保育料の償還払いについて伺っていきます。伺いますけれども、品川区の私立幼稚園の保育料、これは高いところと低いところありますが、高いところと低いところの例示といいますか、そして月額の平均額、品川区がつかんでいるところを教えてください。","respondent":"石井保育支援課長","answer":"私立幼稚園の保育料ですけれども、私が把握している限り、一番低いところは大体２万６,０００円程度、高いところは４万円程度で、平均すると大体３万１,０００円から２,０００円の間であると把握しております。","voiceIndex":397,"id":"exchange-171"},{"speaker":"あくつ委員","kind":"質問","question":"月額平均で３万１,０００円から２,０００円、年額で３７万円から３８万円、半期分でも１９万円から２０万円ぐらい。そして、私立幼稚園にお子さんが２人在園すれば、当然、２倍の出費となるわけであります。ここで伺いますが、施設等利用費の支給について、償還払いもしくは法定代理受領にするのか、その具体的な方法について各自治体で決定できるのか、まず教えてください。","respondent":"石井保育支援課長","answer":"施設等利用費の支給に関しましては、法律上、代理受領について規定がありますので、まずはできるです。各区、各自治体の判断で、そのようなことを実施するか否かについては検討できるものと考えています。","voiceIndex":399,"id":"exchange-172"},{"speaker":"あくつ委員","kind":"質問・要望","question":"このことにつきまして、保護者の経済的負担の軽減や利便性を促進する給付方法である法定代理受領をぜひ導入していただきたいと思うのですけれども、ご見解を伺います。","respondent":"石井保育支援課長","answer":"令和元年に幼児教育の無償化が制度化されてから、様々、方法等を検討してまいりました。この間、いろいろ幼稚園ともコミュニケーションを取らせていただきながら、ぜひこちらの実現に向けて、前向きに準備をしています。","voiceIndex":401,"id":"exchange-173"},{"speaker":"あくつ委員","kind":"質問・要望","question":"園児保護者補助金について伺います。私立幼稚園における各ご家庭の自己負担額、これは、先ほどあった保育料の上下があるので負担額は異なるのですけれども、大体どれぐらい差額を負担されているのか、品川区が捉えている金額を教えてください。","respondent":"石井保育支援課長","answer":"保護者補助金の予算の算定ベースで考えますと、４,０００円程度の自己負担が生じているのではないかと考えています。","voiceIndex":403,"id":"exchange-174"},{"speaker":"あくつ委員","kind":"質問・要望","question":"幼児教育無償化部分に当たる施設等利用給付は、所得にかかわらず、１人につき全国一律２万５,７００円となる。もし、他区と同等の園児保護者補助金額まで引き上げることができれば、第１子のお子さんについては、自己負担がなくなって、全額無償化ということも見えてくるということではないでしょうか。可能な限り、全額無償化に近づけていただきたいと思いますが、いかがでしょうか。","respondent":"石井保育支援課長","answer":"例えば、第２子、第３子の算定方法の変更といったことで、東京都についても制度の工夫をしていますので、そういった動きを見ながら、子育て負担の軽減については適切に検討してまいりたいと考えています。","voiceIndex":405,"id":"exchange-175"},{"speaker":"あくつ委員","kind":"提案","question":"引き続き、よろしくお願いいたします。８９ページ、防災費、避難所管理費です。これも減額補正になっておりますが、これも確認いたしまして、防災井戸の整備について費用が抑えられたということで、減額補正になったということであります。防災課として、あまたある防災対策の中から多額のトイレ対策を提案した理由、そして災害時のトイレ問題についてどう捉えておられるのか、教えてください。","respondent":"平原防災課長","answer":"そういったところもございまして、私どもは今回、地域防災計画の見直しの中で在宅避難を強く打ち出したところでもあり、そういったものを維持するためにどのような事業が必要かという観点で、今回この事業を検討し、来年度、防災をさらに考えていただくきっかけとして。","voiceIndex":407,"id":"exchange-176"},{"speaker":"あくつ委員","kind":"質問","question":"トイレ問題でも災害のときに同じような悲劇が繰り返されておりますが、なぜ災害時のトイレ対策が進まないかというところに対しまして、ＮＰＯ法人日本トイレ研究所の加藤代表、私はこの方の講演へ２回、実は伺っているのですけれども、やはりいろいろなことをおっしゃっているのですけれども、その中で、教訓をどう活かすべきか。品川区では、災害時のトイレ確保・管理計画の策定をされているのか、伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"地域防災計画を、このたび大規模修正をいたしまして、その中に、トイレの確保ということでうたっております。来年度以降、避難所運営マニュアルや地区防災計画といった中にも、しっかりトイレの確保についてうたってまいりたいと考えております。","voiceIndex":409,"id":"exchange-177"},{"speaker":"あくつ委員","kind":"質問","question":"加藤代表という方も言っていますが、トイレの管理・確保というのは生易しいものではない。もう一つおっしゃっているのが、行政でもトイレの管理・確保の責任者を立てていないというところで、立てている自治体もあるのですけれども、このことについて品川区は計画の中で、トイレ確保・管理の責任者を立てているかどうか。私は立てるべきだと思いますが、この点についてご見解を伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"トイレの責任者についてですけれども、現状設定しておりません。","voiceIndex":411,"id":"exchange-178"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"私からは、６７ページの区民保養所経費、５３ページの事業承継支援事業、時間が残れば８５ページの水辺利活用と、目黒川の障害物撤去についてお伺いします。それに関連して保養所のところをお伺いしますが、もともと区民保養所というのが、事業のスタートが、行政評価シートで確認すると、昭和３６年からスタートしていると書いてあるのですが、まずその認識でいいのか。","respondent":"宮澤地域活動課長","answer":"品川荘は昭和３４年に開設で、光林荘が昭和３６年に開設というところで、区民の保養と健康の増進を目的にということで、保養所事業を実施しています。","voiceIndex":414,"id":"exchange-179"},{"speaker":"せりざわ委員","kind":"確認","question":"昭和３４年と昭和３６年。昭和３６年というと１９６１年になるかと思いますが、世界で何が起こったかと確認していると、ベルリンの壁ができた年だそうであります。そういう意味で言うと、これは私の感覚でありますが、一般利用、いわゆる区民の人が利用していくというのは、今の保養所である必要はないのではないかとまず思うのですが、こちらについてご見解をお聞かせください。","respondent":"宮澤地域活動課長","answer":"自治体としてやる中で一番大きいところとしては、例えば、品川荘の宿泊に関しては平日であれば６,５００円というところで、伊東市の平均というところが大体１万５,０００円ということだそうなので、圧倒的に格安で、区民の方がどなたでも気軽に利用できる。","voiceIndex":416,"id":"exchange-180"},{"speaker":"せりざわ委員","kind":"意見","question":"例えば今、保養所がなかったとして、これから造りますか、用意しますかと言われたら、私は用意しないと思っているのですけれども、そういった観点でぜひ一度、見直しをしていただければと思いますが、ご見解をお聞かせください。","respondent":"宮澤地域活動課長","answer":"そちらに関しても、その手法の課題というのもあるとは聞いているところではありますけれども、他区の状況や利用の実績、区民ニーズ等を踏まえて、今後の方向性について検討していきたいです。","voiceIndex":418,"id":"exchange-181"},{"speaker":"せりざわ委員","kind":"確認","question":"事業承継についてお伺いをします。初めにお伺いしたいのですが、品川区でも今、事業承継というのが非常に話題になっているというか、ニーズの高まりを私自身も感じておりますが、このタイミングで、このニーズが高まってきたというのを、どのように分析されているのか、まずお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"そういったところで、品川区として、この取組を平成２８年度から進めておりますけれども、実際、事業承継を進めるに当たりまして、例えば親族間の承継、あるいは従業員に対する承継、あるいは第三者に対する承継、いろいろパターンがありますけれども、こういった中を通じまして。","voiceIndex":420,"id":"exchange-182"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"全体的な高齢化というお話がありました。一緒に働いていた方々なども同じ世代の方が多いので、なかなか後継者というのが見つからないというのが、現状だと思います。しかしながら、１人でやっている店舗の方などというのは、なかなかもう毎日、今を生きるのに本当に精いっぱいで、出口戦略と言ったらいいのでしょうか、どこでやめようか、誰に譲ろうかというところまで、なかなか考えられずにいると思います。","respondent":"小林商業・ものづくり課長","answer":"そういった中を通じまして、まずこういう問題を考えなくてはいけないという問題意識を持っていただきながら、具体的なところは専門家相談や、あるいは本日ご説明しましたような助成金も使っていただきながら、それを有効に進めていくという方向で進めていきたいと考えております。","voiceIndex":422,"id":"exchange-183"},{"speaker":"せりざわ委員","kind":"意見","question":"様々、セミナーのお話もありがとうあります。そうすると、特にこれが問題なのは、地域につながりがあれば、ある人ほど地域の人に相談できないという現状があって、だから地域の人ではなくて品川区が引っ張っていって、ほかの方に事業を譲渡するようなお手伝いをするというのも、品川区としてできればいいと思うのですが、ご見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"ですので、そういったところの相談も活用していただきながら、少し時間もかけながら進めていくようなお手伝いをできればと考えております。","voiceIndex":424,"id":"exchange-184"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"以前、我々の会派で事業承継のことも少し勉強会をさせていただいたときに、今おっしゃっていただいたようなＭ＆Ａですか、事業の買収というところの、例えばマッチングサイトがあったほうがいいのではないかというようなお話もありました。品川区でも、例えばそういったところの支援をしていただいて、品川区として、ぜひ様々な地域産業があります。","respondent":"小林商業・ものづくり課長","answer":"いろいろ複雑なといいますか、専門的な手法もありますので、ご指摘のようなマッチングサイトのところも含めて、金融機関などともいろいろ連携しながら研究していきたいと考えております。","voiceIndex":426,"id":"exchange-185"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6685#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":134821,"voices":431}},{"id":"r06-20240305-3","meetingId":"r06-c-budget","date":"2024年3月5日","dateIso":"2024-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を196件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年度品川区一般会計予算","agenda":"令和６年度品川区一般会計予算","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"おはようあります。６１ページ、なぎさ会館、伺ってまいりたいと思います。歳入になぎさ会館の斎場使用料が計上されておりますが、所管をまたぐので、臨海斎場、桐ケ谷斎場と併せて質問します。増築のために駐車場を一部潰すと伺っておりますが、駐車スペースの確保に問題はないでしょうか。この点、改善できることはないか、ご検討いただきたいと思いますが、いかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"その際、組合のほうから、臨海部広域斎場組合と品川区を含めた組織区５区で、今後検討してまいりますという回答をしております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"西村委員","kind":"質問・要望","question":"これから大きく変わっていく臨海斎場をぜひともお願いしたいと思います。なぎさ会館、こちらは今後どう展開していくのかということも質問させていただきたいと思います。改めて、なぎさ会館はこのまま維持していけるのかという問題は、別の課題があると思うのですが、いかがでしょうか。現状と区の抱える課題についてお聞かせください。","respondent":"吉野戸籍住民課長","answer":"採算が取れないという観点もあるのですけれども、一方で、斎場は広域性の観点も必要であると認識しております。区民のニーズですとか、社会情勢とか、そういったところも勘案しまして、今後の検討課題と認識しております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"西村委員","kind":"質問","question":"なぎさ会館は、リニューアルや新しい施策でまかなえる状況なのか、出血していて立て直しが難しい状況にあるのか、行政評価を上げたばかりでありますが、区はどのようにお考えでしょうか。利用料収入の経年変化と併せて伺います。","respondent":"吉野戸籍住民課長","answer":"先ほどの答弁と少し重なってしまうのですけれども、やはり今後の社会情勢等も鑑みまして検討していきたいと思います。","voiceIndex":8,"id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"葬儀場は、なかなか新規に建てられないという側面もありますので、これからまちづくりも含めまして臨海斎場の見直しが図られる中で、なぎさ会館をどうしていくのかということは、ぜひとも議論を続けていただきたいと思います。次に、桐ケ谷斎場について伺ってまいりますが、民間とはいえ、桐ケ谷斎場の料金に割高感が最近一層あるというご指摘が区民の方からもあります。","respondent":"舩木生活衛生課長","answer":"今後も民間火葬場の関係区とも調整の上、例えば、火葬業とその他の事業の収支、あるいは、会計がしっかりと明確に分離されているかなどについて、必要な報告を求め、火葬場の適正運営について確認を行っていく予定です。","voiceIndex":10,"id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"区と都の役割も改めて伺いたいと思うのですが、区は民間に対しても収支の計画、立入調査をすることができるというふうに今確認をさせていただきました。桐ケ谷斎場は我が区にありますし、区民の方々が多く使っている施設ですので、どうぞ引き続きの調査計画を行っていただきたいと思います。もう一言お願いいたします。","respondent":"舩木生活衛生課長","answer":"そういった意味では、民間企業の火葬場においても、墓地埋葬法の立法の前から、かなり古くから火葬という部分を支えてきていただいたという背景もありますけれども、臨海斎場、あるいは特別区においては民間会社が経営する火葬場が６か所ありますけれども、いずれにしましても。","voiceIndex":12,"id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"葬儀までは生存権や共助の範疇ではないかと私は思っておりますので、公平性が求められるべきだろうと思いますから、よろしくお願いします。最後に、すみません、１点、臨海斎場なのですが、基本方針案において組織区５区の将来死亡者数のピークが２０６０年から２０６４年とあります。これ、構成５区や都市部においては異なるということでしょうか、伺います。","respondent":"吉野戸籍住民課長","answer":"委員のご認識のとおり、日本全体と組織区５区でいきますと、組織区５区のほうは、ちょうど団塊の世代のお子さんが亡くなられるのが２０６０年という形になっております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"西村委員","kind":"意見","question":"こういった５区における特別な状況もあると思いますので、引き続きお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"よろしくお願いします。私からは、２点お伺いいたします。１４１ページ、幼保一体施設幼稚園運営費、９５ページ、オアシスルーム・ポップンルームの運営について、それぞれお伺いしてまいります。初めに、幼保一体施設に関連して、幼稚園の預かり保育の周知についてお伺いしてまいります。","respondent":"立木保育課長","answer":"不承諾の際にお知らせを同封していますけれども、そちらの中では、二次選考に向けてのご案内、それから、定期利用保育、空きスペース利用保育のご案内、それから、認可外保育施設の保育料助成、ベビーシッターの利用支援事業についてのご案内を同封しています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"数も７４０ということで確認させていただきました。そこで、不承諾通知にも、二次選考のスケジュール、先ほど、定期利用やベビーシッターのご案内ということで同封されているとありましたが、こちら、認証、認可外保育事業なども選択肢の１つとなる、幼保一体型の幼稚園も就労のための選択肢の１つとなることや、認証、認可外保育事業なども併せて周知することを求めますが、区の見解を求めます。","respondent":"立木保育課長","answer":"その分、ホームページや窓口、かんがるープラン等での相談とか、そちらのほうで丁寧なご案内をさせていただいている部分ですが、今後も、より丁寧にご案内をさせていただきたいと考えております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"確認させていただきました。もちろん幼稚園と保育園ではそれぞれ方針が違います。ですが、就労のためにどこかに預け、幼児教育を支援していく１つの選択肢として情報を提供していくことは大切なことだと思われます。こちらは要望で終わります。次に、オアシスルームの運営についてお伺いします。今年度のオアシスルームの利用率と傾向、使用されている理由別で一番多い項目についてお聞きします。","respondent":"石井保育支援課長","answer":"令和元年度、２万３,０００名程度のご利用があり、新型コロナウイルスの関係で、少し利用が落ちてしまったのですけれども、今年度についても約２万３,０００名程度のご利用が見込まれるというふうに承知しています。","voiceIndex":22,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"２万３,０００名で増加傾向とのことで、また、リフレッシュのためとの理由から、区民のニーズの高さを確認させていただきました。現実的には、防犯上や安全性の観点からは課題がありますが、例えば、保護者以外の親戚で本人の確認のできるマイナンバーカード等による事前登録ができて、安全性の担保がとれていれば可能であるか、区の見解をお聞きできればと思います。","respondent":"石井保育支援課長","answer":"事前登録ですとか、あとは利用の開始のときに、今日はこういう方がお迎えに来ますよというふうなことができれば、どのような方でもお迎えができるのではないかと考えています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"前向きな答弁、ありがとうあります。課題はありますが、安全性を確保した上で、ぜひ区民ニーズとして前向きに進めていただければと思います。オアシスルームは、理由別でも圧倒的に育児疲れのリフレッシュで利用されていることから、使用頻度の増加から見ても、孤立した子育てが今後も強いられない施策がより一層重要だと感じられます。こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、１４１ページの部活動指導員配置経費補助金に関連して、部活動地域移行について伺います。本件は、昨年の決算特別委員会でも質問いたしましたが、その続きとなります。現在進めている部活動の地域移行に関し、部活動指導員と民間委託のそれぞれに、対象部活数や指導日数の具体値を含めて、令和５年度の計画と実績、令和６年度の計画についてお教えください。","respondent":"丸谷教育総合支援センター長、中谷指導課長","answer":"部活動指導員の計画ですけれども、令和５年度は各校２名枠、令和６年度は各校４名枠と考えております。１種目当たりの日数は、最大想定で週５日程度です。現在、校長会と連携していますが、各校２種目程度で、種目については各学校が委託したい部活動を選ぶことができるような状況で進めていければと考えております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"山本委員","kind":"意見","question":"１３種目のうち、令和５年度は、部活動指導員で２種目分だったところが、令和６年度には、部活動指導員４種目分と、民間委託の２種目の合計６種目分に増えるということですね。当年度から令和７年度までの３年間での移行を目標とする中で、大きく前進していると考えます。部活動指導員は、令和５年度の利用実績で１３校で３０名と、ある程度進んでいる印象ですが、評価と課題をお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"部活動指導員の各学校枠を増やした結果、活用が進んでいるところです。中には地域クラブに移行する部も一部あります。課題といたしましては、今年度以上に地域の方々のご指導をいただき、学校への導入拡大を図る必要があると考えております。","voiceIndex":31,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答をありがとうあります。話が進む中で実務上の課題が判明し、要望をいただきましたので、この場でご説明します。兼業の制限に当てはまらないような契約形態への制度変更は難しいでしょうか。部活動指導員を１人に限定せずにサークル単位とすることはできませんでしょうか。サークル単位が無理でも、１種目に対して複数人、例えば、三、四名程度を登録して、輪番やシフトで勤務することは可能でしょうか。","respondent":"丸谷教育総合支援センター長","answer":"同じ種目に複数名の指導員を任用することは、制度上は可能となっております。ただし、会計年度任用職員となりますので、ある程度、曜日が固定されるということがあります。団体を部活動指導員として登録することは、現状の制度では難しいと考えております。","voiceIndex":33,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"複数名を登録することができるということは確認できてよかったです。それ以外のところは、今後の課題として検討していただきたいと考えています。そこで、新たにＮＰＯ法人を設立し、地域スポーツクラブと部活動指導員への給与支払事務を移管することで、教育総合支援センターの事務負担軽減と、部活動指導員側の利便性向上を図ることを検討してはいかがでしょうか。区のお考えをお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"事務負担の軽減を図っているところです。ＮＰＯ法人の立ち上げ等についてですけれども、まずは国が進めている現在の仕組みの中で充実を図ることが大切だと考えており、次のステップについては今後の話だというふうに考えてあります。","voiceIndex":36,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"なかなかすぐには進まないとは思いますが、国の動向などを踏まえながら、ぜひそれぞれにとってメリットがある仕組みを検討していただきたいと思います。制度改定と対応できる仕組みづくりの検討を要望し、次の質問に移ります。続いて、ここまで区として実施している地域部活動の取組について伺います。それぞれの種目に関して、参加人数、活動状況、感想などについてお教えください。","respondent":"中谷指導課長","answer":"バドミントン、３０名、全１０回、計画どおり実施、様々な練習方法を知ることができた。ダンス、３５名、全５回、計画どおり実施、先生が指導してくれて踊りやすかったなどとなっています。","voiceIndex":38,"id":"exchange-017"},{"speaker":"山本委員","kind":"意見","question":"これまでの部活動にはない新しい取組、新しいスポーツの裾野を広げる取組はよいと考えます。バドミントンは、３０名が参加できてよいと思いますが、各学校でもバドミントン部がありますので、従来の学校での部活動とのすみ分けや、一部の生徒に限り、いいコーチから指導が受けられる、平等性に対する課題があると考えます。それを踏まえた来年度の取組方針について、お教えください。","respondent":"中谷指導課長","answer":"バドミントンにつきましては、学校部活動でメジャーな種目でありまして、今回の成果と課題を踏まえて、今後の学校部活動のよりよい民間委託に生かしていくものとして、次年度、実施予定はございません。","voiceIndex":40,"id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"実証実験を踏まえて、課題に対しておのおのご対応いただいていると理解いたしました。予算を有効に使うべく、多くの子どもたちが参加するように取組を進めていただくことを要望して私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-019"},{"speaker":"安藤委員","kind":"確認","question":"６７ページ、子供の森公園こども野球場に関連して、工事中の代替地確保について、１０９ページ、自衛官等募集事務費に関連して、自衛隊募集への名簿提供の有無、時間があれば、議会費、議事録経費について伺います。名簿を提供するという形をとっているのかいないのか、確認させてください。","respondent":"吉野戸籍住民課長","answer":"自衛官の募集に際しての情報提供ですけれども、こちらは現在行っていない状況です。","voiceIndex":44,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"自衛官募集に区民の名簿を提供することは、引き続き行わないよう求めたいと思います。次の質問に移ります。昨年１０月１７日に行われました住民説明会では、高齢者クラブの会長や役員の方から、工事の期間や期間中の代替地の確保などの質問、要望が出まして、区からは、工事は令和７年度の夏頃から令和８年度末までの１年半を想定している。これが１年半以上途絶えてしまったら、どうなるのでしょうか。","respondent":"高梨公園課長","answer":"一方で、説明会のときにも申しましたとおり、そこで活動したいという区民の方の思いについては、区としてもしっかりと受け止めしていますので、その工事の中で部分的に、できるだけ、例えば野球場を全体の工期よりも早めに終え、少しでも早く利用していただくであるとか。","voiceIndex":46,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"どのような質疑が行われたかを知ることは、議会制民主主義、質問を通して住民要望を実現させる私たち議員にとって重要であることは言うまでもありません。伺います。事務局に依頼すれば、暫定的に紙で出していただく校正中の議事録、それと、ＰＤＦによる校正原稿のホームページへの掲載、最終的に、会議録検索システムの掲載、それぞれどれぐらいかかるのか伺います。","respondent":"大澤区議会事務局長","answer":"議事録についてです。現在、校正前の議事録の作成には１週間程度かかっております。その後のホームページの掲載は、速報版を、本会議は１週間程度、委員会は２週間から３週間程度でアップしています。正式な会議録としましては、掲載まで２か月ほどを要しているのが現状です。","voiceIndex":48,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"１０日とかかかるときもあります。基本、私は、議会改革検討委員会で、議員間で、必要性、緊急性について共通認識をまずつくって、しっかり議会として予算要望すべき性格のものだと認識はしておりますれども、しかし、これが開かれていないのです、残念ながら。伺いたいのですが、２０１９年改選期からの５年間弱の間に、この議会改革検討委員会は何回開催されたのか。この直近の５年間、伺いたいと思います。","respondent":"大澤区議会事務局長","answer":"議事録の作成を早めることにつきましては、例えば、反訳の納品についての契約変更ですとか、ＡＩを活用した文字起こし等、幾つか方法はあるかと存じますが、いずれもそれなりの費用がかかること、また、それぞれに様々課題もありますので、検証が必要だと認識しています。","voiceIndex":50,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"これを改革しなければ、私たちは、言論による政治改革、施策の実現を目指す、それが私たちの仕事なわけですから、ぜひ、今、区長はたまたま退席されておりますが、区長を先頭に、議会からも、こうした改革を進めていくという立場で予算もつけていければいいと思いますので、その際は、ぜひ区長部局の皆さん、ご検討をしっかりよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"よろしくお願いします。私からは、５０ページ、特別区民税、１５２ページ、財政調整基金、１５１ページ、ふるさと納税寄附金など、歳入全般にわたってお聞きいたします。先ほど、特別区民税の減は所得税減税の関連もあるということでしたけれども、特別区民税が減っていて、しかし、歳入全体が増えているということについてのご所見をお伺いいたします。","respondent":"遠藤財政課長","answer":"今回、区民税が減っているというところで、そこの部分が減っているのにというところですが、地方特例交付金がございまして、そちらの部分で減収分については国のほうから補填していただけるという流れになっておりますので、減収分については。","voiceIndex":54,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。そうした特別区民税が減っていくような状況でありますので、私としては、事務事業評価とかで、やはりシビアに見ていって、真に必要な行政サービスの絞り込みなどを行っていって、今後の予算立てをしていくべきかと考えているのですけれども、そのもろもろ、今述べたことを踏まえまして、今後の予算立てについてのご見解をお聞かせください。","respondent":"遠藤財政課長","answer":"今後の予算立てですけれども、１つは、人口動態がありますけれども、何よりも経済状況の影響が大きいかなと考えているところです。","voiceIndex":56,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"基金のお話が出たのですけれど、品川区財政調整基金、その繰入れの判断といたしまして、品川区財政調整基金条例が、１つ、特に第１条が、繰入れ判断の解釈に使われるのかなと考えておりますけれど、経済環境の変動その他の事情により生じる年度間の財源の不均衡を調整し、財政の健全な運営に資するため、繰入れをしていくのかと考えておるのですけれど、区民の方から、基金があるので。","respondent":"遠藤財政課長","answer":"どのような判断というところは、なかなか一言で説明するには難しいところではあるのですけれども、例えば、来年度予算におきましては、２１億円ほど繰入れをさせていただいているところがあります。","voiceIndex":58,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。結構、基本的な部分に充てていたり、また一方で、当然、大災害とかコロナのような大型感染症のときは、かなり多めに出していくというお考えなのか、また、積立ての目標はあるのでしょうか。順調に令和２年度、令和３年度、令和４年度、増えておりますけれども、幾らぐらいまで積み立てていこうかというお考えが何かあるのでしょうか。","respondent":"遠藤財政課長","answer":"ただ、他区の状況などを見ていますと、今、特別区の平均で、財政調整基金は３５０億円ほど平均で積んでいるというところもありますので、ここの部分については、何が適正かということは考えていかなければいけないかと思っているところです。","voiceIndex":60,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。当然、大規模な災害とか、すごい金融危機とか、異常な事態が起きた場合は、積極的に区民のために使っていっていただけたらと考えています。よろしくお願いします。最後、ふるさと納税を伺いますけれども、減収額、令和５年度４５億円ほどということでしたけれども、今年度、令和６年度の減収額の見込みをお知らせください。","respondent":"提坂税務課長","answer":"令和６年度につきましては、まだ確定値ではございませんけれども、５０億円を超える見込みです。","voiceIndex":62,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"そろそろいい加減にしてほしいというような感じなのですけれども、しかも、品川区民に返礼品を期待して寄附する場合、こういうこともあるかと思うのですけれども、２０１９年６月１日から、それも駄目になったということで、最低限、品川区民の方が品川区に寄附していただけるように、もう１回、そういう制度の変更を区長会でぜひ提言していただきたいと思っているのですけれども、その点。","respondent":"提坂税務課長","answer":"区民の方が品川区に寄附するということ自体が禁止されているわけではございませんで、ただ、返礼品がないという条件がついているです。中には、返礼品は要らないので寄附をしたいという方も、年間、毎年１０件から２０件程度はあります。","voiceIndex":64,"id":"exchange-030"},{"speaker":"筒井委員","kind":"意見","question":"そうしていくうちに、いろいろなサイトに載ることで、結果的に品川区のシティプロモーションとか、品川区のＰＲになると思いますので、どんどんこれからの区内イベントは、ふるさと納税を活用していくべきだと考えておりますけれども、その点、お考えをお聞かせください。","respondent":"提坂税務課長","answer":"それからシティプロモーション、そういう観点で、クラウドファンディング型ふるさと納税も進めてまいりますし、区の魅力を発信する体験型返礼品も、なお一層拡充してまいりたいと考えています。","voiceIndex":66,"id":"exchange-031"},{"speaker":"筒井委員","kind":"提案","question":"その方は非常にすばらしい方ですね。よろしくお願いします。今年度、庁舎内の有料広告とか、カプセルトイとか、職員の提案でやられるということで、その理由がふるさと納税でどんどん減収しているからということだったのですけれども、非常に悲しい状況が、本当に焼け石に水になってしまうかなと思っているのですけれども、ぜひ頑張っていただきたいと考えております。","respondent":"佐藤経理課長","answer":"庁舎内の広告の件でご質問いただきました。こちらは、場所といたしましては、庁内のトイレですとか、あるいは、エレベーター内を検討しています。募集に関しては、来年度、４月以降に、要綱等を定めた上で募集して実施していこうというふうに考えているところです。","voiceIndex":68,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"当然、庁舎内ですから、区役所に来られる区民の方にも配慮した、いわゆる景観的な配慮も含めたものが必要かと思いますけれども、ぜひ積極的に進めていっていただきたいと考えております。今後、ゆくゆくは、庁舎内から庁舎の外に展開していくということも考えておられるのでしょうか。","respondent":"佐藤経理課長","answer":"今年度は庁舎内の広告ということで、職員提案の中から事業化したところです。今後につきましては、今回のものがテストケースになろうかと思いますので、効果等を十分把握した上で、全庁に展開するようにいたします。","voiceIndex":70,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"ネーミングライツとか、いろいろ外向けのものも今後あり得るかなと考えていますので、庁舎内の今回の実績とか影響を見て、ぜひ積極的に有料広告を進めていっていただきたいと考えております。よろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"１４３ページ、校内別室指導支援員配置事業について質問をします。この校内別室指導支援員配置事業については、学校内に別室があることで、学びの場の選択肢が増え、生徒を支えて受け止めることができるのではないかと思います。東京都の事業で、現在実施している学校数と支援員の人数を伺います。併せて、本事業内容では、どのような生徒が利用できるかなど、生徒側の条件を教えてください。","respondent":"丸谷教育総合支援センター長","answer":"現在、校内別室指導支援員の配置ですけれども、区立中学校１校で行っておりまして、支援員は２名おります。学校には登校できますが、教室には入れない生徒を対象に行っている事業です。","voiceIndex":74,"id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"今、１校で実施しているということですけれども、生徒の利用状況はいかがでしょうか。マイスクールに通う生徒もいらっしゃる場合があるかと思いますが、校内別室とマイスクールの選択はどのように、生徒が選んでいらっしゃるのでしょうか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"現在の利用状況ですけれども、教室に入れない生徒が数名利用しているということで確認ができております。学校に登校できない生徒については、マイスクールという選択肢がありますので、ご家庭とよく相談して進めているものです。","voiceIndex":76,"id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"生徒とご家庭で選択ができて、また、校内別室指導とマイスクール、それ以外の選択肢も生徒が決めることができるように提供していただければと思います。令和６年度からは、区独自で支援員を全校に配置するということですが、その詳細をお知らせください。義務教育学校は前期と後期がありますが、それぞれ配置する予定でしょうか。週にどれくらいの配置を考えられますでしょうか、教えてください。","respondent":"丸谷教育総合支援センター長","answer":"令和６年度には、校内別室指導支援員の配置を全校で実施いたします。義務教育学校につきましては、小学校、中学校と同様の配置ということで、前期・後期を分けるという考えは今のところございません。","voiceIndex":78,"id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"義務教育学校では、学校全体で１名の配置、部屋も１つ用意するという考えでよろしいでしょうか。児童・生徒や保護者の全員が、状況に合わせて安心して通学できる、この校内別室指導の存在を知っておくべきだと思いますが、現在、１校で行われているということですが、生徒や保護者への、どのような周知をしているか伺います。こちらについては、どのように想定されていますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"現在の周知方法ですけれども、学校において、不登校傾向になられた方に対して案内をしている段階です。来年度につきましては全校で実施いたしますので、教育委員会からも広く周知できるよう、今、検討を進めているところです。","voiceIndex":80,"id":"exchange-038"},{"speaker":"せらく委員","kind":"確認","question":"分かりました。次に、支援員の募集について伺います。現在、区のホームページで募集の情報が掲載されていることを確認しました。雇用契約を結ぶものではなく、有償ボランティアとした理由を教えてください。研修制度などは予定していますでしょうか。そして、募集を３０名程度としていますが、人数について、どのようなお考えで決めているのでしょうか、教えてください。","respondent":"丸谷教育総合支援センター長","answer":"人数ですけれども、学校でも地域の人材等で見つけてくることを想定しておりまして、区としては、現在、３０名程度というふうな考えですけれども、それ以上、応募があった場合には、名簿には登載する考えです。","voiceIndex":82,"id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"募集に関しては、来年度まで期間が短いと思いますが、不登校および不登校傾向の児童・生徒の支援に意欲があり、サポートしたいという多くの方の目に触れていただけるように、応募していただけるような広報、周知をお願いいたします。ホームページ以外でも募集について広報しているかどうか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"現在、ホームページに掲載しておりますけれども、近隣の大学にも、学生ボランティアとして応募ができるように、今後、周知を図っていく準備を進めているところです。","voiceIndex":84,"id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"ぜひ多くの皆様の目に触れるようにお願いしたいと思います。校内別室指導の部屋について、最後に伺います。児童・生徒に寄り添った居心地のいい空間づくりも大切だと考えます。こちらは学校側での判断になるかもしれませんが、この事業の運営上でそういったしつらえにすることは可能でしょうか。","respondent":"丸谷教育総合支援センター長","answer":"部屋の工夫ですけれども、これは各校の工夫によるものと思います。掲示物ですとか、そういったものを、温かな空間づくりができるように働きかけも行っていきたいと考えております。","voiceIndex":86,"id":"exchange-041"},{"speaker":"せらく委員","kind":"質問・要望","question":"よろしくお願いします。事業の運営上での条件や注意点は、しっかり各学校へ周知、工夫を共有するなどして、区全体で取り組んでいただきますようお願いいたします。学校の独自の思いでできる取組もたくさんあると思いますので、区としてもそういった学校発信の独自の取組については、しっかり後押しをしていただきたいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問","question":"私からは、９９ページ、児童虐待防止対策等総合支援事業費補助金、１２９ページ、健康増進事業費、１５３ページ、地域振興基金繰入金、協働推進経費についてお伺いいたします。そこで、児童相談所開設時と新庁舎において、それぞれの会議体の工夫や、コミュニケーションプレイスの設計について、現在の区のご見解をお伺いいたします。","respondent":"長谷川児童相談所開設準備課長、山下新庁舎整備課長","answer":"子ども家庭支援センターとの合同援助方針会議や、合同緊急受理会議をオンラインで実施するなど、対応のスピード感を重視した手法を現在検討しております。会議室におきましては、ただいまお話がございました開設予定の区立児童相談所のように、庁舎の外に所在されている機関ですとか関係機関等とも。","voiceIndex":90,"id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"工夫をしていただいて、様々連携を進めていただきたいと考えています。４月から始まる東京都からのケースの引継ぎはとても大変な作業だというふうに、様々、児童相談所のほうから伺っています。２点目に、健康増進事業費についてお伺いいたします。睡眠に関する健康相談には、どのような内容がありますでしょうか。睡眠の量や質を高め、よりよい睡眠をとるための指針を教えてください。","respondent":"若生健康課長、榎本荏原保健センター所長","answer":"睡眠の質を高めて、よりよい睡眠をとるための指針です。国の健康増進法の基本方針です「健康日本２１」の第三次におきまして、健康づくりのための睡眠ガイドを取りまとめております。私からは、睡眠に関する健康相談についてお答えいたします。","voiceIndex":93,"id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目にいきます。地域振興基金繰入金、協働推進経費についてお伺いいたします。私は、地域において様々な場面でハブとなるコーディネーターが必要だと考えています。地域力を総合的に高めていくために、区民参加、仲間づくり、網の目を張り巡らせることなどを事業を通して構築することが求められていますが、マッチングの難しさについて区はどのようにお考えでしょうか。","respondent":"若生健康課長、宮澤地域活動課長","answer":"先ほどご案内した国の健康日本２１におきましても、休養や睡眠の指標が新たに追加されたことも踏まえまして、今後、ホームページ等でそうした情報発信をしていくことを検討するとともに、次年度。マッチングの難しさですけれども、例えば、機会を創出するというところで、先日も町会とＮＰＯとの意見交換会であったり、企業や団体同士の交流の場の創出も検討しています。","voiceIndex":96,"id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"地域づくりについて、人づくりは非常に重要で時間もかかりますので、ぜひ進めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-046"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"私からは、１５１ページのふるさと納税寄附金、時間があれば、１２５ページのベビーシッター利用支援事業についてお伺いします。お伺いしたいのが、先ほど、今年の見込みが５０億円を超えるのではないかと、それは２０％増であれば５５億円ぐらいになるのだと思うので、そのとおりだと思うのですが、流入のところで、見込みをどれぐらいと考えていらっしゃるのか。","respondent":"提坂税務課長","answer":"今年度１月末現在で、流入が２,４００万円余です。来年度につきましては、予算書どおり、クラウドファンディング型ふるさと納税、それから体験型返礼品の拡充ということをもって、全部で９,０００万円を見込んでいるところです。","voiceIndex":101,"id":"exchange-047"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"すみません、数字も含めて、もう一度確認ですが、一昨年が、たしか９,８００万円ぐらいだったと思うのですが、昨年が１,９００万円ということでよろしいのかということと、予測を立てた上で、当然、行動に落としていく必要がありますから、流入対策、もしくは流出対策、それぞれやっていく必要があると思うのですが。","respondent":"提坂税務課長、佐藤企画課長","answer":"流入額の件で少し確認するのですが、令和４年度、これはあくまでもふるさと納税の寄附金として１,９００万円余のご寄附をいただいたということで、それ以外に一般の品川区への寄附、これがふるさと納税を含んで。区といたしましては、いずれにしても、ふるさと納税の制度に対して、基本的に見直しを求めるとともに、そうは言っても、流出額が物すごい金額になっていますので、体験型の返礼品でありましたり、クラウドファンディング型。","voiceIndex":103,"id":"exchange-048"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"私は、これは税務課ではないのではないですかと以前もお話をしながら答弁をいただいていたと思いますが、来年度以降は、どこがお答えをされるようになるのでしょうか。それが正に所管だと思うので、それについてお聞かせください。","respondent":"提坂税務課長、佐藤企画課長","answer":"来年度の流入額というか予算額ですけれども、全部で９,０００万円、その中でふるさと納税の寄附という形で２,４００万円を見込んでいるところです。来年度、区として、流出額の抑制と流入の増を図るという方針といたしましたので、そこは税務課を主体としつつ、企画や広報も一緒になって、また各事業の充当先の所管も一緒になって進めていきたいと考えております。","voiceIndex":106,"id":"exchange-049"},{"speaker":"せりざわ委員","kind":"提案","question":"質問に応じてということで、それは当たり前で、そのとおりなのですけれども、これまで税務課が主体となってというところで、税務課が主になって、ほかの所管で何かいいアイデアがあれば、ふるさと納税で使えますよというような話をこれまでもしてきていただいていると思うのですが、それではなかなか、自分の仕事がほかの皆さんもあるから、なかなか前のめりにならなくて今に至っていると思うので。","respondent":"提坂税務課長","answer":"単なる入場券とかチケットということではございませんので、委員のご指摘したように、少しプレミアをつけたようなものをいろいろ工夫してまいりたいと考えています。","voiceIndex":109,"id":"exchange-050"},{"speaker":"せりざわ委員","kind":"提案","question":"ほかに幾つかご提案しますが、今、ふるさと納税、他区の状況を見ても、やはり２３区は特にそうですが、それぞれ、もうそろそろどこかでギアを上げないとということで、ほかのところも動き出していると思います。例えば、その１つが、ホテル、宿泊の補助になるかと思います。ご見解をお聞かせください。","respondent":"提坂税務課長","answer":"先ほどから申し上げておりますが、体験型の返礼品に重点を置いて拡充を進めるべく準備を進めているところですけれども、それと関連しまして、区に来てもらえるような返礼品ということで、区内のホテルの宿泊ですとか。","voiceIndex":111,"id":"exchange-051"},{"speaker":"せりざわ委員","kind":"提案","question":"最後に、もう１個だけ提案をしますが、先ほどのシティランのところで、筒井委員からもお話がありました。似たようなところではあるのですが、ぜひこれはシティランの所管からもご意見をいただきたいと思いますけれども、しながわシティラン、いよいよ品川区の一大イベントにこれからなっていくと思います。","respondent":"三井スポーツ推進課長、佐藤企画課長","answer":"そういった課題もありますので、シティランは、来年度、第１回目となりますので、そちらは開催を重ねていく中で、委員からのご提案も踏まえて、今後の研究課題とさせていただければと思います。ふるさと納税の活用に関するクラウドファンティング事業としてシティランは入っておりますので、様々検討してまいりたいと思います。","voiceIndex":113,"id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、その中から、１１５ページ、防犯活動団体支援、１２７ページ、ヤングケアラー支援事業、１４１ページ、いじめ防止対策事業助成金、時間があれば、諸収入で、１６３ページのマイガーデンについてお伺いしたいと思います。は防犯活動団体支援についてお聞きします。活動範囲は、品川区内全域でしょうか。近年、コロナ流行により中止になったと伺いましたが、再開はされたのでしょうか。","respondent":"河合生活安全担当課長","answer":"基本的に歳入のほうの、こちらは防犯カメラ、防犯の対策の助成金となっておりますので、この歳入は、これまでの実績を含めて計上しています。","voiceIndex":117,"id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ヤングケアラーという言葉を聞くようになったのも最近です。ヤングケアラーの立場に置かれた子どもや若者が、健康的で支えられた環境で成長ができるように、今まで埋もれていて届かなかった支援を届けていっていただきたいと思います。続きまして、１４１ページ、いじめ防止対策についてお聞きします。連携はどのように図っているのか。最近の区内のいじめ問題の状況と、その対応についてお聞かせください。","respondent":"勝亦総務課長","answer":"そういった中で、今、１月に開設したものから１９件ほど相談を受けております。そういったものに関しまして、事情をお伺いして、学校と状況を１つ１つ確認しながら、打合せ等をしながら対応を図っているという状況です。","voiceIndex":121,"id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問・要望","question":"子どもたちの様々なトラブルから発展するいじめ問題について、学校や教育委員会、あとは、区長部局に入られます弁護士などの意見も踏まえ、一丸となって対処していただきたいと思います。教育委員会について、追加でお聞きします。教育委員会の方の人選はどのように行っているのでしょうか。","respondent":"勝亦総務課長","answer":"教育委員会の人事案件ですけれども、まず、今年度、春に公募させていただきまして、６月に公募した方を候補者とさせていただきまして、９月の第３回定例会において議案提出させていただいて、任命していただいているところです。","voiceIndex":123,"id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"第３回定例会でも、お一人の方が任命されて、着任していただきました。もちろん、この方のときも、経歴などを拝見しますと、非常に申し分ない人物ですし、今の組織に必要な人選だと思われますが、毎回私たち議員は、経歴などの書面上の情報だけで判断をしなければならず、もう少し採用の狙いや人物のお人柄などの情報に触れる機会があればいいなと考えています。その辺はいかがでしょうか。","respondent":"勝亦総務課長、堀越総務部長","answer":"教育委員会の任命に関しましては、任命の同意を議会にいただく関係があります。そういった中で丁寧にご説明していくようにしていきたいと考えています。議会の中での選任同意に当たっては、地方教育行政の組織及び運営に関する法律の規定等に基づいて議会の同意を得るということで、例えば、議会運営委員会でのご説明ですとか、それは今までもやっていますし、より丁寧な手続。","voiceIndex":125,"id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私たちも判断という部分を任される以上、できれば様々な情報をいただきたいと考えています。今後も品川区の教育のために、一緒になって頑張っていきたいと思いますので、ぜひご協力をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-057"},{"speaker":"新妻委員","kind":"質問","question":"私からは、１２５ページ、病児・病後児保育委託、１３１ページ、東京ユースヘルスケア推進事業、不妊治療等支援事業についてお伺いいたします。そういう中にあって、そもそも４か所現在あるわけですけれども、絶対数が足りないということがまず第一前提としてあるかと思います。そして、現状どのように対応されているのかということをお伺いいたします。","respondent":"立木保育課長","answer":"こちらをできるだけ早く開設できるようにということで、今、クリニックにいろいろ当たったりとか、大きい病院にもお声をかけさせていただいたりするのですけれども、もろもろ諸般の事情によりまして、今のところ、まだ開設の見込みが立っていないというような状況です。","voiceIndex":130,"id":"exchange-058"},{"speaker":"新妻委員","kind":"質問","question":"諸般の事情、様々ご事情があるかと思いますが、その課題について、品川区がその支援ができるところはないのでしょうか。","respondent":"立木保育課長","answer":"例えば、町のクリニックで申しますと、開設に当たりましての補助金を出したりとか、運営に当たって、例えば保育士の雇用に関してのサポート等は、今後いろいろ考えていかなければいけないというふうには考えているところです。","voiceIndex":132,"id":"exchange-059"},{"speaker":"新妻委員","kind":"質問・要望","question":"この病児保育に関しては、預けるということだけではなく、ベビーシッターが活用できるというところがあるかと思いますが、そもそもこのベビーシッター、誰でもいいというわけではありませんで、病児シッターと言われているのでしょうか、病児を見られるシッターでなければいけないというところで、需要と供給がしっかり見合っているのかというところを確認させていただきたいと思います。","respondent":"立木保育課長","answer":"ベビーシッターは、今、保育支援課のほうで所管しているところではありますが、やはりまだベビーシッターの中で病児対応ができるシッターの数は十分でないというところは聞いているところです。","voiceIndex":134,"id":"exchange-060"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひシッターの育成を、品川区ができる取組をお願いしたいと思います。そして、次に、東京ユースヘルスケア推進事業についてお伺いいたします。この事業は、どのような予算なのか。どこの予算なのかということをお知らせいただきたいと思います。","respondent":"若生健康課長","answer":"東京ユースヘルスケアの予算についてですが、こちらは、充当先が不妊治療等支援事業となっていますので、これは１０分の１０で東京都の補助金ですが、こちらを活用いたしまして、今回、不妊治療等の相談事業を行っていくというような予定になってあります。","voiceIndex":136,"id":"exchange-061"},{"speaker":"新妻委員","kind":"提案","question":"この事業に関しまして、昨年の第３回定例会の一般質問で、私もこの事業を活用して相談体制を整えてほしいという、そういう趣旨の提案をさせていただきました。今回、職員提案ということで決定されたと聞いておりますけれども、どういう経過でこれに至ったのかということをお知らせいただきたいと思います。","respondent":"若生健康課長","answer":"こちらは、職員の方の提案で、所管も職員提案のプレゼンの場に参加させていただきまして、職員の方ご自身の当事者としての経験ですとか思い、そういったところで、なかなか相談につながることが難しいというか、お悩みですとか事情があったというようなことで。","voiceIndex":138,"id":"exchange-062"},{"speaker":"新妻委員","kind":"意見","question":"非常にいい形で実現になったのかなと考えています。不妊治療のことでご相談を受けた際に、様々保険適用になったことも大変ありがたいと。ただ、その上で、相談がしたいのだというお声がありました。そして、何よりも、自分がしたいというタイミングで相談がしたいと、そこが大事なのだというお声をいただきましたので、品川区がこれから始める相談事業について、少しお聞かせください。","respondent":"若生健康課長","answer":"電話相談については、月１回程度、現状はまだ確定していないですけれども、平日の夜間の時間帯に、これは予約不要で無料で行うことを想定しておりまして、オンラインでのＺｏｏｍ等を活用した相談、こちらについては対面でということで。","voiceIndex":140,"id":"exchange-063"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区も言っていただけるということで、相談の場が広がると考えています。品川区はこれからですので、しっかりと始めていただく中で、その需要と、また、皆様のお声をしっかり聞いていただきながら、拡充も含めて、そこもご検討いただく中で、ぜひ進めていただきたいと思いますが、いかがでしょうか。","respondent":"若生健康課長","answer":"今後、これは新規の事業で、来年度、夏過ぎ頃から開始していく予定です。まだこちらについては準備の時間がありますので、十分中身、相談しやすい環境を検討してまいりたいと考えております。","voiceIndex":142,"id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問","question":"本日もよろしくお願いいたします。私からは、６３ページから６５ページの文化センターの使用料について、６９ページ、しながわ中央公園ボルダリング場について、１３１ページ、不妊治療等支援事業について質問をいたします。その中で、男性は相談できずに悩むことが多い。次年度からの開始になるとは思いますが、区独自の不妊治療助成について、男性不妊の場合も利用できるのかについてお伺いいたします。","respondent":"若生健康課長","answer":"男性でも相談しやすいような環境づくりというところで、これから事業を構築してまいりますけれども、十分検討していきたいと考えております。それから、不妊治療費の助成ですが、こちらについては、男性の不妊症の治療費についても対象とする予定です。","voiceIndex":146,"id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問・要望","question":"男性についても対象になるということ、また、相談事業についても、男性が利用しやすい視点ということ、今ちょうど検討段階ということでしたので、その検討の内容にもこの視点を十分に組み込んでいただきたいと思います。次に、文化センターの使用料についてです。どうぞご参加ください。」との記載がありました。文化センターの意義や役割についてお聞かせください。","respondent":"篠田文化観光課長","answer":"文化センターについてのお尋ねです。文化センターの設置につきましては、条例に、文化、スポーツ、レクリエーション等に関する活動の促進を図ることを目的とするとなっていますので、主に社会教育活動をすることを想定して設置されているものです。","voiceIndex":148,"id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問","question":"こちらは様々な方が利用できる交流するための施設というふうな認識をしておりますが、例を出すと、旗の台の文化センター、２階部分にあって、施設に入るまで階段があるために障害がある方が利用できない。このような区民の声は届いているのか、このような声に対してどのような対応をしているのか、また、区有施設のバリアフリー化に対する考えや課題、今後の展開についてもお伺いいたします。","respondent":"篠田文化観光課長","answer":"ですので、今後、建て替え等があったときには、そういったバリアフリーに配慮していくということで、一例を申し上げますと、最近、東品川の文化センターが大きく改築されましたけれども、その際には、大幅にバリアフリーに配慮した形での改築ということで対応していますので。","voiceIndex":150,"id":"exchange-067"},{"speaker":"ひがし委員","kind":"質問・要望","question":"改築の際には、もちろんバリアフリー化もしていただきたいと思いますが、現状、利用できない方々からは、古い施設ということで、随分前から言っているのだけれども変わらないというようなお声もいただいておりまして、どのような形であっても、機会を見ながら、また、対応も引き続き検討していただき、もし改築をする際には、障害がある方の声も計画の段階から取り入れていただきたいと思いますが。","respondent":"篠田文化観光課長","answer":"建物自体の古さ等々がありますので、すぐには難しいところがありますけれども、今、委員からご指摘があったとおり、改築の際の配慮と同時に、日頃からも職員のサポートで対応できる部分があれば、そこについては尽力してまいりたいと考えているところです。","voiceIndex":152,"id":"exchange-068"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ全ての方が利用できるような施設を区としても目指していただきたいというふうに要望いたしまして、次の質問に移ります。近年、スポーツクライミングは、国内だけではなく、世界的に人気が高まりつつあり、その競技人口は、国内で６０万人、世界で３,５００万人を超えると言われております。そこでお伺いします。ボルダリング場開設後の利用数、そして開設後からの利用状況の推移についてお聞きします。","respondent":"三井スポーツ推進課長","answer":"２月末時点ですが、月平均で大体２４０件ほどあります。最初２か月は、オープン当初は平均して３００件を超えていましたので、現在は少し減少傾向となっております。","voiceIndex":154,"id":"exchange-069"},{"speaker":"ひがし委員","kind":"意見","question":"現在、減少傾向ということで把握いたしました。初心者向けボルダリング教室の開催も行っていると思いますが、開催の回数、参加の数、また、利用の多い年代や利用した方の反応等があれば、お聞かせください。","respondent":"三井スポーツ推進課長","answer":"今年度、初心者教室は７月から実施しまして、現時点で６回ほど開催しております。人数ですが、今、手元になくて、合計ですと６５名の参加となっております。","voiceIndex":156,"id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは分かる範囲で結構です。それに加えて、先ほど言っていたように、利用者がオープン当初に比べて減っているということですが、区としての課題は、どのように認識していますでしょうか。例えばボルダリング教室利用者にアンケートなどをとって、利用の状況、何か不便があったのか、また、どういうところがよかったのかなど、声を聞くことも有効かと考えますが、いかがでしょうか。","respondent":"三井スポーツ推進課長","answer":"アンケートについては、今後、教室等でとれないかということは検討してまいりたいと思います。","voiceIndex":158,"id":"exchange-071"},{"speaker":"ひがし委員","kind":"意見","question":"私もボルダリングが好きで、議員になる前は週に１回ぐらいボルダリングへ通っていたのですけれども、アンケートをとっていただいて、そういう声を聞いていただくとともに、例えばですけれども、今、月１回ぐらいボルダリング教室を開催していると思うのですけれども、開催の時期を人気のやりやすい時期、気候が落ち着いている時期に多く開催したりとか、そういう工夫もされてはどうかと思うのですけれども。","respondent":"三井スポーツ推進課長","answer":"やはり委員おっしゃるとおり、夏とか、暑い日、寒い日とかというのは、なかなか教室は集まりづらい状況はありますので、今後、そちらも踏まえて考えてまいりたいと思います。","voiceIndex":160,"id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、せっかくできた施設ですので、どんどん利用者が少なくなるようなことがないように、拡大していけるように検討していただきたいと思っています。最後に１点だけ。もし変えられるとしたら、どのぐらいの頻度で変えていく予定なのかというところも、分かりましたら、教えてください。","respondent":"高梨公園課長","answer":"ホールドの配置だけではなくて、物自体も変わらないと、新しく魅力がないということもありますので、年２回、ホールドを購入して、４回変えるというところでやっているところです。","voiceIndex":162,"id":"exchange-073"},{"speaker":"ひがし委員","kind":"意見","question":"やはりそのように新しいものに変わったタイミングで、ぜひ周知、変えましたよというところをアピールする場になるのかなというふうに思いますので、その４回、今回変えていただいたときのタイミングで、来年度以降、実施する際には新しくなりましたというようなところを併せて周知をしていただければなと。それに併せて教室の開催の頻度等も検討していただければいいなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-074"},{"speaker":"中塚委員","kind":"提案","question":"１３９ページの災害対応力向上支援事業費補助金に関わって、防災費の財源と食事について、ペット支援とキッチンカーの活用についても伺いたいと思います。例えば、所管が予算を提案しても、補助金がない、補助金が少ない、一般財源が多くなるからと話が通らない、こうしたやり取りが、企画や区長査定であるのかどうか伺いたいと思います。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"区の防災事業につきましては、区内の実情に応じた事業を機動的に行うため、一般財源を中心に事業を実施していますが、活用できる国や都の補助は最大限活用する、これは区の方針となっております。そこで、予算書の１３９ページの２０節、医療保健政策包括補助金というところで、東京都の補助金になりますけれど、災害時動物救援事業ということで、経費の２分の１の補助率ということで、上限額１４５万円、こちらを満額活用して。","voiceIndex":166,"id":"exchange-075"},{"speaker":"中塚委員","kind":"提案","question":"国や都の補助金の活用はしていきたいということですが、私が伺ったのは、所管が予算を提案しても、補助金がない、少ない、一般財源が多くなるからと話が通らない、こうしたやり取りがあるのかと伺いました。お答えください。","respondent":"平原防災課長","answer":"事業を提案するに当たりましては、事業の必要性について提案させていただいておりまして、財源という形では、特にこちらのほうからその種類について言っているものではございませんし、もし仮にそこに国や都の補助金等がございましたら、そういったものを活用するということで。","voiceIndex":169,"id":"exchange-076"},{"speaker":"中塚委員","kind":"提案","question":"現状では、ペットについては若干ある、キッチンカーについては全くないということですけれども、必要性を認めているのですから、積極的に事業展開をしていく必要があると私は思いますが、いかがでしょうか。","respondent":"遠藤財政課長","answer":"もちろん国とか都の補助金があれば、そちらを積極的に活用するということは事実ですけれども、それがないとしても、やはり必要なものについては、きちんと措置するという考えで、この間、査定をしています。","voiceIndex":171,"id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"これまでも、食事についても、ペットについても、障害者についても、高齢者に対しても、住宅についても、トイレについても、いろいろなことが、阪神・淡路大震災、東日本大震災、熊本、能登、繰り返し同じことが言われているのに、なかなか進まないのは、結局は、国が方針を立てなければ、都が方針を立てなければ、それに補助金がつかなければ。","respondent":"遠藤財政課長","answer":"今後も一般財源の使い方も含めまして、様々なご意見等を頂戴しながら、こちらの施策をつくっていきたいというふうに考えているところです。","voiceIndex":173,"id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、ペットの災害時の支援についても、区議会でも様々声が上がりながらも、結局、国がペットの同行支援に言及して、それを受けた形で補助金が出て、ようやく品川区が動き出している。しかし、同伴避難については、まだ国も出さない、メニューもない、だから区が動けないと、これではいけないと思いますので、区民に寄り添った防災対策を強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１５５ページの奨学金貸付金返還金に関わって、区独自の奨学金実施を求めて質問します。貸付金返還金は、以前の制度で高校生や保護者に貸付けを行っていたものですが、来年度、１,４７８万円余の返還見込みとなっております。現在の返済をしている方の人数を伺います。","respondent":"飛田子育て応援課長","answer":"平成３０年度からは制度改正を行いまして、在学応援資金を創設の上、返還免除型を導入しております。委員のご質問の現在の貸付けの状況ですが、令和６年１月現在で２２４件中７６件ほどの滞納が発生しております。","voiceIndex":177,"id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"今、２２４件ということは、全体の返済している方が２２４人ということだと思いますけれども、高校生から借金を負わせるというのは、将来に希望が持てない社会になっていると思います。全額あるいは一部免除をすべきだと私は考えます。制度を始める前と後の公平性を言ってしまったら、どのような制度も始められないと思いますが、いかがでしょうか。伺います。","respondent":"飛田子育て応援課長","answer":"滞納とか返済につきましては、やむを得ない事情がある場合には、こちらも相談に応じて、さらに分割するなど柔軟な対応をとっているところです。","voiceIndex":179,"id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"私が伺ったのは、制度を始めるに当たって、前後の違いはあるということなのです。返済を免除するときには不公平と説明するのはなぜなのか、伺いたいと思います。ぜひこの制度を前進させていくことが必要だと思うのですけれども、いかがでしょうか。子どもたちの明るい未来のためにも、返還金の免除に踏み出すべきだと思いますが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"今回、この在学応援資金のほうでも返還免除ということで、ほとんどの方が返還を免除というふうになっております。ここのところですが、制度上の違いというところで最初の枠組みをしっかり守っていきたいと考えています。","voiceIndex":181,"id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"少し説明がよく分からなかったのですけれども、この制度をよくしていくときには、やはり違いが生まれると思うのです。ぜひこの点でも返還免除に踏み出していただきたいと思うのですけれども、改めて伺います。","respondent":"飛田子育て応援課長","answer":"ただ、新しい制度については、応援資金ということで返済免除も頑張ればしますよというところで最初にうたっております。そこのところは、やはり大きな違いではないかと考えております。","voiceIndex":183,"id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"制度が変わったということでおっしゃるのですけれども、本人にしてみれば、１年遅く生まれていれば自分も免除されたのにというふうに思う気持ちは同じだと思います。それは強く要望しておきたいと思います。この間、大学生等への給付型奨学金を求めると、国や他区の動向を注視すると答弁されています。注視した現在の結果はどうなっているのか伺います。","respondent":"飛田子育て応援課長","answer":"教育費に対する補助、また対象者数も多く、１人当たりの金額も高額になるため、所得の再配分や世代間配分の在り方、また、税や社会保険料を含む負担と給付のバランスなど、高い視点から全体を見据えた議論が必要であり、根本的には、各種制度を設計している国や都において、議論。","voiceIndex":185,"id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＯＥＣＤ加盟国でも下から２番目という状況です。卒業する頃には数百万円、多い人は１,０００万円以上の借金を抱えて社会生活をスタートさせるということになっています。一義的には、国が全体でやるべきだと思いますけれども、その中で区ができるところで、ぜひ大学生等への給付型奨学金に踏み出していただきたいと思います。実施できない理由はあるのでしょうか、伺います。","respondent":"飛田子育て応援課長","answer":"現在そういった格差是正のために、低所得や成績優秀者などを対象とした給付型の奨学金、主に中間層を対象にした貸付の奨学金については、国や日本学生支援機構、また各大学に多くありまして、近年は一定程度充実してきていると認識しております。","voiceIndex":187,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"充実しているということは、もう十分だというふうに感じているのか伺いたいと思います。私は、国の制度などでも十分ではないと思います。全体の学生の１割しか対象にならないということで、やはりその受皿を増やすためにも、区独自の実施をしていただきたいと思います。そうした中では、ウェルビーイングの観点からも、意に反するものだというふうに思うのですけれども、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"ただ、やはり１人に対してそれだけの税金を投入してよいのか、また、基準を満たしてよいのか、選考に漏れてしまった人、僅かな所得超過で対象外だった人、そういう方、もろもろ考えますと、区単独で実施するには、まだ課題が多いと感じているところです。","voiceIndex":189,"id":"exchange-086"},{"speaker":"澤田委員","kind":"質問","question":"私からは、１１７ページ、高次脳機能障害者支援促進事業について質問します。令和６年度の都補助金は１１９万２,０００円となっていますが、令和５年度は１５７万９,０００円となっております。３８万７,０００円の減額となっていますが、こちらについては、どのような部分が減額されたかについて教えてください。","respondent":"松山障害者支援課長","answer":"高次脳機能障害者の支援促進事業の減額の理由についてです。高次脳機能障害者の専門相談員の配置などを含めまして、事業については変更はなく、専門相談員の人件費分は変わりません。","voiceIndex":192,"id":"exchange-087"},{"speaker":"澤田委員","kind":"質問","question":"こちらの事業が何か変わるということではなく、今まで外部に委託していた講師料の部分を、作業療法士などの方を用いて行うことで削減できたということが分かり安心いたしました。今お話しいただいた支援者研修、高次脳機能障害者サポーター養成講座を行っていますけれども、こちらの実績と、実際に参加された方たちからどのようなお声があったのか、もしあれば教えてください。","respondent":"松山障害者支援課長","answer":"今年度は５回実施いたしまして、参加者数は延べ２４人でございました。内容につきましては、障害や脳機能についての知識を習得し、理解していただくとともに、言葉を使わずに意思を伝えるなど、実践的なコミュニケーションを体験していただきました。受講者の方からの声です。","voiceIndex":194,"id":"exchange-088"},{"speaker":"澤田委員","kind":"質問・要望","question":"理解が深まったというお声もあるということで、やはりまず理解して、それから、それに対応できる方法を学んでいくということは本当に大切なことだと思いますので、今後とも積極的にこちらの活動についても周知していただきたいと思っているのですが、区としては、サポーター養成講座をはじめ、障害の認知や相談窓口があるという情報など、どのような周知を行っていますでしょうか。","respondent":"松山障害者支援課長","answer":"その動画につきましては、ケーブルテレビ品川、しながわホットほっとや、しながわネットＴＶ、ＹｏｕＴｕｂｅで３月中に放映する予定です。","voiceIndex":196,"id":"exchange-089"},{"speaker":"澤田委員","kind":"質問・要望","question":"ホームページやリーフレットだけでなく、新たに動画、特にケーブルテレビ品川に３月中に動画の放送があるということで、情報を求める方々にも広くお伝えできると思いますので、大変うれしく思います。","respondent":"松山障害者支援課長","answer":"さらなる周知ということで、委員ご提案のＳＮＳを使った周知等も積極的に進めてまいります。","voiceIndex":198,"id":"exchange-090"},{"speaker":"澤田委員","kind":"質問","question":"ぜひよろしくお願いいたします。それと、先日、ぐるっぽにて、当事者と、その家族と、施設の方々の交流会が開催されたと参加された方から伺いました。ぜひ区としてもサポートしていただけると、より充実したものになるのではないかと考えられますが、区としてのご見解をお聞かせください。","respondent":"松山障害者支援課長","answer":"今後どういった内容にしていくのか、充実させていくのかにつきましては、参加される皆さんのお声を取り入れながら、一緒にどういう形でつくっていくのかということを、指定管理者、区も一緒に考えていければと考えています。","voiceIndex":200,"id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お願いします。私からは、１５０ページのふるさと納税、そして、人権問題で３つ、５０ページの特別区民税と、１１５ページの人権啓発事業、１４７ページの人権尊重教育推進費、時間があれば、９９ページと１２７ページのヤングケアラー支援で聞きます。昨日に続いてなのですけれども、先ほどご答弁がありました９,０００万円、歳入の予定の内訳を改めてもう一度お聞かせいただいてもいいですか。","respondent":"提坂税務課長","answer":"一般分と合わせて合計９,０００万円という形になってあります。","voiceIndex":204,"id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、ふるさと納税での２,４００万円ということで、今年度は見込みは幾らなのか教えてください。","respondent":"提坂税務課長","answer":"今のところ、１月末の時点で、税務課として返礼品をお返ししている分が４０２万円、あと、子育て応援課の子ども食堂の関連が２,０５０万円余となっています。合計で２,４００万円余です。","voiceIndex":206,"id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、前年度と来年度、同じぐらいのふるさと納税の収入ということですか。","respondent":"提坂税務課長","answer":"流出額が年々２割増しぐらいで増えているということを懸念しまして、体験型返礼品の拡充ということで、例えば、事業所のご協力を得ながら、体験ツアーですとか、スポーツ体験、あと、先ほども少し申し上げたのですけれども、区内のホテルに泊まれる電子クーポン。","voiceIndex":208,"id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"昨日は、さらば青春の光という、かなりそこだけに焦点を当てましたけれども、それ以外でも、品川に関連しているような著名人の方とコラボするとか、返礼品の品物であれば、品川を拠点に置く企業とか、技術者とか、職人の方、ものづくりの町というふうに品川は言われているわけですし、ＩＭＡＧＩＣＡをはじめとして映像クリエーターの方たちもたくさんいらっしゃるところですから。","respondent":"提坂税務課長、佐藤企画課長","answer":"区政にご協力いただいている区内の様々な企業の方のご意見等を聞きながら、体験型、事の体験の返礼品として導入できるものがないかということを模索していきたいと考えています。もう既に企画課と総務課と税務課と、関係各課でＰＴを組んで、今年度、検討も開始しておりまして、今回、様々な提案をしています。","voiceIndex":210,"id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問","question":"内容としては、例えば、障害者の方とか、性的マイノリティの方とか、外国人の方、そういった方について、例えば人権が守られていると、そういったようなことも当然教育の内容として入っていますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"今おっしゃっていただいたような人権課題につきまして、それぞれ学習を進めているところです。","voiceIndex":215,"id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"質問","question":"差別は許さないということで承知しました。人権啓発事業も同じような取組との理解でよろしいでしょうか。","respondent":"加島人権啓発課長","answer":"区の啓発事業におきましては、５月の健康週間ですとか、人権週間講演会におきまして、障害、それから性的マイノリティを含めた人権尊重のパネル展示を実施したり、また、割合としては少ないですけれども、多様性ということに着目いたしまして。","voiceIndex":217,"id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問","question":"少しお伺いしたいことがあります。２月２８日、衆議院の予算委員会の分科会で、在日コリアンへの憎悪をあおるデマとして知られる在日特権が取り上げられたと。日本維新の会の高橋英明氏が、税制面の優遇措置といった特権があるのかと質問しました。改めてお伺いします。品川区として、在日特権はないという理解、そして、そういう教育方針ということでよろしいでしょうか。","respondent":"加島人権啓発課長、提坂税務課長","answer":"私ども、そのような法的な定義ですとか、法務省が特に在日特権というもので言葉の定義をしているわけではないのですけれども、差別や偏見を生み出さないためにも、相互理解、多様性の尊重を進めていくことが大事だと思いまして。特別区民税、いわゆる住民税についても、前年の１年間の所得に応じて税額を計算しまして、国籍に関わらず、日本人、外国人の方に等しく課税しています。","voiceIndex":219,"id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"質問","question":"２３区唯一の人権尊重都市宣言をされている品川ですから、ぜひ子どもの教育段階、そして大人になってからの啓発事業としても、ぜひこういった差別、ヘイトをあおるような誤った情報、デマを教育段階から未然に防いでほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-099"},{"speaker":"つる委員","kind":"質問","question":"お願いします。９９ページ、困難な問題を抱える女性支援推進等事業費補助金、８１ページ、薬事衛生手数料、６１ページ、区民斎場使用料、７１ページ、児童センター使用料、高齢者多世代交流支援施設使用料について伺っていきたいと思います。この法律に基づく基本計画、品川区が、今、策定している段階なのか、また、その有無についてお知らせください。","respondent":"飛田子育て応援課長","answer":"困難な問題を抱える女性への支援に対する基本的な計画ということで、委員おっしゃるとおり、都道府県については義務づけられているということで、現在、区としましては、東京都の計画を参考にしながら、まずは関係機関との連携の在り方を具体化していきたいと考えております。","voiceIndex":224,"id":"exchange-100"},{"speaker":"つる委員","kind":"確認","question":"東京都の策定状況を確認してということで、関係機関ということでお話がありました。そこにつきまして、この法律に基づくものという部分において、既にあるもの、それから、特別区としてやるべきもの、また、努力義務等を含めて、できる規定とかがあると思いますが、そういう意味である有無について教えてください。","respondent":"飛田子育て応援課長","answer":"やはりポイントとなるのは、今までの「保護」から「自立への支援」ということになりますので、区としても包括的に提供していくことが大事だと考えておりますので、そのためには民間支援団体の協力が必要だと思っていますので、連携の強化をしていくことが必要だと感じております。","voiceIndex":226,"id":"exchange-101"},{"speaker":"つる委員","kind":"質問・要望","question":"今、民間団体との連携というふうに答えがありましたけれども、正に法律で規定されているところの大きなポイントの１つが、民間団体との協働連携というところがあろうかと思います。なので、この民間団体との協働を置くというところは、なかなか行政に助けを求められない、そういう方々、また求めようとしても求めることができないという、そうしたニーズのある方もいらっしゃるわけであります。","respondent":"飛田子育て応援課長","answer":"ですので、女性問題というのは、福祉部門だけではなく、やはり同じように保健部門、そういうところとも連携をとりながら、関係機関と調整の上で検討していきたいと考えております。","voiceIndex":228,"id":"exchange-102"},{"speaker":"つる委員","kind":"質問・要望","question":"私、ずっと指摘しているのは、やはり使われている古い言葉で「ゆりかごから墓場まで」という行政の利用についての部分の墓場についての課題、これは墓埋法でも、経営主体は自治体となっておきながら、基本的には、宗教法人だったり、民間の墓苑だったりが実態という中にあって、このお墓の課題、これ、ずっと墓じまいの課題とかと言われて久しいわけでありますけれども、ここについて。","respondent":"吉野戸籍住民課長","answer":"私ども戸籍住民課は、委員のご指摘のとおりですけれども、埋・火葬の許可証を実際に窓口でやっているところであります。墓じまいとか、そういったところの支援の在り方に関しましては、今後の検討課題といいますか、研究させていただきたいと考えています。","voiceIndex":230,"id":"exchange-103"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひそこまでやってほしいのです。やはり亡くなった後の安心感が生きているときの安心感につながるのです。火葬場を建設するときも様々な苦労があって、一部事務組合でやることができたという、こういったこともあるわけでありますので、そういう一部事務組合方式なども含めて、このお墓の課題については、ぜひ全庁的にいろいろな観点から検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-104"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、１５０ページ、ふるさと納税、１２９ページの医療保健政策包括補助金の予防接種について、時間があれば、国や都の補助金など全体的な少子化対策についてお伺いします。初めに、ふるさと納税ですが、この間、様々な質疑を聞いていた中で、１点気になったのが、いわゆる流出分の抑制をしていくというようなご答弁がありました。これについて、どのように抑制をしていくのか教えてください。","respondent":"提坂税務課長、佐藤企画課長、坂野保健予防課長","answer":"なかなか難しい問題です。今でもホームページ等々で流出額が大きいというところと、ふるさと納税に関しましては、区民の方に訴えかけているところですが。これについてですが、一応、今の予定では、令和６年７月頃をめどに、２万２,０００名の対象者の方に個別の接種通知を送ると、ただ。","voiceIndex":234,"id":"exchange-105"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これはやっているし、これからもしっかりと続けていっていただきたいけれども、でも一方で、喜んでいる人たちがいるのだから、それを抑制するというのは、区の行政として、あるまじき行為だと思いますが、改めてご見解をお聞かせください。なので、これはぜひ、こういった週間とかを通じて、そういった時期を見て、情報発信をしていただきたいと思いますが、改めて、その辺のお考えをお聞かせください。","respondent":"佐藤企画課長、坂野保健予防課長","answer":"やり方といたしましては、例えば、４５億円ありましたら保育園が複数つくれますとか、グループホームが幾つつくれますとか、そういった区民のサービスにつながるようなものとして、分かりやすく伝えていきたいというところで。ＨＰＶ月間、予防接種の週間のお話がありました。申し訳ございません、なかなかそれは対応できていなかった部分がありますので、次年度以降の課題とさせていただきたいと思います。","voiceIndex":238,"id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"分かりました。ふるさと納税は分かるのです。情報発信です。これ、無料です。この瞬間でも。なぜそう言っているのに、来年度にと、本当にこれはぜひ、私、さっき言ったのは、今日どうしても言いたかったのはなぜかというと、これ、週間中なのです。昨日、国際デーでした。だから私は発信をしてほしいと言っているのだけれども、なぜ来年度になるのでしょうか。もう一度ご答弁をお願いします。","respondent":"辻広報広聴課長","answer":"広報広聴課では、各所管からそういった何とか週間とか、そういったときに依頼をいただいて、今のところ発信しているところですが、来年度からは、戦略広報課となることですし、さらに私どもからもプッシュ式でやっていきたいと考えています。","voiceIndex":241,"id":"exchange-107"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"区長、区ができないのだったら、区長のＳＮＳでぜひ発信していただきたいと思いますが、ご意見をお聞かせください。","respondent":"久保田企画部長","answer":"そうしたいいタイミングになりますので、こういった機会を捉えて、啓発を進めていきたいと考えていますし、今日この委員会が終わりましたら、早速そういった形で情報発信をしていきたいというふうに考えてあります。","voiceIndex":243,"id":"exchange-108"},{"speaker":"えのした委員","kind":"質問","question":"私からは、１５１ページ、ふるさと納税寄附金から、孤独・孤立対策推進分、時間があれば、プレス発表、４８ページ、こころのセルフコントロール講習会についてお伺いいたします。そこでお伺いします。９００万円の予算は、ふるさと納税寄附金、こちらはガバメントクラウドファンディングだと思いますが、孤独・孤立対策推進分として選ばれた経緯、理由などをお知らせください。","respondent":"佐藤企画課長","answer":"ふるさと納税の充当事業の孤独・孤立の関係です。今回、このように複数充当するのは初めてというところで、区民還元、公益性、独自施策という３本柱で事業選定をしたところです。","voiceIndex":247,"id":"exchange-109"},{"speaker":"えのした委員","kind":"確認","question":"広域性、区の独自施策ということで確認がとれました。国は、令和４年度、総合経済対策事業の１つである地方版孤独・孤立対策官民連携プラットフォーム推進事業を開始し、品川区は、令和５年度、第２次募集に応募し、都内では、江東区と並び都内初の参加になったと厚生委員会でご説明があり、心強く存じます。これまでの複合的課題、隙間の課題、また取組についてお知らせください。","respondent":"東野福祉計画課長","answer":"重層的支援体制整備事業および孤独・孤立対策につきまして、私のほうから答弁します。重層的支援体制整備事業ですが、相談支援、参加支援、地域づくりの体制を整備し、令和７年度の本格実施に向けた検討を進めているところです。","voiceIndex":249,"id":"exchange-110"},{"speaker":"えのした委員","kind":"確認","question":"様々な取組を確認できました。ちょうど本日、庁内の研修会があったことを初めて知りましたが、これからも連携を深めて取組を進めていただければと思います。子育て世代、ヤングケアラー、ひきこもり等も懸念され、特に若者への対策が必要だと考えます。今後の取組として、子どもや若者層への対策や課題をお知らせください。今後の取組と、区のご見解をお知らせください。","respondent":"東野福祉計画課長","answer":"これらを孤独・孤立対策の切り口からプラットフォーム化しまして、若者層への対応などを補いつつ、庁内連携、ネットワーク間の情報共有、支援団体、企業との連携、アウトリーチなど、取組を行っていきたいと考えているところです。","voiceIndex":251,"id":"exchange-111"},{"speaker":"えのした委員","kind":"質問・要望","question":"様々課題があるようです。こういった解決を要望し、施策を進めていただければと存じます。区民、地域団体、行政など様々な主体が協働して地域福祉を推進していくための方針や具体的な取組を示すことを目的として、第４期品川区地域福祉計画の策定を進めていますが、先月の２月２２日までにパブリックコメントを募集していましたが、区民の方からどのようなご意見がありましたでしょうか。お知らせください。","respondent":"東野福祉計画課長","answer":"現在これらに対する区の見解を取りまとめているところです。パブリックコメントの結果につきましては、４月の厚生委員会でお示しした後、広報や区ホームページに掲載をしてまいります。","voiceIndex":253,"id":"exchange-112"},{"speaker":"田中委員","kind":"提案","question":"その辺の発信の仕方、区長がせっかくこれだけいい思いがあって、２,０３６億円、その中でも３８億円は、本来であればつかなかった予算が、まずは自らの事務事業評価をして、しっかり財源を自ら確保し、その上でリーダーシップを発揮されて予算編成に反映されているというふうに私は受け止めておりますが、まず、こういう受け止め方でいいのかどうかお聞かせいただきたいと思います。","respondent":"遠藤財政課長","answer":"今度、３月１１日の広報紙でも、こちらのウェルビーイングの予算も含めまして、様々区の施策としてアピールしていくところですので、引き続き、こちらの部分についても研究していきたいと思っています。","voiceIndex":256,"id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、情報発信という意味で、やはりしっかり、今度は広報広聴課から戦略広報課に変わるということもありますし、より力を入れていただきたいと思いますが、こういう中で、新井副区長は、都庁時代は総務課長をされていらっしゃって、局と議会との連絡調整担当ということで、しかも、当時、１人会派であった当時の森澤都議にもしっかり対応されていた。","respondent":"新井副区長","answer":"そういった意味においては、全ての委員の皆様に対して、説明をしっかり尽くしてまいりたいと考えていますし、呼んでいただければ、いつでも参りますので、引き続きよろしくお願いします。","voiceIndex":258,"id":"exchange-114"},{"speaker":"田中委員","kind":"質問・要望","question":"しかし、そこには、やはり森澤区長のウェルビーイングに対する思いが、新たな財源を創出できなかったとしても、しっかり予算に反映できるような、令和７年度以降の取組としては、そういう予算編成の在り方が求められてくると思いますので、そこは、もう時間がないので次に移しますけれども、今後の区長のリーダーシップを期待して質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":260,"id":"exchange-115"},{"speaker":"松永委員","kind":"質問","question":"１５１ページのふるさと納税寄附金についてでありますが、先ほど来、様々なご意見があったと思います。しかし、実現に向けて、ある程度の見込みが計算されているものだと私は思うのですけれども、その中で一般分とか、孤独・孤立対策とか、先ほど少し伺ったのですが、その中で、しながわシティランの１,５００万円についての内訳を教えていただければと思います。","respondent":"佐藤企画課長","answer":"寄附の歳入の予算計上というところで特に内訳はございませんが、先行自治体のほうで流出額の２％を目標に、様々な手段を用いて、それに近い数字は達成したという実績がありますので、区といたしましても、決して低くない目標だとは思っておりますが。","voiceIndex":262,"id":"exchange-116"},{"speaker":"松永委員","kind":"質問","question":"そこで、今月にしながわシティランのロゴの発表があると思われますけれども、そのロゴを使ったプレミアム返礼品を検討するなどの対策をしていかなければ、先ほど、近隣区では１,５００万円は妥当だということであったのですけれども、私からすると、そうした返礼品も考えていただければと思うのですけれども、これは改めてなのですが、しながわシティラン分のふるさと納税の寄附金については。","respondent":"佐藤企画課長","answer":"予算なので、そういう予算立てをしておりますけれども、様々な手段を使って、ふるさと納税を増収させたいと思いますので、今後も様々検討していきたいと考えています。","voiceIndex":264,"id":"exchange-117"},{"speaker":"松永委員","kind":"確認","question":"ぜひそうしたことも含めて積極的に頑張っていただければと思います。次に、７７ページの自転車駐車場使用料について伺います。現在、定期利用と当日利用の確認をさせていただいたところ、一時利用の自転車の台数が１０５万台と物すごい台数であり、昨年度の９５万台を大きく上回っております。この一時利用について、どのエリアを強化されたのか伺います。","respondent":"工藤交通安全担当課長","answer":"駐輪場の強化についてです。こちらにつきましては、自転車の利用が多いところ、例えば大井町駅前ですとか、西大井等を強化しています。","voiceIndex":266,"id":"exchange-118"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、現在の利用状況を伺ったのですけれども、それに踏まえて、大森駅前住宅の当日利用駐車スペースの利用率について伺いたいのですが、以前、一部を撤去されたということを確認させていただいて、今現在の大森駅水神口自転車等駐車場について、大井水神公園内と、区道歩道上の利用状況をお知らせいただきたいと思います。","respondent":"工藤交通安全担当課長","answer":"大森駅前の駐輪場の関係でお答えします。大森駅前水神公園のところですが、こちらは利用率が１００％を超えております。住宅前、南側住宅の真ん前にありますけれども、こちらは駐輪台数６０台程度になりますが、こちらも平均で利用率が８０％です。","voiceIndex":268,"id":"exchange-119"},{"speaker":"松永委員","kind":"質問","question":"１００％というのは、公園側のほうが１００％ということで、機械式のほうは１００％ではないのではないかと考えています。多分１０年ぐらい前になるのですが、その際に、今後どんどん検討していくということで、それからもう１０年がたっておりまして、いつまで検討されていかれるのかということで、併せてその辺も伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"こちらは３基ございまして、計７６５台収容可能な駐輪場になってあります。定期利用です。こちらは業者と話をしておりまして、当日利用が可能かどうかといったところも含めまして話をしているのですが、やはり機械の性質上、当日利用は難しいとなっています。続いて……。","voiceIndex":270,"id":"exchange-120"},{"speaker":"松永委員","kind":"質問","question":"どのくらいまであそこの歩道のところを駐輪場として使われるのかということで先ほど質問させていただいたので、そのことについて伺いたいと思います。次に、１２５ページのベビーシッター利用支援事業について伺います。この事業は、東京都が平成３０年度から、待機児童対策として実施されている事業だと認識しております。そこで質問いたしますが、現在の利用状況についてお知らせください。","respondent":"石井保育支援課長、工藤交通安全担当課長","answer":"ベビーシッター利用支援事業のうち、事業者連携型です。こちらは待機児童対策としてやっているのですけれども、今、令和６年度に向けて継続の勧奨などを行っているのですけれども、４０名程度のご利用がいるというふうに把握しています。大森駅前の駐輪場の検討の関係ですが、こちらは住宅前の駐輪場、先ほどお話ししたとおり、現在まだ８０％超の利用率があります。大森駅周辺の全体の利用率を確認しながら、撤去については検討してまいりたいと考えています。","voiceIndex":274,"id":"exchange-121"},{"speaker":"松永委員","kind":"質問","question":"ぜひそうした時期が来ましたら、大森の方たちに対しての周知をお願いしたいと思います。その次のベビーシッターのところは、お伺いしましたら４０名程度ということであります。実は、実質この事業に対しては無料でとても人気のある事業だと思います。","respondent":"石井保育支援課長","answer":"こちらは、例えば電子申請等々いろいろとやり取りをもっとスムーズにできないかということがありますけれども、やはり書類の審査はすごく煩雑になってございまして、まず、外部委託のために令和６年度予算で計上させていただいているところでございまして。","voiceIndex":277,"id":"exchange-122"},{"speaker":"松永委員","kind":"意見","question":"ぜひ進めていただければと思います。次に、７１ページのシルバーセンターの使用料についてです。この中で西大井いきいきセンターについてですが、料金表のところにいきいきセンターが載っているのですけれども、「シルバーセンター」と検索したときに、なぜ西大井いきいきセンターが掲載されていないのか、お知らせください。","respondent":"川原高齢者地域支援課長","answer":"西大井いきいきセンターについての説明です。西大井いきいきセンターについては、旧西大井シルバーセンターという形でございました。","voiceIndex":279,"id":"exchange-123"},{"speaker":"松永委員","kind":"質問","question":"こうしたシルバーセンターは、地域で生活する高齢者を対象に、ふれあいの場とか憩いの場ということで無料で活用しているかと思います。特に無料の方は、団体登録、登録された方のみだと思うのですけれども、その中で旗の台のシルバーセンターが昨年度４回となっておりまして、その利用状況について改めて伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"それに比べて有料団体が、今の状況としては１件のみの歳入という形でございまして、すごく差があるのが、地域の町会の方々の利用は、主にシルバーセンターではなく区民センター、近隣などに集会などの利用が多いのではというふうに考えられます。","voiceIndex":281,"id":"exchange-124"},{"speaker":"塚本委員","kind":"質問","question":"私からは、８１ページの廃棄物処理手数料、それから、５０ページの特別区民税に関して伺いたいと思います。最初に、廃棄物処理手数料ですけれども、去年の令和５年１０月に事業系のごみ処理券の料金が改定されました。","respondent":"品川品川区清掃事務所長","answer":"これは券の改定があったときということで、年に何回もあることではない、数年に１回というような観点から、窓口に来ていただくという対応をとっているところです。","voiceIndex":285,"id":"exchange-125"},{"speaker":"塚本委員","kind":"質問・要望","question":"これはもう１回ご答弁いただきたいと思います。２３区のよその区では、旧旧券であろうとも、新しい新券の値段に、差額を払えば交換しているという区もありますというところで、品川区としては、なぜそういった対応になっているのか教えていただきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"ただ、品川区としても、一定期間の間で、やはり時効という考えはあったほうがいいのではないかというところで、地方自治法の中での金銭の時効の５年を基本としまして対応しているものです。","voiceIndex":287,"id":"exchange-126"},{"speaker":"塚本委員","kind":"質問・要望","question":"ここについて、なぜなのだろうというところと、５０代、６０代、まだまだ現役で頑張っていらっしゃって、納税というところでも、品川区にとっては多額の税金を納めていただいているという方も多いと思われるのですが、この５０代、６０代の人が減っていく、転出が増えていく、この人たちは、どういった事情で品川区を離れていかれるのか。","respondent":"佐藤企画課長","answer":"６０歳ぐらいになると転出が多いのではないかということで、こういった傾向は以前から私どもとしても把握をしておりまして、詳しく調査をしたわけではありませんけれども、例えば、定年であったり、もしくは、自分のライフサイクルの変更といいますか、そういった時期に合わせて。","voiceIndex":289,"id":"exchange-127"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこで、５０代、６０代というところに焦点を当てると、やはり健康とかコミュニティ、会社勤めだとか、家庭の子育てとかが一段落して、コミュニティ、地域とのつながり、こういったところにおけるウェルビーイングの欲求が強まってくるのではないかというふうに思ったところなのですけれども、区として、５０代、６０代、ここについてのウェルビーイングというところの視点における施策の強化を。","respondent":"佐藤企画課長","answer":"今年度行った全区民アンケートで、８割の方が幸福だというふうに回答していただいておりますので、５０代、６０代の方もそういった数字なのかと思っています。来年度、実施計画の改定の中で、また詳しく検討してまいりたいと思っています。","voiceIndex":291,"id":"exchange-128"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"５９ページ、新庁舎整備負担金、これは国・都なのですけれども、新庁舎のことについて関連して伺いたいと思います。基本設計がもう佳境を迎えておりまして、これで決まるということであります。基本設計があって、これでいくのだというお話は伺いました。そういう品川区の庁舎を私はつくっていくべきだと考えておりますけれども、その外観に対する考え方をもう一度お聞かせいただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"こちらは、今後、実施設計を進めるに当たって、環境に配慮した外観を基本にいたしまして、区のシンボルとなるように、建設後も長きにわたり利用される建物として、区民に長く愛されるデザインを目指して実施設計を進めたいと考えているところです。","voiceIndex":295,"id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、今、シンボル的とおっしゃったわけだよね。それと、見劣りするとか、安っぽいというのは話は別だから、だから、ここら辺はそういうことをしっかり踏まえてもらって、あえて基本設計のここで言っているので、今後それをどうしよう、それでこの外観図が出てきたわけだから、これは私はそうではないだろうと思っているから質問しているわけで、それに対するお答えを正確にしていただきたい。","respondent":"大友新庁舎建設担当課長","answer":"今、イメージとして、単色でお示しをさせていただいているものについては、一例という形でご認識をいただければと思ってあります。","voiceIndex":297,"id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"確認","question":"ぜひそこの部分は、先ほど言った、私は、日建設計に３パターンぐらいあって、１回聞くということも必要かなと思っているけれども、今これが出てきて、単色、それではあまりに違うのではないかと思っているので、それはぜひ、今もう私の考えは言ったので、よろしくお願いします。それから、もう１個、８２ページの土木手数料から入ろうかと思っているのですが、建築確認等、これ、非常に減っている。","respondent":"長尾建築課長、崎村人事課長","answer":"建築職として入区している職員については、ＯＪＴに加えまして、品川区独自の、また２３区の研修に参加する、または一級建築士や建築基準適合判定の資格取得をする勉強の中で。確かに、他団体と比べると、構成比はかなり低い部分がありますので、適正数については、今後引き続き検討していきたいと考えています。","voiceIndex":299,"id":"exchange-131"},{"speaker":"せお委員","kind":"質問","question":"私からは、１６１ページ、庁舎内広告料等、１３５ページ、無電柱化推進事業についてお伺いします。そこで、この総合庁舎内への有料広告掲載事業は、なぜ庁舎内としたのかということと、これはスタートですので、初めは６３万円という予算額にしたという、そういう理由なのか、分からないですけれども、私としては、すごく慎重だなと思ったので、そこを含めて今後の有料広告の方向性を教えてください。","respondent":"佐藤経理課長","answer":"規模的には、かなり違うというところはご指摘のとおりかと思いますけれども、これまでもですけれども、税外収入の確保は、全庁を挙げて取り組んでいる、検討していますので、金額的にはかなり少ないところではありますが。","voiceIndex":303,"id":"exchange-132"},{"speaker":"せお委員","kind":"提案","question":"その検討の中で、まずは区内企業にヒアリング、意見交換してみてはいかがでしょうか。そのような機会は今後考えていますでしょうか。お聞かせください。このような今した提案だったり、都市ブランディングのところに含めるという形、そういったことについて区の見解をお聞かせください。","respondent":"佐藤経理課長、三井スポーツ推進課長、辻広報広聴課長","answer":"４月から準備に入りまして、７月ぐらいから掲載できればというふうには考えておりますので、その準備の段階で、委員ご指摘のように、広報ですとか。しながわシティランにつきましては、今、協賛金の募集を開始しようと検討しているところです。来年度から都市ブランディングを開始するに当たりまして、区の未来を考えるのは、行政だけではなくて、区民や地域の企業、そして区民の団体の方。","voiceIndex":305,"id":"exchange-133"},{"speaker":"せお委員","kind":"質問","question":"新しい魅力ある品川区を一緒につくっていければと思っています。次に、無電柱化推進事業です。ご存じのとおり、東京都の小池知事が国会議員時代から強力に進めてきた事業ですので、区市町村への補助金も国から都からと存在していて、品川区も活用している状況だと思います。目的の中での優先順位を教えていただければと思います。","respondent":"森道路課長","answer":"無電柱化の目的の優先順位ですけれども、今行っております競馬場通りや文庫の森の周辺ですけれども、そちらは防災性がやはり一番重要だろうというふうに考えているところです。","voiceIndex":309,"id":"exchange-134"},{"speaker":"せお委員","kind":"提案","question":"防災性ももちろん大切で、３点もちろん大切なのですけれども、私の中では、日々の安全みたいなところが第一かなと考えていまして、私の近所で言えば、桐ケ谷通りなどは、電柱がなくなれば少しだけ歩行が楽になるなというお話はよくいただいています。実際、私が毎日通っていても危険が多いのは確かです。このような提案を含めて、今後の方向性をお聞かせください。","respondent":"森道路課長","answer":"今、推進計画の中で進めているところですけれども、優先順位をつけまして、しっかりと進めていきたいというふうに考えているとともに、区民の方々の意見をというお話もございましたので、しっかりと計画の見直しには、お話を聞きながら進めていきたいと考えています。","voiceIndex":311,"id":"exchange-135"},{"speaker":"せお委員","kind":"質問・要望","question":"先ほどの広告料収入もそうですが、関連する企業や区民と共に、森澤区長になってから十分意見交換する場とかも増えていて、そういったこともさらに進めていただいて、新しいものが見えてきて、そういった視点で取り組んでいただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":313,"id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１１４ページの都補助金から、東京都が実施を決定した学校給食費無償化について伺いたいと思います。長きにわたって、この品川でも多くの要望の声が上がる中、昨年、学校給食費無償化が実施されました。都立の特別支援学校等都立校は、都が全額補助することになるのでしょうか。そして、それは今後、都の補助金として入ることになるのでしょうか、伺います。","respondent":"柏木学務課長","answer":"続きまして、都立特別支援学校の給食費補助の件ですが、こちらは東京都が直接行うというふうに聞いてありますので、こちらは都のほうで決定しましたら、品川区の予算計上の分は減額をするのかということは、調整しながら検討していきたいと思います。","voiceIndex":315,"id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。この半分というのも不十分だなというふうに思っているので、東京都にも働きかけたいなというふうに思っておりますが、共産党としては、無償化の対象を、私立、国立等、要は、区立以外に通う小・中学生全てに広げるべきだというふうに求めてきました。現在どういう検討がされているのでしょうか。私立や国立に通う人数、改めて伺いたいと思いますけれども、把握されているでしょうか。","respondent":"柏木学務課長","answer":"申し訳ございません。私立の人数ですが、資料を今持っておりませんので、すぐお答えできませんけれども、前回答弁した内容で変わりはないと思ってあります。詳細については、申し訳ございませんが、今はお答えできません。","voiceIndex":317,"id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、実施に向けての検討はされていないということでしょうか。","respondent":"柏木学務課長","answer":"実質的な検討といたしましては、教育委員会のほうではまだしていない状況です。","voiceIndex":319,"id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"プレス発表の際にも、区長から、憲法２６条などが言われて、義務教育は無償とすることが書かれているということで、それを見て私たちも感激したところですけれども、これからこれが、やはりこれだけ話題になっていますので、品川から全都へ、そして全国へ広がるといいなと、充実を求めて質問をしたいと思います。この学用品の無償化は、これは全く区の単費ということでいいのでしょうか。伺います。","respondent":"柏木学務課長","answer":"来年度予算で計上しております補助教材費の保護者負担軽減事業ですが、こちらは今回の事業評価でやっているウェルビーイング予算での計上になりますので、全て品川区の予算となります。","voiceIndex":321,"id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういう時点でもう特別支援学校の当事者や家族からは、また蚊帳の外だよと、こういう声も出ておりますので、当初からぜひそこは対象にすべきではないかと思いますし、今後、しっかり対象にしていくべきと思うのですけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"今回の補助教材費の補助ですけれども、こちらは、各学校、各学年の補助教材費によって補助金額が異なってあります。ですので、給食費のように、特別支援学校についてこのまま一律で実施できるかどうかというのは、非常に難しい部分があると考えています。","voiceIndex":323,"id":"exchange-141"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ実施に向けて検討していただきたいと思います。憲法の立場、そしてウェルビーイングの立場からも、区内に住む子どもたち全てが格差なく教育が受けられるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":325,"id":"exchange-142"},{"speaker":"西本委員","kind":"質問","question":"１０９ページの自衛官等募集事務費、そして、９５ページのぷりすくーる西五反田の件、３つ目が、１１７ページの公設民営保育園費をお聞きします。午前中にありました自衛官等の募集事務費、情報提供を品川区はしていないということなのですが、これは法的にやっていいということになっているのです。やってくださいなのです。本当にこれは感謝しております。区のお考えについてお聞きします。","respondent":"伊藤災害対策担当課長","answer":"午前中の回答にありますとおり、区としては、名簿を見ていただいて書き写すということはやっていますが、名簿提供はやってございません。ただ、そういった形で、しっかりと地域のために貢献をしていただける自衛隊の皆様にも、採用に協力できるように頑張ってまいります。","voiceIndex":327,"id":"exchange-143"},{"speaker":"西本委員","kind":"質問・要望","question":"これは理解が得られないと、個人情報にもなってきますので理解しますが、いずれはやはり協力してほしいです。それ以外のことには使わないのですから、紹介だけなのですから、ぜひ検討してください。強く要望しておきたいと思います。次に、ぷりすくーる西五反田ですが、これ、指定管理者制度という形で運営しているのですが、社会福祉法人化もやっていなければおかしくないですか。いつやるのですか。","respondent":"立木保育課長","answer":"指定管理の運営者は、ＮＰＯ法人から社会福祉法人に切り替わっております。今後、建て替えと認定こども園化のスケジュール等を、先日の文教委員会でもお知らせさせていただいたのですが、それに向けて、ここを検討していくという、そういうような形になってあります。","voiceIndex":329,"id":"exchange-144"},{"speaker":"西本委員","kind":"質問","question":"これは委員会でもいろいろお話が出ていると思うのですが、園庭とかの広さが足りないという、いろいろなハード的な問題がありますということなのです。ですから、あそこは、ぷりすくーるだけではなくて、隣に西五反田保育園があります。そういう広い意味で考えていかないと無理なのです。そこをどう考えていますか。もうそろそろ結論を出してください。","respondent":"立木保育課長","answer":"施設更新の時期にも来ておりますので、西五反田保育園の改築をした上で、その敷地の一部をぷりすくーる西五反田が利用することによって、認定こども園化のハードルになっておりました園庭の部分をクリアすると、そういうような形で、今、検討を進めているところです。","voiceIndex":331,"id":"exchange-145"},{"speaker":"西本委員","kind":"質問","question":"同じものをつくるのですか。ぷりすくーるは幼保一体施設となっておりますが、でも、隣に保育園です。同じような施設です。なので、認定保育園とか、こども園とか、いろいろ形式があると思うのです。なぜ隣と一緒に考えて、次の世代の保育園、幼保一体施設、今、こども家庭庁ができておりますので、それも含めて考えないのでしょうか。いかがでしょうか。","respondent":"立木保育課長","answer":"様々検討の中でも、そういった案も検討してきているところですが、やはりぷりすくーる西五反田、まだ１６年という形になってあります。","voiceIndex":333,"id":"exchange-146"},{"speaker":"西本委員","kind":"質問・要望","question":"そうですよね。それであるならば、なぜ、将来性を踏まえて、両方にもっと将来性の未来のある、そういう施設にしないのかなと思うのです。なので、それも含めて考えていただきたいと思います。それに関連して、１１７ページにあります公設民営化です。そうなると、品川区の保育園、私立、公立を含めて、補助金の関係がどうなっていくのか。そして、保育園の全体像がよく見えないので、そこを教えてください。","respondent":"今井保育教育運営担当課長","answer":"今後のあり方基本方針の中で、民設民営化の進め方ですけれども、現在の公設民営の形態ですと、１年ごとに運営業務委託ということで、保育園の業務内容について細かく仕様を定めまして、年度ごとに実施していただくというところで。","voiceIndex":335,"id":"exchange-147"},{"speaker":"西本委員","kind":"意見","question":"公設民営の運営費が変わらないことは分かっています。それで、この公設民営から民営化にするというときの、この基本方針の中に書いてあったのが、公私連携型保育所制度、これは児童福祉法第５６条の８ということを書いてありました。やはりこれは協力し合いながら、次の品川区の保育をどうしていくかということになると思うので、そこはどう考えられていますか。","respondent":"今井保育教育運営担当課長","answer":"公私の連携の部分ですけれども、先ほどお話し差し上げました協定のところで、区の基本的な保育の理念の部分については引き継がせていただきまして、それ以上のところについては、連携しながらきちんとした保育を提供していただくという意味です。","voiceIndex":337,"id":"exchange-148"},{"speaker":"若林委員","kind":"提案","question":"要するに、来年度は５０億円超の流出額があったり、また、一般のふるさと納税の流入という言い方なのですか、これが２,４００万円で予算が組まれたりということで、特に流出のほうで、この予算書の中で、例えば５０億円超の影響は、どこら辺に出てくるのか、どういうふうに見たら説明できるのかということをお聞きして、影響があるということであれば、区民にとって何が問題で。","respondent":"提坂税務課長、河合生活安全担当課長","answer":"ふるさと納税の減収額がどこに出てくるかですけれども、目に見えて予算書を見ても分からないのですが、特別区民税の収入見込額、ここの部分がふるさと納税による流出額を見込んで算出したものになってあります。適用事例なのですけれども、具体的に、たばこを吸った、ポイ捨てしたというところでの軽犯罪法とか廃棄物処理法の適用事例は、申し訳ありません、そこまでは把握しておりませんけれども、やはり他法令で適用するときには。","voiceIndex":340,"id":"exchange-149"},{"speaker":"若林委員","kind":"質問・要望","question":"見える化がされていない。そのためには言質が要る。警視庁からいらっしゃっている課長でもありますので、例えば、啓発看板とか横断幕、毎年予算を組んでつくっていただいて、町に張っていただいていますけれども、その中に、ポイ捨て条例という根拠とともに、法に抵触するのだということも、一歩強く、抑止力になるのであれば、ぜひご検討いただきたいという要望です。よろしくお願いします。","respondent":"遠藤財政課長、河合生活安全担当課長","answer":"大体学校が１校５０億円ぐらいと考えていますので、その分が丸々流出していますので、しっかり区民の方に周知をしていきたいというふうに思っています。他法令の抵触に関する表示につきましては、主管の機関と警察のご意見を聞きながら、効果的な広報啓発ができるように検討してまいります。","voiceIndex":343,"id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。５６ページの特別区財政調整交付金の普通交付金について、もう１つは、１７２ページ、区議会事務局についてです。昨日と今日と、ほかの委員の方からの質疑もありましたが、前年度比較でマイナス１１億円の４２０億円を見込んでいます。前年度比マイナス１１億円は、どのように見積もっていらっしゃったのか、財政の専門的な視点でお伺いいたします。","respondent":"遠藤財政課長","answer":"委員おっしゃるとおり、来年度から児童相談所の運営が始まりますので、その分につきましては、対応補正という形で６か月分が算定になっておりまして、３.５億円程度が入ってくるような形で考えているところです。","voiceIndex":347,"id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"提案","question":"これは、先日も質疑がありましたけれども、改めて確認したいのですが、令和６年度も５５.１％を維持するということで確認できるでしょうか。先ほどお話があったのですが、６か月分の、児相は１０月からなので、これが区のほうに入ってくるということは再確認させてください。この０.１％の中でやっていくのか、私も不勉強なのですが、その辺りはどういう形になるのでしょうか。","respondent":"遠藤財政課長","answer":"児童相談所の０.１％でやるのかですが、こちらは少しまた別の部分になりまして、その５５.１％の中でやっている区とやっていない区がありますので、やっている区については、ある程度、別の算定式がございまして。","voiceIndex":349,"id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問","question":"それが先ほどお話があった対応補正ということになるのかなと思いますが、いかがですか。","respondent":"遠藤財政課長","answer":"委員おっしゃるとおり、対応補正で対応する形になります。","voiceIndex":351,"id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"質問","question":"区長会の方々は、以前に財政配分で４５％だったものを５５％に変えてきたという歴史があります。お話が先ほど出ましたけれども、令和５年度末で８区が児童相談所を開設、令和８年度末には１２区となることが分かっています。練馬区においては、区長は、福祉行政に深く関わった方であります。これに対し、区長会の一員として、どのように思われているのか、感想をお伺いいたします。","respondent":"遠藤財政課長","answer":"私のほうで、財政の部分でという形になりますけれども、そこの部分について、今まで２３区一緒にやってきたところです。今でも特別区長会を通じまして、様々都と協議していますので、そちらについては継続してやっていくものかと考えているところです。","voiceIndex":353,"id":"exchange-154"},{"speaker":"高橋（し）委員","kind":"質問","question":"それに対して品川区がどうこうということではないですが、やはり２３区として足並みをそろえて、これから進んでいってもらいたいというところです。昨日、決意をお述べいただいた部分もありますけれども、都区財政調整の議論において、区長は区長会において、ぜひ前向きの姿勢でこれへ臨んでいただきたく、改めて心意気をお伺いいたします。","respondent":"森澤区長","answer":"一方で、やはり大幅な事務の変更ということは変わっていないというふうに思いますので、引き続き、品川区としては、しっかり児童相談所を設置していくという中で財源は確保していく、その点は変わらないと考えています。","voiceIndex":355,"id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区としてしっかりと財源を確保し、品川区のお子さん、そして保護者の方々のために、きちんと現在進めている区立児童相談所をさらなるしっかりしたものに進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":357,"id":"exchange-156"},{"speaker":"こしば委員","kind":"質問","question":"よろしくお願いします。私からは、１３９ページ、持続可能な地域公共交通実現に向けた事業補助金について質問します。そこで、まず、こちらの歳入となります事業の補助金が充当される本区の事業について教えてください。","respondent":"鈴木都市計画課長","answer":"来年度、持続可能な地域公共交通実現に向けた事業補助金というところで、予算書に記載の金額につきましては、まずはコミュニティバスの実施に、試行運行中なわけですが、様々なアンケートですとか、行う委託の検討経費に歳入で充てるとともに。","voiceIndex":359,"id":"exchange-157"},{"speaker":"こしば委員","kind":"質問・要望","question":"今、課長がお答えになりましたコミュニティバスの事業についてお伺いしたいと思います。基本的ですが、誰もが移動しやすい利便性の高さを求めていくのがコミュニティバスと捉えておりますが、お聞きします。このバスの運行を通じました区民の幸せとは何ぞや、教えていただければと思います。","respondent":"鈴木都市計画課長","answer":"区民の移動の手段も非常に充実しているというところではありますが、やはりより身近な、より短距離の移動、様々な新たな交通手段も出ていますので、そうしたところもしっかり検討しながらしていくことで、やはり多様な、より多くの移動について。","voiceIndex":361,"id":"exchange-158"},{"speaker":"こしば委員","kind":"確認","question":"現状では、判断基準の収支率が５０％であり、これは超えている。ただし、これはシルバーパス利用者を含めた数値であって、これを除いた場合は、実質はその半分程度と伺っております。以前、バスが試行運行を始める前にも聞いたのですけれども、このシルバーパス利用者も１人当たり２２０円を充当した運賃収入、この運賃収入を含めた運行実績を、今後、判断するということなのでしょうか。確認をお願いします。","respondent":"鈴木都市計画課長","answer":"現在、試行運行中のコミュニティバス「しなバス」につきましては、ご指摘のとおり、令和６年度の運行実績に基づいて判断をしていくですが、その判断基準が５０％という設定をしています。","voiceIndex":363,"id":"exchange-159"},{"speaker":"こしば委員","kind":"質問","question":"ぜひ公益の観点、また、社会状況を踏まえて判断をお願いしたいと思います。全国的に運転士不足が起こる中で、品川区では、全国に至る運転士不足をどのように評価、考えておるのか、また、実際、コミュニティバスを運行します東急バスのほうから、運転士の不足について、何か状況について聞き取りを行っているのか、教えていただければと思います。","respondent":"鈴木都市計画課長","answer":"コミュニティバスを運行していただいている東急バスとは、常日頃から様々な機会で意見交換を、情報交換をしていますが、やはりコロナ前の利用には、もう戻らないだろうというところで、区内のバス事業者におきましては、減便ですとか、ルートの見直しによって。","voiceIndex":365,"id":"exchange-160"},{"speaker":"こしば委員","kind":"提案","question":"大変憂慮しております。西大井の循環ルート、具体的に言いますと、西大井二丁目から六丁目区間、そのエリアを回るルートについて、質問・提案をさせていただきました。特に西大井本通りの道幅は、５ｍ程度の箇所も複数あり、車道にはガードレールはなく、道も蛇行を繰り返し、対向車を遠くから目で確認することが難しい道路事情もあります。","respondent":"鈴木都市計画課長","answer":"ＡＩを活用しました利用者のニーズに合わせて柔軟に運行する地域特性や一人一人の移動ニーズに合わせて少数の移動を担う面的なサービスとしてのオンデマンド交通、それから、電動で環境に優しく低速の小さな移動サービスとして。","voiceIndex":367,"id":"exchange-161"},{"speaker":"こしば委員","kind":"質問・要望","question":"先ほどの答弁で、秋頃、実証実験を行うということでございました。改めて、今はコミュニティバスをシルバーパスが運賃収入として見込まれているわけですけれども、こういった軽減策についても、ぜひ実証実験、オンデマンド交通の実証実験で取り入れていただきたいということを願いまして、質問は終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":369,"id":"exchange-162"},{"speaker":"松本委員","kind":"提案","question":"よろしくお願いします。私からは、１４９ページ、地所賃貸料の中からＥＶ、カーシェア収入、１５１ページ、これはカプセルトイのことかと思いますが、ノベルティグッズ売払代金、これらに関連して、職員提案制度について伺います。我々も考えていかないといけない。では、来年度の予算で計上されておりますＥＶ、カーシェア、カプセルトイは、これは職員提案制度によるものということです。","respondent":"岡秘書担当課長","answer":"人事評価と直接的に連動するものはございませんが、今回、人事異動に関しまして、人事課で実施しております庁内公募を活用して、提案者が提案事業を所管する課へ異動し事業に携わることができるよう、積極的に庁内公募制度の利用を進めるように声かけを行ってきました。","voiceIndex":371,"id":"exchange-163"},{"speaker":"松本委員","kind":"提案","question":"これは、提案された方が実際に事業に関われるかどうかというところで変わってくるのかなと。これ、具体的に、今回提案された方たちが手を挙げた際に、これはまだ確定ではないかもしれませんけれども、つながるというふうな、異動が可能かどうかというふうな、その辺りの見込みについては、いかがでしょう。","respondent":"崎村人事課長","answer":"ただ、現在、庁内公募を昨年度から試行的に実施しておりまして、庁内公募と職員提案を連動した形で異動ができないかということは、令和６年度以降、検討していきたいというふうに考えているところです。","voiceIndex":373,"id":"exchange-164"},{"speaker":"松本委員","kind":"提案","question":"そこは本当に、よりよい事業にしていくためには大事なことだと思いますので、ぜひ進めていただきたいと思います。職員提案制度自体は、これは過去にも品川区で実績があるというふうに聞きまして、当時は人事課が所管だったというふうに伺いました。一般質問でもあったかもしれませんが、審査基準についてもお伺いできればと思います。","respondent":"岡秘書担当課長","answer":"委員がおっしゃるとおり、以前は人事課の職層研修などで職員提案を実施しておりました。その際には、総務部長をトップとした審査会を開きまして、その中で優秀賞を取ったものを企画部門へ資料提供しておりました。","voiceIndex":375,"id":"exchange-165"},{"speaker":"松本委員","kind":"提案","question":"そうしたところで見られたということなのですけれども、逆に、プレゼンテーションをする側としては、例えば、今回、歳入増加策、カプセルトイなどは歳入増加につながるものかと思いますが、例えば今、市場規模がこのぐらいで、ターゲットはこういうところですというふうな、例えば、創業支援の際に事業計画を出したりすることがあると思いますけれども、そういったレベルの提案までなされたのか。","respondent":"篠田文化観光課長","answer":"こちらは、私どもの職員から提案されたものですけれども、例えば、市場規模でいえば、カプセルトイについては７２０億円ぐらいというふうに言われておりますし、また、提案に当たって、税外収入を確保するという意味で、近隣区、港区ですとか大田区も。","voiceIndex":377,"id":"exchange-166"},{"speaker":"松本委員","kind":"提案","question":"時間も限られておりますので、さらにカプセルトイについて伺いたいのですが、かなり研究されてご提案されたということは理解いたしました。一方で、カプセルトイについては、今、紙といいますか、プラスチックを使わないカプセルトイも発明されているということなので、こういったものを使うということも１つ考え方としてはあると思うのですが、いかがでしょうか。","respondent":"篠田文化観光課長","answer":"ただ、そういった新しい素材を使ったものに関しては、どうしてもコストが上がってしまうということがありますので、いわゆる税外収入確保の観点からいくと、少しまたなかなか難しいのかなということで、これから先を検討してまいりたいと思います。","voiceIndex":379,"id":"exchange-167"},{"speaker":"松本委員","kind":"質問・要望","question":"なかなか課題もいろいろあると思いますが、ぜひ前向きにいろいろなことを進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":381,"id":"exchange-168"},{"speaker":"藤原委員","kind":"質問","question":"５０ページ、区民税、１５０ページ、ふるさと納税。今日は、ふるさと納税を質問してくれた方、ありがとうあります。よく勉強になりました。私も今日、思い切りいろいろな発想が出たので質問していきたいと考えています。だから、私は、この後、ふるさと納税を伺いますが、課長、ふるさと納税、もう答弁しないでいいですよ。私には。今、品川区は、２３区で徴収率は何位ですか。","respondent":"提坂税務課長","answer":"令和４年度決算で申し上げますと、２３区中１位です。","voiceIndex":383,"id":"exchange-169"},{"speaker":"藤原委員","kind":"質問・要望","question":"簡単に徴収１位と言っても、対面とか、電話とか、本当に徴収が遅れている方にするのは大変だと思います。ぜひ職員の方たち、メンタル面も含めて、課長、フォローしていっていただきたいと考えています。これでいいです。だって、２３区の試験を受けて品川区と来てくださるのですから。だけれども、品川区愛、これを言うと、私、今、質問する前に考えました。でも、話したい。税務課長、いいですからね。","respondent":"佐藤企画課長、堀越総務部長","answer":"大変難しいご質問でありまして、ふるさと納税の流出額、流入額、先ほど来、答弁しているとおりですが、職員に努力義務を課すかは別として、様々な手法を使って。先ほど来、答弁させていただいていますように、クラウドファンティングの形式ですとか、体験型という形で、職員が実際にそういった事業に携わっている部分もありますし、そういう中で、今、委員がご発言なさった内容についても。","voiceIndex":385,"id":"exchange-170"},{"speaker":"藤原委員","kind":"質問","question":"その答弁を待っていたのです。そして、ふるさと納税できる所得がある方の３割から４割しかしていないのです、現実は。そして、その残った全国で６割ぐらいの方に、ぜひふるさと納税に参加してもらいたい。だからどうなのかと、品川区には伺わないですけれども、私は、これが現実だと思って、ありがとうございました。それで、これこそ１４６ページ、配当金で伺いたいのですけれども、会計管理室、出番ですよ。","respondent":"大串会計管理者","answer":"したがって、１４６ページのほうにも利子及び配当金ということで予算化しておりますけれども、約１億３,８００万円余ということで、大体、例年、１億円ぐらいずつは入ってきているというところ。それから、運用の基本方針です。","voiceIndex":388,"id":"exchange-171"},{"speaker":"藤原委員","kind":"質問","question":"かかってくると思うのですが、そこの証券会社の利率とか手数料とかが大きくなってしまうというと、また問題になると思うのですけれども、他区で結構いい実績が出ているところがあるならば、そこと話したり、勉強するなりして、パーセンテージ上は少しでも上になってもらいたいと思うのですけれども、大きく利率を取れるほうがいいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"大串会計管理者","answer":"債券の利率も上がってくるかと思いますので、また、その辺につきましては、情報収集を行いまして、なるべく確実で、かつ、有利なものを購入していこうというふうに考えているものです。","voiceIndex":390,"id":"exchange-172"},{"speaker":"藤原委員","kind":"質問","question":"最初に区民税を伺って、５６ページの特別区財政調整交付金も少し含むのですけれども、この基本になる人口動態についてお伺いしたいと思うのですけれども、私も本当に自分自身で少し勘違いしたのは、この区で一番人口が少なくなっていくのは、２０４０年か４５年ぐらいかなと思ったのです。だから、そこも含めて、人口動態を、企画課としてはどういうふうに捉えているか教えてください。","respondent":"佐藤企画課長","answer":"区の人口の形、ピラミッドと言いますけれども、星型とか、都市型と言われている分野にも入っておりまして、ここで生産年齢人口がたくさん多い都市をあらわしている形にも近いようになってまいりますので、生産年齢人口の方が多いところは、税収もありますし。","voiceIndex":392,"id":"exchange-173"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、品川区はすばらしいのですよね、人口動態においても。だって、日本全国でやっているわけですから。それと、今日、財調を伺おうと思っていました。そういう質問はできないと感じたのですけれども、副区長、総括質疑で思い切り伺いますので、答弁はカウントされませんので、もう長く答弁してくださって結構ですから、ぜひ楽しみにわくわくしながらやりたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":394,"id":"exchange-174"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、６０ページからのきゅりあんの自転車駐輪場の利用料について、１点伺いたいと思います。それから１０枚という数はどういうことでつくられたのか。私は、ぜひ、このきゅりあんの小ホールは、結構利用料もかかっていますし、全員に無料券を出していただきたいと思うのですけれども、その仕組みと、それから、要望に対してお聞かせいただきたいと思います。","respondent":"篠田文化観光課長","answer":"こちらに関しましては、貸出しのときにはご案内はしているのですけれども、ホームページ等では、ご案内が今まで漏れていたところがありますので、こちらについては早急に対応するようにしたいと考えているところです。","voiceIndex":396,"id":"exchange-175"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、この品川区も含めて、介護の現場で働く方の、どういう対象なのか、そのことについて伺いたいと思います。国のほうで少し調べたら、介護職に限定していまして、ケアマネジャーとか、リハビリ関係、看護師とかは対象にならないのか、その確認をお願いしたいと思います。それから、品川区としては、この対象をどう考えられているのか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区においては、直接処遇にかかる介護福祉サービス従事者を対象として今のところ考えておりますが、東京都が、先日、予算の説明会が開かれまして、ある程度の、例えば社会保険料の部分を、事業者負担の部分を含むとか、そういった新たな要素が提示されたりとかもしましたので。","voiceIndex":398,"id":"exchange-176"},{"speaker":"鈴木委員","kind":"質問・要望","question":"東京都も介護職とケアマネジャーで、それ以外のところは対象にならないのかと思ったのですけれども、そこのところの確認をもう１回お願いしたいと思います。そういうところからすると、介護職とケアマネジャーだけではなくて、介護の現場で働く職種全てを対象にして１万円の支給はぜひしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"区においては、ではどうしようかというところで、限られた予算の中で、どういった対象者にするかというのは、今後検討していきたいと考えています。","voiceIndex":400,"id":"exchange-177"},{"speaker":"大倉委員","kind":"質問・要望","question":"よろしくお願いします。１１７ページ、区内私立保育園経費に関連して、不審者の対応や保幼小連携について伺えればと思います。１４１ページ、部活動指導員配置経費補助金から、地域移行や部活動指導員について、時間があれば、６１ページのシルバー人材センターについて伺いたいと思います。初めに、不審者対策について伺っていきたいと思います。","respondent":"立木保育課長、石井保育支援課長、中谷指導課長","answer":"園によってまちまちですが、定期的に不審者対応訓練を実施しています。定期的に私立保育園長会にて、通知レベルではあるのですけれども、年に１回の不審者訓練があるのですよということを周知しながら。人材リストの作成につきましては、今年度、協議会を運動部で３回、文化部については２回ということで開催いたしまして、その中で検討を重ねてきました。","voiceIndex":404,"id":"exchange-178"},{"speaker":"大倉委員","kind":"質問・要望","question":"こうした訓練や対策についての実施検討について伺いたいと思います。部活動指導員は、リストをつくっていただいて、配って活用していただいているということでありますので、しっかりと活用いただいて、部活動の指導員を確保できる環境をさらに、６人の中の４人が部活動指導員として地域からということだったと認識しておりますので、ぜひ進めていっていただきたいと思います。","respondent":"立木保育課長、石井保育支援課長、中谷指導課長、三井スポーツ推進課長","answer":"園外保育、お散歩等での不審者対応ですけれども、こちらも園内と同じように、園ごとに訓練、それからあと、安全な場所、危険な場所。私立園においても、例えば、国の通知に示しているように、お散歩マップで警察の場所を事前に把握しておくこととか、あと携行品で。ご指摘いただいたスポーツクラブも、地域とのつながりというところで、関係部局と連携しながら。スポーツ推進課では、地域スポーツクラブのほうからいろいろ声を聞いている段階ですが。","voiceIndex":408,"id":"exchange-179"},{"speaker":"大倉委員","kind":"質問","question":"屋外での不審者対応ということで、通達を出しているというところですが、ぜひ訓練をしていただけるといいかなと思います。次の保幼小の連携について伺いますが、平成２２年に、品川区は全国に先駆けて、保育園、幼稚園、小学校が連携して、幼児期教育と小学校教育をシームレスにつなぎ、子どもが主人公である成長過程をつくる保幼小ジョイント期カリキュラムが作成されたとホームページも載っておりました。","respondent":"中谷指導課長、三井スポーツ推進課長","answer":"部活動の地域移行ですが、教育委員会としましては、今後も協議会を継続して開催してまいりたいと考えています。スポーツ推進課といたしましては、既に自主的にアンケートを実施していただいた地域スポーツクラブを中心に、今後。教育委員会としましては、今年度、１２月に研究園として連携接続の取組を発表された八潮わかば幼稚園の研究の成果も区内で共有していきたいと考えています。","voiceIndex":413,"id":"exchange-180"},{"speaker":"大倉委員","kind":"質問・要望","question":"時間がないので、改めて別のところで伺いたいと思いますが、全然知らない子たちが小学生に上がるというところで、教員の理解とか、保育園もこういった学校で教えてくれているのだなという相互の理解が進むというところでは、非常にすばらしい取組だと私は思っておりますので、この取組がしっかり進むように、また改めて質問させていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":417,"id":"exchange-181"},{"speaker":"あくつ委員","kind":"質問・要望","question":"で別に答弁は求めませんから。真面目に生きてこられた方が不幸になってはならない、報われてほしい。所感です。では、質問に入ります。１３９ページ、区民交通傷害保険について伺ってまいります。なぜ歳入の款で伺うかと申しますと、この制度、区が窓口として募集をしているのですが、保険加入者数に応じて、保険会社である損保ジャパンから一定の割合で手数料が還付される、いわゆるキックバックがあります。","respondent":"工藤交通安全担当課長","answer":"この使用用途ですけれども、交通安全に資する活動に充当しているといったところです。最後に、令和６年度の見込みですけれども、おおむね３,２００名、事務手数料につきましても、令和５年度と同等額の約９０万円ということで見込んでいるところです。","voiceIndex":419,"id":"exchange-182"},{"speaker":"あくつ委員","kind":"提案","question":"２０１９年７月の実施までに、２０１７年から、私、これ、何度か議会でこの導入を求めてまいりました。そういったところで、やはり区が窓口となる保険が必要ではないかということで、保険会社とも相談をして、いろいろお話を聞いて提案をしたという経緯があります。本制度の意義について、品川区はどのようにお考えになっているのか教えてください。","respondent":"工藤交通安全担当課長","answer":"こちらの保険の意義ですけれども、やはり、先ほど委員ご説明のとおり、被害者も加害者も両方、事故によって不幸になるというところを、この賠償保険をもって経済的な負担を軽減させる、不幸にしないといったところで非常に重要なものだと考えておりますので。","voiceIndex":421,"id":"exchange-183"},{"speaker":"あくつ委員","kind":"質問・要望","question":"単年度、１年間の契約ですので、命と安全を守る制度としては、できる限り継続していただきたいと思いますので、リピーターが多いということは何よりかと思います。聞いてみますと、高齢者の方が多いということですが、７０代以上、自転車に乗らない人も結構入っているのです。本制度の課題についても伺ってまいります。それに伴う職員の事務負担があると聞きましたが、その点も教えてください。","respondent":"工藤交通安全担当課長","answer":"少し細かいところになるのですけれども、保険会社が受け取る通知書のサイズが決まっておりまして、これが所定の大きさ、２０ｃｍ掛ける８ｃｍぐらいの短冊みたいなものになっておるのですが、この形の大きさに切らないと。","voiceIndex":423,"id":"exchange-184"},{"speaker":"あくつ委員","kind":"提案","question":"これは情報戦略担当に伺いたいのですけれども、今回の金融機関から回ってくる区民交通傷害保険の手書きの申請書は、正にこういったデータ化に効力を発するのではないかと思うのですけれども、この点、検討されたのかどうかということが１つと、この技術を活用して、事務を軽減してはいかがでしょうかということで提案をしたいと思うのですが、いかがでしょうか。","respondent":"河西情報戦略担当課長","answer":"ご提案いただいた業務も、まだ我々のほうには要望は上がってきておりませんが、この中でデジタル化することにより、区民の利便性向上と業務の効率が図れる可能性がありますので、所管課の皆さんと検討を進めさせていただきたいと考えています。","voiceIndex":425,"id":"exchange-185"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１つ、加入促進の手法として、ウェブ募集の導入です。昨年の決算特別委員会の中で、ウェブ導入には課題があるというようなご答弁があったのですが、先行して導入している１６区のうちの４区、これは実際に増えているのです。これは２４時間申込みができる。これをぜひやっていただきたいのですけれども、この辺、検討していただきたいと思うのですけれども、交通安全担当課長のご見解を伺います。","respondent":"工藤交通安全担当課長","answer":"委員ご提案のウェブ申請の導入も含めまして、よりよい商品を提供できるように検討してまいりたいと思います。","voiceIndex":427,"id":"exchange-186"},{"speaker":"あくつ委員","kind":"質問","question":"サイクル安心保険の話も伺いましたけれども、これは残念ながらもらい事故には対応していないのです。いわゆる自転車専門の保険ですから、先ほど申し上げたように、高齢者の方が多いのは、区がやっていて安心、紙で書けるというところもあるので、ぜひ二本立てでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":429,"id":"exchange-187"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。１３１ページ、商店街活性化推進事業助成金、１２９ページ、健康増進事業費、８０ページ、使用料手数料についてお伺いします。これ、残念ながら、昨年の３月に閉店しました。商店街のシンボルと言ってもいいような建物だと思いますので、私としても、区に何らかの形で活用方法が何かあるのかということを、賛成なのですけれども、この件に対する区の見解をお尋ねしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"区といたしましても、地域のにぎわい創出、そして防災機能の強化、こちらの２点につきましては非常に重要と考えていますので、活用について前向きに検討しています。","voiceIndex":431,"id":"exchange-188"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"前向きに検討されるということで、具体的にどういった活用方法を想定しているのかということをお伺いしたいと思います。私は、あそこは駅前という立地を生かして、例えば、地元の方々とか、子育て世代の活動の場とか、いろいろ交流の拠点として活用もできると考えています。様々な活用の用途が考えられると思いますけれども、区の見解をお聞かせいただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"委員ご案内のとおり、様々な用途が考えられますので、要望をいただきまして、にぎわいの創出、こういったものに寄与できるように、地域の方々のご意見も伺いながら、引き続き検討を進めていきたいと思います。","voiceIndex":433,"id":"exchange-189"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"外国人支援という部分でいうと、私は、国際友好協会とか、そういう拠点としてもいいのかなと思っているのですけれども、様々な活用方法があると思うので、ぜひ地元の方々の要望を聞いていただいて、活用方法を検討していただきたいと思います。今現在、禁煙外来治療の今年の取組、来年度の取組、何か変化があったのかどうかをまず最初にお尋ねしたいと思います。","respondent":"若生健康課長","answer":"こちらにつきましては、禁煙治療に取り組んでいただいている場合に、その禁煙外来治療を実施している医療機関が行う治療について、支払った治療費および禁煙補助薬の購入費の一部を区が補助するというような事業でございまして、今年度１月末時点で、申請登録者数。","voiceIndex":435,"id":"exchange-190"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それで、ファイザー社のチャンピックスが、今、販売が休止になっていると思うのですけれども、これもまだ今、休止の状態に恐らくなっていると思うのです。このファイザー社のチャンピックスは、体に何か原因が生じて、今は治療制度をしていないということを、私、聞いたのですけれども、それを確認させていただきたいと思います。","respondent":"若生健康課長","answer":"ただ、これによって健康被害が出ているかというと、それは現在、確認はされておりませんが、現在、出荷停止が続いているということで、これは飲み薬ですけれども、これ以外の貼るパッチの薬ですとかは、今、問題なく出荷されておりますので。","voiceIndex":437,"id":"exchange-191"},{"speaker":"高橋（伸）委員","kind":"提案","question":"これは、コンテナ型ですと、やはり用地のこともありますし、当然コストもかかるという面でいうと、パネルフェンスもそうなのですけれども、あるいは、トレーラーハウスとか、これは機械換気で、換気扇での換気なのですけれども、それだと低価格で、多分、大きさにもよりますけれども、３００万円余ぐらいでも大体収まるのではないのかと私は思っているのですけれども、特に、受動喫煙に対して。","respondent":"河合生活安全担当課長","answer":"確かに、今、既存のコンテナ型のほうは、財政負担が大きくて課題が大きいと認識しております。委員ご指摘のとおり、トレーラー型とか、コストダウンの商品の発掘も含めて、そういった検討をしてまいりたいと思います。","voiceIndex":439,"id":"exchange-192"},{"speaker":"高橋（伸）委員","kind":"意見","question":"西大井の駅前、それぞれ西大井で活動している委員の方も当然いらっしゃると思いますけれども、あそこの場所は、場所としては指定喫煙になっているのですけれども、あそこも恐らく相当苦情があるとは思っております。お願いします。","respondent":"河合生活安全担当課長","answer":"引き続き、適正な設置に向けて検討してまいりたいと思います。","voiceIndex":441,"id":"exchange-193"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ西大井のほうを進めていただきたいと思います。よろしくお願いします。最後に、８１ページ、廃棄物処理手数料についてお尋ねします。内訳を見ると、事業系のごみ、粗大系のごみ、いずれも令和５年度よりも回収率の見込みを減らしているのですけれども、その理由と考え方をお尋ねしたいと思います。これが減収の主な要因になっているかと私は思うのですけれども、お尋ねをしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"予算は、ある程度一定に抑えていたのですけれども、そういった状況も見まして、今年度、減額を少しさせていただいているというような状況です。","voiceIndex":443,"id":"exchange-194"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、ごみの量が減るということは、当然、私も評価すべきと考えております。それによって不法投棄が増えることがあってはならないと思うのですけれども、不法投棄防止対策に対する今後の見込みというか、見通しはどういうふうに思われているのかということをお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"不法投棄ですけれども、基本的にやはり一番発生しやすい場所が、資源ごみを回収するところの資源ステーション、こちらに全体的に９割近く置かれているような状況です。","voiceIndex":445,"id":"exchange-195"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当にこれ、パトロールしていただいて、不法投棄をなくしていただきたいと思います。最後に、近年は、サーキュラーエコノミーという言葉に代表されるように、循環型の社会経済のシステムの構築が必要と思われますけれども、廃棄物の観点から、サーキュラーエコノミーの確立に向けた今後の取組をお尋ねしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"やはり一番大きいところはリサイクルのところかと思います。現在、ペットボトル、缶が、やはり皆さん、周知が徹底してきていまして、リサイクルが非常によく進んでいるところです。今後は、新たなリサイクル品目を探して、少しでもごみ量を減らしていきたいと考えております。","voiceIndex":447,"id":"exchange-196"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6687#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":129269,"voices":449}},{"id":"r06-20240305-10","meetingId":"r06-cm03","date":"2024年3月5日","dateIso":"2024-03-05","committee":"議会運営委員会","time":"午後 ６時０４分～午後 ６時１１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5542#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2361,"voices":22}}]);
